window.__D("text/torat-chaim/c017",{"p":[[2300540721,"לגילוי הנ\"ל, ולזה השיבו ה' אהרן אחיך ידבר כו' הוא יהי' לך לפה כו' [כי] אהרן הי' עיקר המדבר לזקני ישראל, וז\"ש ידעתי כי [דבר] ידבר מכבר להיותו בחי' שודמ\"ט לעורר לבב בנ\"י באה\"ר כנ\"ל וע\"כ יהי' לך לפה לקבל השפע דח\"ע הפנימי' ואתה תהי' לו לאלקי' לבחי' משפיע להמשיך לפיו כמ\"ש ושמת את הדברים בפיו<sup data-n=\"3727\">554</sup> כו'. ואע\"פ שאין זה ערך שיוכל לבוא פנימי' האור דח\"ע בסדר השתל' מהעלם לגילוי מטעם הנ\"ל אבל לזה הקדים בתחלה במ\"ש מי שם <span data-k=\"pg\">קיז</span> ּ פה לאדם כו', פי' דמה שיוכל לימשך מהעלם לגילוי בפה האדם מחכ' שבראש הלא גם זה הוא אנכי ה' כו' (שהוא בחי' התיקון), ע\"כ יוכל להיות ג\"ז שיומשך ג\"כ מפנימי' ח\"ע בפה דאהרן משום דאנכי אהי' עם פיך ועם פיהו כו', ואם<sup data-n=\"3728\">555</sup> ידבר הוא אליך<sup data-n=\"3729\">556</sup> לך אל העם כו' [הוא יהי' לך לפה ואתה תהי' לו לאלקי' בחי' משפיע כמו התגלות השפע מגילוי השכל בדיבור אע\"פ שהאור והשפע זאת היא באה מלמעלה מהשתלשלות דהעלם וגילוי כנ\"ל וד\"ל. וזהו שמתחלה כשאמר לו ואנכי אהי' עם פיך א' שלח נא<sup data-n=\"3730\">557</sup> כו'] וכשאמר לו אהרן אחיך יהי' נביאך<sup data-n=\"3731\">558</sup> לך לפה הוסכם לפי שאהרן שודמ\"ט כו' וכידוע דמשה ואהרן הן בחי' נו\"ה דאבא<sup data-n=\"3732\">559</sup> וע\"כ הקדים לפעמים אהרן למשה כו' וכמ\"ש ונחנו מה ש' מ\"ה<sup data-n=\"3733\">560</sup> דח\"ע כנ\"ל.\n<b>והנה</b> כדוגמא זאת דבחי' משה הנ\"ל יש ג\"כ עכשיו בכל דור ובכל זמן עם כל<sup data-n=\"3734\">561</sup> אדם מישראל וכמ\"ש בזהר דאתפשטותא דמשה בכל דרא<sup data-n=\"3735\">562</sup> כו' שהוא הנק' שוד\"מ שממשיך לבחי' אוא\"ס ב\"ה שבח\"ע למטה בדבור בגילוי בפה, והוא במצות ת\"ת שאדם חייב בכ\"י<sup data-n=\"3736\">564</sup><sup data-n=\"3737\">563</sup> לקבוע עתים לתורה בכ\"י לומר דבר הלכה<sup data-n=\"3738\">566</sup> ה' בפה<sup data-n=\"3739\">565</sup> דוקא והוא מ\"ש והיו הדברים האלה אשר אנכי מצוך כו' ודברת בם בשבתך כו' שזה ממש בחי' משה הנ\"ל. וביאור הענין, הנה כתי' ולקחתי אתכם<sup data-n=\"3740\">567</sup> לי לעם והייתי לכם לאלקים, פי' והייתי לכם לאלקים, היינו ע\"ד שאמר למשה הוא יהי' לך לפה ואתה תהי' לו לאלקי' שזה בחי' המשכה [דמשה] לאור ח\"ע לבא בגילוי [ב]פה דאהרן וכמ\"ש ושמת את הדברים בפיו כו', דאהרן הוא בחי' מקבל בפיו כל דברי אלקי' שנמשך ע\"י משה וע\"כ נק' אלקי' לגבי אהרן כנביא שמקבל דבר ה' בפיו כו', ולכך כאשר אמר והייתי לכם לאלקים, והיינו שבנ\"י יהיו בחי' מקבל אור שפע אלקי בפה שלהם והוא שיהי' לבחי' פה לדבר דבר ה' זו הלכה<sup data-n=\"3741\">568</sup> או מקרא כו' וכמ\"ש<sup data-n=\"3742\">569</sup> תען לשוני",[["3727","554","<b>ושמת את הדברים בפיו</b>: שמות ד, טו."],["3728","555","<b>ואם</b>: ט: ואז."],["3729","556","<b>אליך</b>: בד: ליתא."],["3730","557","<b>וד\"ל. . נא</b>: ניתוסף ע\"פ: ט."],["3731","558","<b>נביאך</b>: בד: ליתא."],["3732","559","<b>דמשה ואהרן. . נו\"ה דאבא</b>: ראה סידור שער בהמ\"ז קז, ב. מאמרי אדה\"א שמות ח\"ב ע' שלד וע' תקד. וש\"נ. נ\"ך ריש ע' תסו. קונטרסים ע' תלז. אגרות קודש חי\"ח ע' קיז."],["3733","560","<b>ש' מ\"ה</b>: בד: ממ\"ה."],["3734","561","<b>עם כל</b>: גט: ובכל. — ראה גם לקמן פ' בשלח קנו, ד. וש\"נ."],["3735","562","<b>דאתפשטותא דמשה בכל דרא</b>: ראה ת\"ז תס\"ט (קיב, רע\"א. קיד, רע\"א-ס\"א). תכ\"א (נ, ב). ב\"ר פנ\"ו, ז. מאמרי אדה\"א שמות ח\"ב ע' של וע' שצט."],["3736","564","<b>בכ\"י</b>: בד: ליתא."],["3737","563","<b>שאדם. . עתים לתורה בכ\"י</b>: ראה שו\"ע אדה\"ז חאו\"ח סקנ\"ה, ס\"א. הל' ת\"ת שלו פ\"ג, ה\"ד."],["3738","566","<b>הלכה</b>: בד: ליתא."],["3739","565","<b>לומר. . בפה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. קונטרסים ע' תקעג. וש\"נ. לקמן פ' בא קכה, א. בשלח רטז, ד. רלז, רע\"ג. יתרו רנו, א. תצוה שמט, ד."],["3740","567","<b>ולקחתי אתכם</b>: וארא ו, ז."],["3741","568","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["3742","569","<b>וכמ\"ש</b>: בד: וכמו. ט: או כמו."]]],[2300540733,"אמרתיך<sup data-n=\"3743\">570</sup> וכתיב למען תהי'<sup data-n=\"3744\">571</sup> תורת ה' בפיך [ודברי אשר שמתי בפיך<sup data-n=\"3745\">572</sup> ] וכה\"ג שאדם מדבר בד\"ת אינו רק בחי' כלי הפה שהוא המדבר ד' הנ\"ל<sup data-n=\"3746\">573</sup> כמו אהרן שהי' לפה למשה כנ\"ל, כך הוא ממש בדבר ה' שמדבר האדם ולומד איזה הלכה או מקרא [הרי] אותו דבור ד\"ת נק' בחי' פה לגבי אור ושפע ח\"ע שנמשך בדבר ה' זה שמדבר וזה ממש בחי' משה הנ\"ל, שהרי מה שנמשך ונשפע מאור ח\"ע שנק' מ\"ע בדבור זה [ד]ד\"ת הרי הוא נמשך ונשפע ע\"י משה דוקא שהוא הממוצע הדולה וממשיך מח\"ע לבא למטה בגילוי הדבור וכו'<sup data-n=\"3747\">574</sup> דכ\"ד ספרי' [ד]אוריי' נשאב מים הגדול דח\"ע וכמ\"ש ותמלא כדה ותעל, הרי עד\"ז ג\"כ כל הלכה והלכה בפרט נשאב ונמשך מח\"ע ע\"י משה ואפילו כל פרטי חידושי דינים שכל תלמיד ותיק עתיד לחדש<sup data-n=\"3748\">575</sup> הכל ניתן למשה מסיני. ונמצא דבחי' משה הוא המשפיע מח\"ע בדבור דד\"ת בכל אדם המדבר ד\"ת כמו שהי' אהרן לו לפה ונק' שודמ\"ל להמשיך גילוי אוא\"ס ממש בח\"ע דתו' הקדומה כו' שיבא ויתגלה בדבור [זה] בפרט, אך זהו דוקא כאשר לומד ד\"ת לשמה לשם התורה<sup data-n=\"3749\">576</sup> להמשיך גילוי אוא\"ס בדבר זה<sup data-n=\"3750\">577</sup> זו הלכה או מקרא כנ\"ל והיינו כאשר האדם הוא בבחי' ביטול כל עצמותו לגמרי שאינו רק בחי' כלי הפה לדבר ה' שמדבר כנ\"ל, וכמו ששליח המלך מדבר ומצווה בגזירתו מרצון<sup data-n=\"3751\">578</sup> המלך שיעשה כך ולא כך כו' שאינו אלא כלי להעלות ע\"י גילוי דבר המלך בפי המדבר והוא עצמו אינו כלום כו', כך הוא במצות ת\"ת הרי הוא רק כמספר ומדבר גזירת רצה\"ע <span data-k=\"pg\">236</span> ּ בכל דיני התו' כשר או פסול טמא או טהור חייב או זכאי כו', וה\"ז כמו שמצינו<sup data-n=\"3752\">579</sup> דבר המלך [ממש] לעשות כך ולא כך שהן דקדוקי דיני ההלכות באופן רצה\"ע במ\"ע ול\"ת כו'. וזהו שא' מתניתן מלכתא<sup data-n=\"3753\">580</sup> כמלך שמצוה וגוזר כך יוכשר וכך לא יוכשר כו' (ובזה יש יתרון מעלת [מצות] ת\"ת על כל המצות אע\"פ שהמעשה עיקר ומצות ת\"ת שמדבר<sup data-n=\"3754\">581</sup> אינו רק איך לעשות כו' הרי אמרו דת\"ת כנגד כולם<sup data-n=\"3755\">582</sup> ותלמוד גדול<sup data-n=\"3756\">583</sup> [מפני] שמביא לידי מעשה, והענין הוא לפי שהת\"ח<sup data-n=\"3757\">584</sup> היו עוסקים<sup data-n=\"3758\">585</sup> בתורה נק' שרי המלך שמודיעים אופן רצון המלך בשליחותו שהן במקומו של מלך עצמו ממש שהרי אינם רק בחי' כלי לדבר ה' וגזירתו ויש להם כח לגזור גזירות המלך כמו שרי מלוכה שניתן להם כח מרצון המלך כו', וא\"כ זהו יותר נעלה ממעשה המצוה עצמה שאינו אלא כעבד העושה מצות המלך וזהו העוסקים בתו' הוא כשר שמצווה בשם המלך ולכך יש כח",[["3743","570","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["3744","571","<b>למען תהי'</b>: בא יג, ט."],["3745","572","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["3746","573","<b>ד' הנ\"ל</b>: בד: דבר ה'."],["3747","574","<b>וכו'</b>: בד: וכנ\"ל."],["3748","575","<b>תלמיד ותיק עתיד לחדש</b>: נסמן לעיל פ' שמות ג, ב."],["3749","576","<b>לשמה לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"א שמות ח\"א ע' א. וש\"נ. שה\"א סט, ב ובהערה 26. לקמן פ' בשלח רלז א הערה 943. יתרו רנו, ג. משפטים רצ, ד. תצוה שנט, ג. ויקהל שצב, ד בשם הע\"ח. תיז, א."],["3750","577","<b>זה</b>: בד: ה'."],["3751","578","<b>בגזירתו מרצון</b>: בט: גזירות ורצון."],["3752","579","<b>שמצינו</b>: בדט: שמצוה. ט ניתוסף: ואומר."],["3753","580","<b>מתניתן </b>[ט: מתניתא]<b> מלכתא</b>: נסמן לעיל ע, א."],["3754","581","<b>שמדבר</b>: בד: ליתא."],["3755","582","<b>דת\"ת כנגד כולם</b>: פאה רפ\"א. ראה גם לקמן פ' תצוה שלו, א."],["3756","583","<b>ותלמוד גדול</b>: קידושין מ, ב. ראה גם לקמן פ' תצוה שלו, א."],["3757","584","<b>שהת\"ח. . שרי המלך</b>: נסמן לעיל י, ד."],["3758","585","<b>היו עוסקים</b>: בד: העוסקים."]]],[2300540745,"ב[יד] חכמי ישראל לג[ד]ור אופן רצון העליון כפי דעת[ם] להוסיף או לגרוע וכמו במלקות דגרעי חדא<sup data-n=\"3759\">586</sup> כו' וכה\"ג, וזהו שאמר ריב\"ז אני כשר<sup data-n=\"3760\">587</sup> לפני המלך כו' שר התו' וכמ\"ש במשה בכל ביתי<sup data-n=\"3761\">588</sup> הנק' יחו\"ע<sup data-n=\"3762\">589</sup> נאמן הוא כמו בעה\"ב<sup data-n=\"3763\">590</sup> עצמו לעשות כרצונו ממש ומבחי' משה נמשך לכל חכמי ישראל ולכך מתניתא מלכתא כמלך עצמו שגוזר כו' ולכך תלמוד גדול שמביא לידי קיום המעשה [וד\"ל]). וזהו ענין והיו הדברים האלה כו' אחר ואהבת של אה\"ר ע\"י אהרן שושדמ\"ט כו' דוקא<sup data-n=\"3764\">591</sup>, והוא מבחי' המשכות דחכ' עילאה<sup data-n=\"3765\">592</sup> שבעצמותו ית' כמ\"ש למשה<sup data-n=\"3766\">593</sup> בדיבור בפה והוא מ\"ש אשר אנכי מצוך כו' אנכי מי שאנכי<sup data-n=\"3767\">594</sup> סדכ\"ס למת\"ב כלל מצוך היום גוזר ואומר בפיך דברים האלה ע\"כ אמר ושננתם לבניך<sup data-n=\"3768\">595</sup> ודברת בם להיות גוזר ואומר דבר ה' כמו מתניתן מלכתא הנ\"ל, והיינו ע\"י בחי' משה שושדמ\"ל שממשיך גילוי אוא\"ס בדברים האלה אשר אנכי מצוך כו' לפה דכנ\"י כו' בדבור בד\"ת, [ו]לכך אנכי זה<sup data-n=\"3769\">596</sup> משה אמר על עצמו כי פתח דבריו שמע ישראל<sup data-n=\"3770\">597</sup> ה' אלקינו כו' ואהבת את כו' עד והיו כו' אשר אנכי מצוך כו' כמו תורה צוה לנו משה ([ל]היותו נמשך מח\"ע עצמה ממש כנ\"ל).\n<b>אך</b> הנה אין כנ\"י נעשים בחי' בית<sup data-n=\"3771\">598</sup> קיבול דבר ה' דתורה לקבל מאור ח\"ע עצמה ע\"י משה כ\"א ע\"י שיהיו תחלה בחי' בית קיבול מה<sup data-n=\"3772\">599</sup> לזה והוא ע\"י האה\"ר בכל נפשך ובכל מאדך כו', שהרי האומר אין לי אלא תו'<sup data-n=\"3773\">600</sup> אפילו תורה אין לו וכמו שאנו אומרים שב[ל]א התפ[עלות] אה\"ר במס\"נ באחד כו' גם כשיאמר דבר ה' זו הלכה לא נמשך כלל בחי' אור דח\"ע דתורה בפי המדבר כו' לפי שאין כלי הפה כלי בית קיבול כלל לקבל האור דח\"ע שבדיבור זה וזהו אפי' תורה אין לו, ולכך אחר שאמר ואהבת את ה' אז יהי' כלי הפה בית קיבול לדבר ה' לקבל האור דתורה שיהי' נמשך בפיו וכמ\"ש ואשים דברי בפיך כו'. וזהו ודברת בם שתהי' רק כלי [ה]פה לדבר [הוי'] המדבר בפיך וע\"כ מצות ת\"ת תמידי'<sup data-n=\"3774\">601</sup>, בשבתך בביתך ובלכתך בדרך כו' וכמ\"ש במ\"א <span data-k=\"pg\">קיח</span> ּ (ובזה יובן יותר ענין הנ\"ל במ\"ש מי שם פה לאדם כו' דהגם שאמר לו הוי' מי שם פה לאדם כו' ואנכי אהי' עם פיך לא רצה משה ואמר לו שלח נא כו' לפי שידע משה שלא יאיר [אור] דברי אלקי' [חיים] בכנ\"י ע\"י המשכה זו דאור חכ' עילאה דתורה לבדה כענין הנ\"ל במי שאין לו אלא תורה כו' כ\"א ע\"י שיהיו כנ\"ל כו' בלתי<sup data-n=\"3775\">602</sup> קיבול במס\"נ באה\"ר דכל נפשך ומאדך כנ\"ל ע\"כ גם שאמר ואנכי אהי' עם פיך שזהו כמו והיו",[["3759","586","<b>במלקות דגרעי חדא</b>: ראה מכות כב, א-ב."],["3760","587","<b>ריב\"ז אני כשר</b>: נסמן לעיל פ' שמות יא, ב."],["3761","588","<b>בכל ביתי. . נאמן הוא</b>: נסמן לעיל י, ד."],["3762","589","<b>הנק' יחו\"ע</b>: א: בית הון דח\"ע. בד: הנק' ח\"ע. ג: ליתא. ט: בית הון."],["3763","590","<b>בעה\"ב</b>: ג: ה'."],["3764","591","<b>כו' דוקא</b>: ניתוסף ע\"פ: גט."],["3765","592","<b>דחכ' עילאה</b>: ג: מ\"ע."],["3766","593","<b>כמ\"ש למשה</b>: גט: ממש למטה."],["3767","594","<b>אנכי מי שאנכי</b>: נסמן לעיל סג, ד."],["3768","595","<b>ושננתם לבניך</b>: ואתחנן ו, ז."],["3769","596","<b>זה</b>: ניתוסף ע\"פ: גט."],["3770","597","<b>שמע ישראל</b>: ואתחנן ו, ד."],["3771","598","<b>בית</b>: ב: כלי."],["3772","599","<b>מה</b>: בד: ליתא."],["3773","600","<b>האומר אין לי אלא תו'</b>: ראה יבמות קט, ב. לקמן פ' בשלח קסג, ג."],["3774","601","<b>מצות ת\"ת תמידי'</b>: ראה מנחות צט, סע\"ב. הל' ת\"ת לאדה\"ז פ\"ג, ה\"ז. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141021\" data-slug=\"likkutei-sichot\" data-id=\"1300141021\">לקו\"ש ואתחנן (כרך יד) ע' 21</a> ובהנסמן שם. לקמן פ' בשלח ריא, ד. תצוה שכד, א. שמו, ד. פקודי תנג, ב. תס, ב."],["3775","602","<b>כו' בלתי</b>: בד: בית."]]],[2300540757,"הדברים האלה אשר אנכי מצוך כו' מיאן בשליחותו זו כמ\"ש תחלה והן לא יאמינו לי<sup data-n=\"3776\">603</sup> ולא ישמעו בקולי ומטעם זה שלא איש דברים אנכי כו', אך כאשר אמר לו אהרן אחיך ידבר כו' והוא יהי' לך לפה ואתה תהי' לו לאלקים כו' [נתרצה] בדבר לפי שע\"י אהרן שהוא שושדמ\"ט יכול לעשות לכנ\"י בחי' בית קיבול לקבל אור דא\"ס ב\"ה בח\"ע דמ'<sup data-n=\"3777\">604</sup> ע\"י שנמשך בחי' אהרן דבכל נפשך כו' כנ\"ל וד\"ל).\n<b>ובכ\"ז</b> יובן מה שהשיב ה' למשה עמ\"ש לא איש דברים אנכי כי כ\"פ כו' מי שם פה לאדם כו', והנה תי' לאדם נקוד בקמץ תחת הלמ\"ד דמשמעו לאדם הידוע<sup data-n=\"3778\">605</sup> שהוא לבחי' אדה\"ע שעל כסא [הכבוד] כמ\"ש ועה\"כ דמות<sup data-n=\"3779\">606</sup> כמראה אדם כו', דהיינו בחי' מדות דאצי' שנמשך לבחי' דבה\"ע שנק' פה העליון כמו ויאמר אלקי' יהי אור<sup data-n=\"3780\">607</sup> כו' כי בדבר ה' כו' וברוח פיו<sup data-n=\"3781\">608</sup> כו' וכמ\"ש בס\"י וקבען בפה שהן כ\"ב אותיות שיוצאות מה' מוצאות הפה שנתגלו ביו\"ד מאמרות [וכל] פרטי צירופי אותיות שמהן נבראו כל העולמות עליונים ותחתונים מאין ליש כידוע, שזה[ו] שנאמר ואתה מחי' את כולם א\"ת וה' מוצאות הפה כו' וד\"ל<sup data-n=\"3782\">609</sup> אמרו בה' בראם<sup data-n=\"3783\">610</sup> כו' וע\"ז אמר מי שם פה לאדם העליון כו' הלא אנכי ה' כו' וד\"ל. וביאור הענין הנה ידוע דעצמות אוא\"ס ב\"ה הוא אח\"פ בתכלית וכמ\"ש אנת חד ולא בחושבן<sup data-n=\"3784\">611</sup> כו' דהיינו לא בחושבן יו\"ד ספי' וכמ\"ש חכים ולא בחכ' ידיעא כו' עד ולאו מכל אינון מדות כלל, וע\"כ אמר ועל הכסא דמות כמראה אדם ולא אדם ממש דאדם הוא בחי' מוחין ומדות שכולל ע\"ס דכח\"ב וחג\"ת כו' ובאמת לאו דאית לי' מכא\"מ כלל שע\"י האור<sup data-n=\"3785\">612</sup> העצמ[ות] האציל ע\"ס להיות נק' חכים ומבין כו' וכמ\"ש אפיק' יו\"ד תיקונין וקרית לון יו\"ד ספירן כו' רק לאחזאה לאתנהגא בהון עלמין כו' עלמין סתימין כו' ועלמין דאתגליין, פי' שכל מה שצמצם א\"ע להאציל ע\"ס באו\"כ אינו רק כדי שיהי' מקור להנהגת העולמות במדות דחב\"ד<sup data-n=\"3786\">613</sup> כו' ולהיות מהם מקור שפע חיי כל העולמות אבל מצד עצמו הרי הוא למעלה מעלה מכל ההשתלשלו' דע\"ס וכמ\"ש בס\"י עשר ספי' בלי מ\"ה<sup data-n=\"3787\">614</sup> בלי מהות כו' כידוע. וז\"ש מי שם פה לאדם [העליון שהרי מה שנאצל ע\"י<sup data-n=\"3788\">615</sup> או\"כ בבחי' אדם היינו רק בשביל שפע מציאות העולמות לבד כנ\"ל, והוא אשר האציל לבחי' מוחין ומדות דאדם דאצי' הרי הוא ית' שם פה לאדם] זה והוא בחי' דבור העליון שזהו בחי' התגלות מדותיו שבלב האדם העליון לבוא בגילוי הדיבור בה' מוצאות הפה העליון כו' להיות",[["3776","603","<b>והן לא יאמינו לי</b>: שמות ד, א."],["3777","604","<b>זה. . דמ'</b>: בד: ליתא. . דתורה."],["3778","605","<b>לאדם נקוד בקמץ. . לאדם הידוע</b>: ראה גם לעיל פ' שמות מז, ד. וש\"נ."],["3779","606","<b>ועה\"כ דמות</b>: יחזקאל א, כו [בדילוג — ראה מאמרי אדה\"ז תקע\"א ע' עז. מאמרי אדה\"א שמות ח\"ב ע' תעב. וש\"נ. שע\"ת יא, ד ובהערה 21]."],["3780","607","<b>ויאמר. . אור</b>: בראשית א, ג."],["3781","608","<b>בדבר. . פיו</b>: תהלים לג, ו."],["3782","609","<b>וד\"ל</b>: בד: ורז\"ל. ט: וכן."],["3783","610","<b>בה' בראם</b>: ראה גם לעיל לד, א. וש\"נ."],["3784","611","<b>אנת חד ולא בחושבן</b>: ראה ת\"ז בהקדמה (יז, א)."],["3785","612","<b>שע\"י האור</b>: ט: רק ע\"י צמצום אור."],["3786","613","<b>דחב\"ד</b>: בד: דחג\"ת. גט: דחד\"ר דחסד דין רחמים."],["3787","614","<b>עשר ספי' בלי' מ\"ה</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["3788","615","<b>ע\"י</b>: ט: ע\"ס."]]],[2300540769,"בדבר ה' שמים נעשו מאין ליש כמו ע\"י מאמר יהי רקיע<sup data-n=\"3789\">616</sup> כו' נתהוה הרקיע מאין ליש, וכה\"ג בכל המאמר[ו'] וצירופי אותיות המסתעפי' ומשתלשלי' ע\"י יו\"ד מאמרות בעולמות עליונים ועולמות תחתונים עד התהוות דצח\"מ דעשי' כידוע (וכמו למטה באדם התחתון שעיקר גילוי אורות וכחות הנפש דאדם הוא מבחי' הדבור בפה שעי\"ז נק' בחי' מדבר נפש המדברת<sup data-n=\"3790\">617</sup> כו'), ואמר הלא אנכי ה' שהיינו על התו' שנק' מ\"ה<sup data-n=\"3791\">618</sup> <span data-k=\"pg\">238</span> ּ לעולם הנאצל ולעולם הנברא כו' וכמ\"ש ה' קנני ראשית דרכו<sup data-n=\"3792\">619</sup>, פי' ראשית דרכו להאציל ולברוא כו' שהן ד' אותיות הכלולים בשם הוי' יו\"ד באצי'<sup data-n=\"3793\">620</sup> ה' בבריאה ו' ביצי' ה' בעשי' הכל בא מעצמיות<sup data-n=\"3794\">621</sup> חכ' הקדומה שהוא ח\"ע שבתו' הקדומה וכמאמר בראשית בשביל התורה<sup data-n=\"3795\">622</sup> שנק' ראשית [שנא'] ה' קנני כו', וכן אמר בזהר דאסתכל באורייתא וברא עלמ[א]<sup data-n=\"3796\">623</sup> והיינו שהסתכל באותיות התורה הקדומה וכמ\"ש ואהי' אצלו אמון אומנא<sup data-n=\"3797\">624</sup> כו' כמו האומן הבונה מן ציור הלוח כו' וכמ\"ש במ\"א. מזה<sup data-n=\"3798\">625</sup> יובן ג\"כ דכל מה שהאציל ע\"ס כאו\"א עד בחי' דבור העליון שנק' פה לאדם כו' הכל הוא ע\"פ חכמה שבתו' הקדומה דוקא, וכמ\"ש מי מדד<sup data-n=\"3799\">626</sup> כו' שהוא ע\"פ מאמר קו המדה דקו וחוט ש[נ]משך במדה בכל<sup data-n=\"3800\">627</sup> האצי' באו\"מ ואו\"פ עד גם במל' דאצי' שנק' פה הוא הנמשך ע\"פ רצון העצמי' של המאציל ב\"ה כפי הקריאה שקרא באותיות התו' שקדמה לעולם אלפים שנה<sup data-n=\"3801\">628</sup> כו', עפ\"ז<sup data-n=\"3802\">629</sup> הי' אופן התחלקות הי' מא[מרו'] בה' מוצאות הפה [ה]עליון כמשל אומן שרואה וקורא בלוח כך מצווה לעשות הבנין לא יוסיף ולא יגרע כו', וכידוע שזהו פי' בראשית בחוכמתא<sup data-n=\"3803\">630</sup> כמ\"ש בחכ' יבנה בית<sup data-n=\"3804\">631</sup> והוא ב' דבראשית<sup data-n=\"3805\">632</sup> דבראשית נמי מאמר הוא<sup data-n=\"3806\">633</sup> דע\"ז א' במאמר א' יכול להבראות<sup data-n=\"3807\">634</sup> הכל כו' והוא מ\"ש כולם בחכ' עשית<sup data-n=\"3808\">635</sup> כו', אך מאמר זה דבראשית נמשך מח\"ע דתורה הקדומה דאסתכל באוריי' כו' (וכמ\"ש במ\"א בענין יו\"ד הדברות שהן מקורים אמיתים לי' מאמרות<sup data-n=\"3809\">636</sup> שהוא שא' תנאי הי' עם וימ\"ב<sup data-n=\"3810\">637</sup> כו' וכמ\"ש בזהר), ונק' מאמר זה דבראשית מאמר פתוח שבא בדיבור לגילוי בי' מאמרות כמו עד\"מ השכל שיתגלה בכלי המוח שיוכל לבוא בדבור בפה, אבל מאמ' דאותיות התו' דח\"ע<sup data-n=\"3811\">639</sup> הקדומה נק' מאמר סתום<sup data-n=\"3812\">638</sup> חכ'<sup data-n=\"3813\">640</sup> דחכים ולא בחכ'",[["3789","616","<b>יהי רקיע</b>: בראשית א, ו."],["3790","617","<b>נפש המדברת</b>: ראה גם ז\"ח (מדרש הנעלם) בראשית ו, ד. ט, א. רמב\"ן בראשית ב, ז. ג, כב. פירוש להל' יסודה\"ת פ\"ד, ה\"ח. פירוש המלות זרות לר\"ש תבון למו\"נ. לקמן פ' בא קח, ד. קלב, ג פקודי תס, ג. שה\"א מב, ב ובהערה 23."],["3791","618","<b>שהיינו. . מ\"ה</b>: בד: והיינו ע\"י התורה שקדמה."],["3792","619","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["3793","620","<b>יו\"ד באצי'</b>: נסמן לעיל פ' שמות כד, ד הערה 62."],["3794","621","<b>מעצמיות</b>: ט: מאמצעות."],["3795","622","<b>בראשית בשביל התורה</b>: בראשית א, א. ראה רש\"י שם. הנסמן בלקו\"ש נח (כרך ג) ע' 755."],["3796","623","<b>דאסתכל באורייתא וברא עלמ[א]</b>: ראה זהר תולדות קלד, א. תרומה קסא, א. מאמרי אדה\"א דברים ח\"א ע' רעט."],["3797","624","<b>אמון אומנא</b>: ראה ב\"ר בתחלתו. תו\"ח בראשית ז, א ואילך."],["3798","625","<b>מזה</b>: ט: ולזה."],["3799","626","<b>מי מדד</b>: ישעי' מ, יב."],["3800","627","<b>מאמר. . בכל</b>: ניתוסף ע\"פ: ט."],["3801","628","<b>התו' שקדמה. . שנה</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["3802","629","<b>עפ\"ז</b>: ט: ולפ\"ז."],["3803","630","<b>בראשית בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א."],["3804","631","<b>בחכ' יבנה בית</b>: משלי כד, ג. ראה גם לקמן פ' בשלח קלה, ג. תצוה שמב, א."],["3805","632","<b>והוא ב' דבראשית</b>: ניתוסף ע\"פ: ט."],["3806","633","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."],["3807","634","<b>במאמר א' יכול להבראות</b>: אבות רפ\"ה. ראה מאמרי אדה\"א דברים ח\"ב ע' תעז. וש\"נ. קונטרסים ע' תקלו. וש\"נ. לקמן פ' יתרו רנב, ב."],["3808","635","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["3809","636","<b>יו\"ד הדברות. . לי' מאמרות</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. שע\"ת מא, ב ובהערה 19. ראה גם לקמן פ' בא קכו, ב. בשלח קסג, ב."],["3810","637","<b>תנאי הי' עם וימ\"ב</b>: ראה שבת פח, א."],["3811","639","<b>דח\"ע</b>: ניתוסף ע\"פ: ט."],["3812","638","<b>מאמר פתוח. . מאמר סתום</b>: נסמן לעיל פ' שמות יב, ב."],["3813","640","<b>חכ'</b>: גט: דח\"ס."]]],[2300540780,"ידיעא כו', וזהו בחכ' יבנה [בית כו'] כמאמר<sup data-n=\"3814\">641</sup> הקדומה שבעצמות המאציל יבנה בית דבראשית שהוא מה שכולם בחכ' עשית כו' וד\"ל. וזהו פיה פתחה בחכ' ותורת חסד על לשונה פי' מה שפיה פתחה בחכ' דמע\"ב הרי מזה בא ונמשך מהעלם דחכ' [ד]תורה הקדומה והיינו מפני טעם הנ\"ל שהתחלקות הי' מאמרות בפה העליון מקורו הוא באותיות דתורה שקדמה לעולם, וזהו משה\"כ<sup data-n=\"3815\">642</sup> ותורת חסד [על לשונה] פי' מפני שתו' חסד דתו' הקדומה על לשונה לישנא דאורייתא דוקא משום דאסתכל באורייתא וברא עלמין (והוא ענין תושב\"כ שנק' לה\"ק<sup data-n=\"3816\">643</sup> והוא מ\"ש וזאת תורת האדם<sup data-n=\"3817\">644</sup> האדם עליון מטעם הנ\"ל, ופה הוא תושבע\"פ מל' קרינן לה<sup data-n=\"3818\">645</sup>, וז\"ש פיה פתחה בחכ' דתושבע\"פ שהוא עיקר קיום הי' מאמרות בפה ודיבור להוות העולמות מאין ליש וע\"כ הת\"ח נק' בונים<sup data-n=\"3819\">646</sup> שעוסקים בבניינו של תורה<sup data-n=\"3820\">647</sup> כמ\"ש בחכ' יבנה כו' כמ\"ש במ\"א).\n<b>וזהו </b>מי שם פה לאדם כו' ואמ' הלא<sup data-n=\"3821\">648</sup> אנכי מעצמות המאציל (ומ\"ש או אלם הוא בחי' קטנות הדבור והוא אלם מאלקים<sup data-n=\"3822\">649</sup> נאלמתי<sup data-n=\"3823\">650</sup> כו') שמזה עיקר קיום העולמות מטעם הנ\"ל שזה נמשך מדבור דתו'<sup data-n=\"3824\">651</sup> וגם עכשיו הרי דבריו חיים וקיימים<sup data-n=\"3825\">652</sup> בכל דור ובכל זמן שאדם לומד איזה הלכה ופסוק הרי זהו דבר ה' ממש כמ\"ש ואשים דברי בפיך<sup data-n=\"3826\">653</sup> לנטוע שמים וליסוד ארץ כו' שמזה קיום שמים וארץ לפי שמזה דוקא מתחדש אור דשפע דח\"ע דתורה בדבור דיו\"ד מאמ' למעלה וע\"כ אין העולם מתקיים אלא בהבל תינוקות <span data-k=\"pg\">קיט</span> ּ שב\"ר שהוא הבל שאין בו חטא<sup data-n=\"3827\">654</sup> (וזה הי' התוכחה שהוכיח ה' למשה שאע\"פ שהוא כבד פה ולשון תשב\"כ ושבע\"פ מפני היותו בפנימי' הח\"ע דמ\"ע הנ\"ל, אבל מי שם פה כו' א\"כ גם אנכי אהי' עם פיך שהוא בחי' דבור דתו' הקדומה שיוכל לבא למטה לזקני ישראל, ועכ\"ז לא רצה בזה לפי שידע שלא יקבלו בנ\"י כ\"א ע\"י אהרן שודמ\"ט כו' שיהי' לו פה והוא אחר מס\"נ בואהבת דייקא אז והיו הדברים כו' ודברת בם ע\"י משה דוקא כו'), ובכ\"ז יובן מ\"ש הוא אהרן ומשה אשר אמר ה' להם הוציאו כו' אחר אה\"ר דכל נפשך כו' שנעשה ע\"י אהרן שודמ\"ט כו' א[ז] ראוים ב\"י להיות לפה לגבי משה שהוא הדבור בד\"ת וכמ\"ש והיו הדברים האלה אשר",[["3814","641","<b>כמאמר</b>: ט: בחכמה."],["3815","642","<b>משה\"כ</b>: בד: שא'."],["3816","643","<b>לה\"ק</b>: בד: לשון."],["3817","644","<b>וזאת תורת האדם</b>: שמואל-ב ז, יט."],["3818","645","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["3819","646","<b>הת\"ח נק' בונים</b>: נסמן לעיל ד, ג הערה 193."],["3820","647","<b>תורה</b>: בד: עולם."],["3821","648","<b>וזהו. . כו' ואמ' הלא</b>: ט: וז\"ש. . בד: בי' מאמרו' הכל."],["3822","649","<b>אלם מאלקים</b>: נסמן לעיל יט, ג."],["3823","650","<b>נאלמתי</b>: תהלים לט, ג."],["3824","651","<b>דתו'</b>: ט: דד\"ת."],["3825","652","<b>דבריו חיים וקיימים</b>: ע\"פ ברכת אמת ויציב."],["3826","653","<b>ואשים דברי בפיך</b>: ישעי' נא, טז [בדילוג]."],["3827","654","<b>אין העולם. . שאין בו חטא</b>: ראה שבת קיט, ב. מאמרי אדה\"א דברים ח\"א ע' קמ. וש\"נ. הנחות תקע\"ז ע' סח. וש\"נ. לקמן פ' בשלח ריא, ד יתרו רנו, ב. רעו, ג."]]],[2300540791,"אנכי מצוך כו' ודברת בם שהוא המשכת בחי' מ\"ע [שנק'] מ\"ד מ[י]ין דאורייתא שנמשך ע\"י משה דוקא כנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שבפ' קדש<sup data-n=\"3828\">655</sup> דק\"ש שמע ישראל והי' א\"ש<sup data-n=\"3829\">656</sup> כו' משה א' לבנ\"י מפי עצמו ואיך אמר בפ' שמע אשר אנכי מצוך היום כו', ובפ' שני' אמר ונתתי מטר ארצכם<sup data-n=\"3830\">657</sup> כו' והלא ה' נותן מטר כו', אך הענין הוא לפי שבחי' משה הוא בחי' מ\"ה דח\"ע ממש שע\"י נמשך דוקא כנ\"ל וע\"כ יכול לומר אנכי מצוך כו' ונתתי מטר כו' וד\"ל. אך בתנאי כאשר תשמעו אל מצותי [כו'] לאהבה את ה' בכל לבבכם ובכל נפשכם אז ונתתי מטר ארצכם כו' שהוא בהמשכת מ\"ד דמ\"ע דאוריי', וזהו ואספת דגנך זה תלמוד<sup data-n=\"3831\">658</sup> ותירושך זה סודות התורה שנק' יינה ש\"ת<sup data-n=\"3832\">659</sup> ויצהריך הוא בחי' תעלומות ח\"ע<sup data-n=\"3833\">660</sup> שנק' שמן כידוע בענין יין ושמן כנ\"ל וד\"ל. ופי' הפשוט דואספת דגנך כו' מדבר במצות הצדקה שכולל כל המצות וכמ\"ש וצדקה תהי'<sup data-n=\"3834\">663</sup> לנו כי נשמור לעשות את<sup data-n=\"3835\">664</sup> כו', וע\"כ נק' צדקה בשם זריעה כמ\"ש זרעו לכם לצדקה וקצרו לפי חסד [וכן] זורע צדקות<sup data-n=\"3836\">666</sup> [כו'] והוא בקיום כל המצות שנק' בשם זריעה אז יקצרו לפי חסד שזה[ו ש]נאמר ואספת דגנך כו', וכמו שהמצות הצדקה<sup data-n=\"3837\">667</sup> והחסד שבגשמיות דוקא נמשך ברכה במעשה ידיו בגשמיות כך זורע צדקות ע\"י מצות מעשיות מצמיח ישועות וחסדים עליונים וכו' וכמ\"ש וקצרו לפי חסד וכו' וד\"ל. ושרש הענין הוא לפי שקדם תחלה מ\"מ תחלה<sup data-n=\"3838\">668</sup> ונתתי מטר ארצכם שמטר זה היינו בחי' המשכות מ\"ע [ד]אור תו' ששורש התורה הוא בבחי' מים והוא בבחי' חסד העליון כמ\"ש ותורת חסד על לשונה<sup data-n=\"3839\">669</sup> לישנא דאוריי' כו' כנ\"ל, שכל שפע חסד שנמשך לעולמות כמ\"ש כי אמרתי עולם חסד יבנה וכו' היינו מח\"ע דתו' להיות ג\"כ בבחי' חסד דוקא וע\"כ נק' תו' חסד כו', וז\"ש פיה פתחה בחכ' דהיינו גילוי אור חכ' דתו' [ב]חכ' שבמע\"ב לפי שתורת חסד דוקא על לשונה מטעם הנ\"ל. וע\"כ אמר ונתתי מטר ארצכם במ\"ע דאוריי' שהוא ע\"י משה דוקא כמ\"ש בו<sup data-n=\"3840\">672</sup> כי מן המים משיתיהו בבחי' מ\"ע דחכ\"ע כנ\"ל אז ממילא ואספת דגנך כו' והוא ענין הקצירה שהוא לפי חסד העליון דח\"ע, והיינו ע\"י הזריעה שבמצות שהוא ג\"כ ע\"י מי החסדים עליונים כמ\"ש<sup data-n=\"3841\">673</sup> כאשר ירד הגשם כו' והרוה<sup data-n=\"3842\">674</sup> את",[["3828","655","<b>שבפ' קדש</b>: בד: שב' פרשיות הללו."],["3829","656","<b>והי' א\"ש</b>: עקב יא, יג."],["3830","657","<b>ונתתי מטר ארצכם</b>: עקב שם, יד. ראה גם לקמן פ' תצוה שסג, א."],["3831","658","<b>ואספת דגנך זה תלמוד</b>: שם יא, יד. ראה ב\"ר פס\"ו, ג. מאמרי אדה\"א במדבר ח\"ב ע' תרמד. דברים ח\"א ע' רצה ובהנסמן לשם."],["3832","659","<b>ותירושך. . יינה ש\"ת</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסו ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"א ע' רמה ואילך. נ\"ך ע' סה. וש\"נ."],["3833","660","<b>ויצהרך. . תעלומות ח\"ע</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה שם. מאמרי אדה\"א דברים שם. תו\"ח ויצא קסה, רע\"ג."],["3834","663","<b>הצדקה. . וצדקה תהי'</b>: נסמן לעיל פ' שמות יד, א."],["3835","664","<b>לעשות את</b>: ניתוסף ע\"פ: ט."],["3836","666","<b>זורע צדקות</b>: ברכת יוצר. — בתו\"ח באות תיבות אלו לפני התיבות ”כמ\"ש זרעו\" ותוקן כאן ע\"פ בדט."],["3837","667","<b>שהמצות הצדקה</b>: ט: שע\"י צדקה."],["3838","668","<b>מ\"מ תחלה</b>: בד: ליתא. ט: מ\"ש."],["3839","669","<b>ותורת חסד על לשונה</b>: משלי לא, כו."],["3840","672","<b>בו</b>: ניתוסף ע\"פ: ט."],["3841","673","<b>כמ\"ש</b>: ט: וזהו מ\"ש."],["3842","674","<b>כאשר. . והרוה</b>: ישעי' נה, י [ושם: כי אם הרוה — ראה מאמרי אדה\"א הנחות תקע\"ז ע' רכ. וש\"נ]."]]],[2300540801,"הארץ כו' כן דברי<sup data-n=\"3843\">675</sup> וכו' וכמו שבצדקה כ[תוב] זרעו לכם לצדקה וכו' וכתי' אשריכם זורעי על כל מים והוא מים דאוריי'<sup data-n=\"3844\">676</sup> זש\"כ ונתתי מטר ארצכם בעתו כו' אך [ש]תשמעו אל כל מצותי כו' שהוא ענין הזריעה דהיינו לפי שהמצות שהן הח' וכו' <span data-k=\"pg\">240</span> ּ ותורה וצדקה בכל<sup data-n=\"3845\">677</sup> ענין ומדריגה אחת והוא בבחי' חסדים העליונים וכידוע דתו' וגמ\"ח הכל א' שהוא מבחי' מים וחסדים עליונים ע\"כ הא בהא תליא שע\"י המצות נמשך מטר דאורייתא וע\"י המטר ואספת כו', וזהו שב' פרשיות הללו משה דוקא אמרן לישראל לפי שמן המים משיתיהו כו' וד\"ל.\n<b>הם</b> המדברים אל פרעה כו' הוא משה ואהרן, הנה ידוע הדקדוקים בפסוקי' אלה והוא מה שהזכיר בתחלה אהרן ואח\"כ משה באמרו הוא אהרן ומשה כו' ובסיום דברי' אמר הוא משה ואהרן, והתירוץ הוא לפי שלגבי זקני ישראל יהי' אהרן עיקר המדבר כמ\"ש בפ' שמות ודיבר הוא אל העם והוא יהי' לך לפה ואתה תהי' לו לך<sup data-n=\"3846\">678</sup> לאלקים וכמ\"ש וילך משה ואהרן<sup data-n=\"3847\">679</sup> ויאספו את כל זקני ישראל וידבר אהרן את כל הדברים האלה<sup data-n=\"3848\">680</sup> אשר דיבר ה' [אל] משה ויעש האותות כו' ויאמן העם<sup data-n=\"3849\">681</sup> כו' ואח\"כ באו<sup data-n=\"3850\">682</sup> משה ואהרן אל פרעה כו', אבל לגבי פרעה הי' משה עיקר המדבר וכמ\"ש בכאן ויאמר ה' אל משה ראה נתתיך<sup data-n=\"3851\">683</sup> אלקים לפרעה ואהרן אחיך יהי' נביאך, פי' נביאך כמו מתורגמן<sup data-n=\"3852\">684</sup> לבד לפרש ולבאר דבריו ולא שיהי' [לו] לפה ממש שהרי אמר למשה אתה תדבר<sup data-n=\"3853\">685</sup> את כל אשר אצוך ואהרן אחיך ידבר אל פרעה היינו רק כמו מתורגמן לבד, וזהו שלגבי הדבור אל פרעה הזכיר משה ואח\"כ אהרן וכמ\"ש הם המדברים אל פרעה כו' הוא משה ואהרן לפי שמשה עיקר המדבר כו' ולגבי זקני ישראל הי' אהרן עיקר המדבר וזה פלאי לכאורה דהי' ראוי להיות להיפוך דלזקני ישראל שיאמינו הי' מהראוי שיהי' משה עיקר המדבר ולגבי פרעה די באהרן כו' ובכאן נהפך הוא<sup data-n=\"3854\">686</sup>. אך הנה הענין הוא דלגבי פרעה דוקא הי' צריך שיהי' משה דוקא עיקר המדבר ולזקני ישראל צ\"ל<sup data-n=\"3855\">687</sup> אהרן עיקר המדבר.\n<b>וטעם</b> הדברים הנה תחלה י\"ל שורש בחי' פרעה שהוא אותיות עורף<sup data-n=\"3856\">688</sup> והוא בחי' אחוריים המנגד לכת\"ר דקדושה",[["3843","675","<b>כן דברי</b>: ישעי' שם, יא [בדילוג]."],["3844","676","<b>אשריכם זורעי. . מים דאוריי'</b>: ישעי' לב, כ. ב\"ק יז, א."],["3845","677","<b>זש\"כ. . אך. . בכל</b>: ט: וז\"ש. . אחר. . הכל."],["3846","678","<b>לך</b>: ניתוסף ע\"פ: ט."],["3847","679","<b>וילך משה ואהרן</b>: שמות ד, כט."],["3848","680","<b>וידבר אהרן. . האלה </b>[בדט ליתא]: שמות ד, ל."],["3849","681","<b>ויאמן העם</b>: שמות שם, לא."],["3850","682","<b>ואח\"כ </b>[ט: ואחר]<b> באו</b>: שמות ה, א."],["3851","683","<b>ויאמר. . ראה נתתיך</b>: וארא ז, א."],["3852","684","<b>נביאך כמו מתורגמן</b>: ת\"א ורש\"י עה\"פ."],["3853","685","<b>למשה </b>[ט: למטה]<b> אתה תדבר</b>: וארא ז, ב."],["3854","686","<b>הוא. . הוא</b>: ניתוסף ע\"פ ט. ג: כו'. . ניתוסף ע\"פ: גט."],["3855","687","<b>ולזקני. . צ\"ל</b>: גט: ולגבי זקני. . ניתוסף ע\"פ: גט."],["3856","688","<b>פרעה. . עורף</b>: נסמן לעיל פ' שמות יט, ב."]]],[2300540811,"שהוא תוקף וקושי וגסה\"ר כתרגום קשה עורף [קשי קדל]<sup data-n=\"3857\">689</sup>, שכל קושי וגסות ועביות הוא [ב]עורף דוקא להיותו המנגד לבחי' ביטול והכנעה של [ה]רצון [ו]נק' גסות הרוח כי רוח האדם היא העולה בבחי' ביטול והכנעה לאלקות והעורף הוא בהיפוכו ממש שהוא העומד במעמדו ותקפו מאד לבלתי יוכל להכנע לעולם ואינו מתפעל ואינו ניזוז ממקומו כלל משום דבר גדול ונורא יהי' מה שיהי' כו' עד\"מ הידוע<sup data-n=\"3858\">690</sup> שהוא קשה מאד וכמ\"ש כי עם קשה עורף אתה<sup data-n=\"3859\">691</sup> כו', וכמו שאנו רואים בטבע בני אדם שיש הרבה בנ\"א שהם קשים מאד שלא יזיזו אותו ממקומו בכל דבר שבעולם לא ברך ולא בקשה כי גם שיבטשו אותו ביותר לא יכנע כלל וכלל כי אין לבו נשבר משום דבר בעולם, וכמו שיש אנשים שהולכים בשרירות לבם רק רע אף שלפעמים יגיע עליו ביטוש גדול בבני חיי ומזוני לא יפול לבו ולא ישבר ולא יכנע כלל וכלל, [ו]הוא מצד גסות [ועבות שנק' גסי] הרוח שהרוח שלו גס ועב ביותר ורחוק מאד מבחי' הביטול והזזה ממקומו והן הנק' עזי פנים<sup data-n=\"3860\">692</sup> שהוא עז וקשה ביותר עד שהוא קשה<sup data-n=\"3861\">693</sup> כברזל ממש שלא יפול לבו משום דבר שבעולם וכנ\"ל [וכמ\"ש] שמעו אלי אבירי לב<sup data-n=\"3862\">694</sup> הרחוקים מצדקה כו'. ושרש קושי הלב בזה שקשה כאבן ממש הוא בא מבחי' קושי העורף דוקא והוא מצד שורש<sup data-n=\"3863\">695</sup> הרבה נשמות ששרשם בבחי' עורף ולא <span data-k=\"pg\">קכ</span> ּ פנים כו', כידוע שיש בכלל ציור קומה דכנ\"י גם בחי' עורף לנגד הפנים, ע\"כ יש שם<sup data-n=\"3864\">696</sup> גם בעבודת ה' הרבה נשמות בישראל ששרשם מבחי' עורף דקדושה כו' שלזה גם שרוא[ים] בראיית השכל ובהשגה והתבוננו' בגדולת ה' עכ\"ז לא יהי' בהם התפעלו' אלקות באוי\"ר להיות ניזוז ממקומו בהתפשטו' וביטול כל עצמותו כלל וכלל, כי לא תעלה נפשו בביטול היש לאין [ה]אלקי כלל רק עומד במהותו וטבעו בתוקף מעמדו בלתי הזזה ממהותו כלל וכלל וזה מצד גסות ועבות רוח[ו] בשרשו בבחי' עורף הקדושה וזהו שכ' כי עם קשה עורף [כו'] (ואפי' לשוא לא ישא את נפשו). ועכ\"ז יש בזה מעלה יתירה והוא בחי' העקשות והנצחון בעבודת ה' שמחמת תוקף וקושי רוחו דוקא אם יוסכם אצלו דבר מה כמו מקבלת מ\"ש להיות סומ\"ר בפ\"מ וע\"ט בפו\"מ או להתייגע בעבודת ה' וכה\"ג אף שאין בו בחי' הביטול והתפעלות אהוי\"ר כלל<sup data-n=\"3865\">697</sup> כנ\"ל, אבל יעמוד בתוקף ועוז גדול בעבודתו ולא יפול מזה לעולם, וכידוע שע\"פ הרוב כל עיקר היסוד של העבודה בתומ\"צ תלוי בזה והוא מ\"ש כי עם קשה עורף הוא<sup data-n=\"3866\">698</sup> [כו'] לשבח כשהוא בסט' דקדושה שמזה העבודה תמה בלי נפילה לעולם מפני שכל נצחון ועקשות הוא בעורף דוקא, אך בהיפוך כשהוא בסט' דקליפה הוא",[["3857","689","<b>כתרגום קשה עורף </b>[קשי קדל]: ת\"א תשא לב, ט."],["3858","690","<b>הידוע</b>: בד: העורף."],["3859","691","<b>כי עם קשה עורף אתה</b>: תשא לג, ג."],["3860","692","<b>עזי פנים</b>: חגיגה יד, רע\"א. ראה גם לקמן פ' תצוה שסה, ג."],["3861","693","<b>קשה</b>: ט: עז וקשה."],["3862","694","<b>שמעו אלי אבירי לב</b>: ישעי' מו, יב."],["3863","695","<b>שורש</b>: ב: שיש."],["3864","696","<b>שם</b>: בד: ליתא."],["3865","697","<b>כלל</b>: ניתוסף ע\"פ: ט."],["3866","698","<b>כי עם קשה עורף הוא</b>: תשא לד, ט. ראה גם לקמן פ' תצוה שעט, ד ובהנסמן שם."]]],[2300540820,"העיקר המנגד להפיל הנופל לכל רע מטעם הנ\"ל (אבל נשמות עליונים שהן מבחי' פנים הן בבחי' ביטול אמיתי לאלקות והזזה לגמרי להיות לבו נשבר ונדכה תמיד ונבזה בעיניו נמאס עד שמואס בחייו ממש ותומ\"י שמתבונן בגדולת ה' יתפעל ויזיז ממקומו להבטל מכל עצמותו לה' לבדו וכו', וכמו שאנו רואים בחוש גם בפחות ערך שתומ\"י שיזכירו לה' אחד יכנע לבו ורצונו כו' וכ\"ש כשיבטשו אותו בבני חיי ומזוני שירך לבבו וישבר מאד ויעשה תשובה מקירות לבו בבכיה רבה כו'), [ו]אף שזהו הסימן להבין בין צדיק לרשע שבצדיק כתיב אבן בוחן<sup data-n=\"3867\">699</sup> כו' כמ\"ש בזהר, עכ\"ז יש נשמות שהן בשרשן בבחי' פנים כצדיקים גמורים וירדו ונפלו למטה בבחי' אחוריים ועורף להיות קשים כברזל כו' מצד הגלגולים שנתגלגלו נשמות גבוהות וירדו למטה בשביל תיקון ובירור דעורף והוא ע\"י בחי' נצחון ועקשות בעבודת ה' וכה\"ג, ויש נשמות שירדו למטה מצד עוונות וח\"נ שעבירה מטמטמת<sup data-n=\"3868\">700</sup> לבו של אדם כאבן ממש ומצד השורש של[ה]ן נשמות גבוהות הן מבחי' מוחין דפנימי'<sup data-n=\"3869\">701</sup> כו', וזהו שא' לעולם יהא אדם רך כקנה<sup data-n=\"3870\">702</sup> ולא יהי' קשה [כארז] כו' וכמ\"ש במ\"א).\n<b>והנה</b> ע\"ד דוגמא מכל הנ\"ל בנשמות שהן בחי' עורף דקדושה כו' יובן עכ\"פ שהעורף הוא בחי' [הגסות ו]הקושי ביותר ועכ\"פ יובן מזה בבחי' עורף דקליפה המנגד ממש לקדושה [האלקית] והוא בחי' קליפה דפרעה שאחר כל האותות ומופתים הכביד את לבו כו' והוא שר של מצרים שהוא בבחי' כת\"ר דקליפה והוא מ\"ש התנים הגדול<sup data-n=\"3871\">703</sup> הרובץ בתוך יאוריו כו' כמ\"ש בזהר<sup data-n=\"3872\">704</sup> וה\"ע תוקף וקושי וגסה\"ר דסט\"א שנק' עומק רע לבלתי יבטל כלל וכלל מגילוי אלקות אדרבה אמר מי ה'<sup data-n=\"3873\">705</sup> כו' (ואע\"פ ש[נ]א' מלך על גוים כו' וכתיב מי לא ייראך<sup data-n=\"3874\">706</sup> מלך כו' וכן יראו מה' כל הארץ<sup data-n=\"3875\">707</sup> כו' גם בכתר דקליפה שהרי קראו לו אלקא דאלקייא<sup data-n=\"3876\">708</sup> כי להיותן מקבלים מאחוריי' וחיצוני' דשם אלקי' כידוע, הרי בכאן אמר ואני אקשה<sup data-n=\"3877\">709</sup> את לב פרעה כו' והוא שהסתיר עליו אור אלקי <span data-k=\"pg\">242</span> ּ ביותר והוא ממ\"ח צירופי' אחרונים דשם אלקים וז\"ש ונתתי מופתים [בארץ חם<sup data-n=\"3878\">710</sup> ] כו' וכמ\"ש במ\"א). והנה כדי להכניע הקליפה<sup data-n=\"3879\">711</sup> קליפה תקיפה דפרעה [הוצרך להיות ע\"י משה דוקא, ולכך לגבי פרעה הי' משה עיקר המדבר<sup data-n=\"3880\">712</sup> לפי שעיקר יסודו בקליפה דפרעה] הוא עוצם הגסות והקשי רוח כו', ואין דבר לעומתו בסט' דקדושה שיוכל להכניע אותו ולהפילו רק ע\"י בחי' משה דוקא לפי שמשה",[["3867","699","<b>אבן בוחן</b>: ישעי' כח, טז. ראה זהר שלח קסח, א. מאמרי אדה\"א שמות ח\"ב ע' תקכו. וש\"נ. שע\"ת סה, א ובהערה 1."],["3868","700","<b>שעבירה מטמטמת</b>: יומא לט, א."],["3869","701","<b>דפנימי'</b>: בד: דפנים."],["3870","702","<b>לעולם. . רך כקנה</b>: נסמן לעיל פ' שמות מו, א."],["3871","703","<b>התנים הגדול</b>: יחזקאל כט, ג. ב: ובמאמרי אדה\"ז תקס\"ג כאן (ע' קלג): תנין הגדול. וראה גם לעיל פ' שמות לז, ג ובהערה 58. מאמרי אדה\"א בראשית ע' רצט ובהנסמן שם."],["3872","704","<b>התנים. . בזהר</b>: ראה זהר שמות לד, א. שמו\"ר פ\"ט, ד. פ\"ג, יב."],["3873","705","<b>מי ה'</b>: שמות ה, ב."],["3874","706","<b>מי לא ייראך</b>: ירמי' י, ז."],["3875","707","<b>יראו מה' כל הארץ</b>: תהלים לג, ח."],["3876","708","<b>קראו לו </b>[בד: לי']<b> אלקא דאלקייא</b>: מנחות בסופה."],["3877","709","<b>ואני אקשה</b>: וארא ז, ג."],["3878","710","<b>ונתתי. . חם</b>: ע\"ד תהלים קה, כז. ראה הנסמן במאמרי אדה\"א נ\"ך ע' כב."],["3879","711","<b>הקליפה</b>: בד: ליתא."],["3880","712","<b>המדבר</b>: ט ניתוסף: דוקא כנ\"ל."]]],[2300540829,"הוא בחי' היפוכו בתכלית בקדושה האלקי' והוא בחי' הביטול במציאות ממש בהעדר הרגשת עצמו מכל וכל [מצד שנשמתו מבחי' פנימיות דח\"ע ששם הוא בחי' גילוי עצמות א\"ס ב\"ה ממש, וכמ\"ש בו כי<sup data-n=\"3881\">713</sup> מן המים משיתיהו ממ\"ע דח\"ע כנ\"ל, וע\"כ גזר אומר למשה שיהי' הוא העיקר המדבר לפרעה להכניעו ולהפילו משרשו בעורף כו'] שלא הי' זה היכולת ע\"י אהרן רק ע\"י משה דוקא וד\"ל.\n<b>וביאור</b> הענין הנה במשה נאמר והאיש משה עניו מאד<sup data-n=\"3882\">714</sup> מכל האדם כו' והאיך הי' שפל בעצמו כ\"כ עד שהי' פחות בעצמו מכל האדם אשר ע\"פ האדמה כו', הענין הוא דיש בשפלות ב' מדריגות הא' מצד החשבון שחושב פחיתות ערכו בכל דבר עד שנחשב בעצמו כחוטא גדול יותר מכל אדם ושפלות זאת נק' הכנעת הלב שלבו נכנע ונשבר באמת מצד פחיתות ערכו בעיניו עד שהכל טובים ממנו כו', ואמנם יש לשפלות זאת שיעור ומדה עכ\"פ הרי הוא במציאות דבר מה רק שהוא הפחות ערך מהכל ומרגיש בשפלות הזאת מפני שאין זה רק השפלת הגסות שאינו יש ודבר בעצ[מו כלל] ונק' ביטול היש לבד. ואמנם ענין הענוה יתירה הוא שפלות הב' שאינו לפי המדה כלל והיא השפל[ות] בעצם מציאו' שנק' ביטול העצמות מצד העצם שהוא שפל בעצם לבלתי ירגיש א\"ע כלל בשום דבר מה וכאילו אינו במציאות ממש וכמו שנא' ונחנו מה כו' (ובל\"א נישטיקייט ער איז באיי זיך גאר נישט), והסימן הוא שאינו מרגיש כלל בעצמו [גם] השפלות הזאת מאחר שאינו בא ע\"פ חשבון הפחיתות שלו רק מצד עצם שפלותו הוא הנק' ענוה שנא' והאיש משה עניו מאד כו' כנ\"ל<sup data-n=\"3883\">715</sup> שעי\"ז ממילא הי' לו לב נשבר ונדכה מאד בתמידות עד שהי' נבזה בעיניו נמאס<sup data-n=\"3884\">716</sup> בתכלית וכענין ונפשי כעפר לכל תהי'<sup data-n=\"3885\">717</sup>, דאל\"כ האיך הי' עניו מכל האדם אשר ע\"פ האדמה יהי' מי שיהי' אפי' גוי<sup data-n=\"3886\">718</sup> כו', והוא לפי עוצם מיעוט והעדר הרגשת עצמו לגמרי מכל וכל ע\"כ נפש[ו] כעפר לכל תהי' ממילא עד שיסבול חרפתו גם מהפחות שבפחותים ולא יצר לו כלל וכלל, ואין זאת המעלה דענוה יתירה שאינה לפי המדה כלל בא בעצם נפשו דמשה רק מפני [ש]שורש נשמתו שהיא היא<sup data-n=\"3887\">719</sup> גבוה מאד והוא מבחי' פנימי' דח\"ע שנק' מים עליונים כו' שהוא בבחי' ענין<sup data-n=\"3888\">720</sup> האמיתי דעצמות אוא\"ס ב\"ה שאינ[ו] שורה כ\"א בדבר השפל בעצם בתכלית [ביותר], וכידוע בענין ונפשי כעפר כו' אז ודאי פתח לבי",[["3881","713","<b>בו כי</b>: ניתוסף ע\"פ ט."],["3882","714","<b>והאיש משה עניו מאד</b>: בהעלותך יב, ג. ראה גם לקמן פ' תצוה שעא, א."],["3883","715","<b>כנ\"ל</b>: בד: ליתא."],["3884","716","<b>נמאס</b>: ט: ממש."],["3885","717","<b>ונפשי כעפר לכל תהי'</b>: נסמן לעיל פ' שמות מו, ד."],["3886","718","<b>עניו. . אפי' גוי</b>: ראה גם מאמרי אדה\"א נ\"ך ע' כח. וש\"נ."],["3887","719","<b>שהיא היא</b>: בד: הי'."],["3888","720","<b>ענין</b>: בד: אין."]]],[2300540838,"בתורתיך<sup data-n=\"3889\">721</sup> שנמשך לו פנימי' ח\"ע דתו' כמ\"ש יהיב חכמתא לחכימין<sup data-n=\"3890\">722</sup> דוקא שהוא הביטול והשפלות בעצם הכל<sup data-n=\"3891\">723</sup> שנק' חכימין שם שורה מעצמות דח\"ע שבבחי' אין ממש, וכן בלב כל חכם לב<sup data-n=\"3892\">724</sup> דוקא נתתי חכמה שלא תמצאינה בגסה\"ר<sup data-n=\"3893\">725</sup> כלל, לפי שמשה הי' עניו מאד יותר מכל האדם ע\"כ הי' שורה בו בתמידות מפנימי' ח\"ע ששם גילוי עצמות אוא\"ס ב\"ה וכידוע דעומק רום אינו שורה רק בעומק תחת<sup data-n=\"3894\">726</sup> וכמ\"ש את מי אשכון<sup data-n=\"3895\">727</sup> את דכא ושפל רוח, וזהו מצד שרש נשמתו שמן המים עליונים משיתיהו ע\"כ הי' עניו מאד בעצם מהותו כו' מפני שכל הגבוה <span data-k=\"pg\">קכא</span> ּ גבוה ביותר [יותר] הוא משפיל א\"ע למטה מטה ביותר<sup data-n=\"3896\">728</sup> וזהו האות על רו\"מ עילוי<sup data-n=\"3897\">729</sup> נשמתו דוקא. וראי' לזה ממה שמצינו שמשה השפיל א\"ע להשקות צאן יתרו כמ\"ש וגם דלה דלה לנו וישק את הצאן אף שיתרו הי' אז כומר לע\"ז ולא נתגייר עדיין והאיך השפיל א\"ע כ\"כ להשקות צאן דבנות יתרו, אלא מפני שזה הכלל דכל הגבוה גבוה [ביותר] יותר יוכל להשפיל א\"ע וע\"כ הי' יכול משה להביא שפע גם למדרגות הנמוכות בתכלית כמו להשקות צאן יתרו כו' וכה\"ג (ולקח את צפורה<sup data-n=\"3898\">730</sup> בתו לאשה, וכה\"ג יוסף שלקח את אסנת בת פרעה<sup data-n=\"3899\">731</sup> כו'), וכדוגמא שאמר במכת בכורות ועברתי באמ\"צ אני ולא מלאך<sup data-n=\"3900\">732</sup> כו' (וכמו שידוע בענין משלי שלמה שמפני רוממות עומק החכמה יכול להשפיל הדברים במשלים וחידות עד אין שיעור למטה וכמ\"ש וידבר ג\"א משל<sup data-n=\"3901\">733</sup> ).\n<b>והנה</b> מכ\"ז יובן הטעם מה שלגבי פרעה הי' משה עיקר המדבר וכמ\"ש אתה תדבר אל פרעה ואהרן הי' רק כמתורגמן לבד והוא מג'<sup data-n=\"3902\">734</sup> טעמים שהן א' ממש, להיות שבחי' קליפה תקיפה דפרעה שנק' תנין הגדול כו' הי' במדרגה היותר נמוכה ועמוקה ביותר שהוא בחי' כתר דקליפה הנק' עומק רע שעמוק עמוק מכל מדריגו' דחו\"ב ומדות דקליפה שהן חרטומי מצרים, ולזאת לא הי' ביכולת להכניעו ולהפילו כ\"א ע\"י משה דוקא להיותו לעומתו במדרג' הגבוה מאד נעלה בקדושת האלקי' ביותר שהוא בפנימי' הכל<sup data-n=\"3903\">735</sup> דקדושה כמו שהחכ' באין האמיתי דעצמו' א\"ס ב\"ה שהוא דוקא אשר יכול להשפיל א\"ע למטה ביותר מטעם הנ\"ל, והוא עצמו הטעם הב' שהיא הנותנת שיוכל להשפיל עוצם גסותו ולשבור אותו בתכלית לפי שהי' היפוכו בתכלית בבחי' לב נשבר ונדכה בתכלית מצד הענוה היתירה מכפי המדה לפי שהי' עניו [מאד] מכל האדם שהוא עוצם",[["3889","721","<b>ונפשי כעפר. . פתח לבי בתורתיך</b>: ראה מאמרי אדה\"א קונטרסים ע' שפא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670059\" data-slug=\"torat-chaim\" data-id=\"2300670059\">תו\"ח בראשית לד, ב</a> ובהערה 20."],["3890","722","<b>יהיב חכמתא לחכימין</b>: דניאל ב, כה. ראה ד\"ה זה במאמרי אדה\"א נ\"ך ע' תקכג. לקמן פ' בא קיב, ב. קיח, א."],["3891","723","<b>הכל</b>: בד: הנ\"ל. ט: כנ\"ל."],["3892","724","<b>בלב כל חכם לב</b>: תשא לא, ו [ושם: ובלב — ראה לקמן פ' בא קיח, א. קלב, ד. מאמרי אדה\"א קונטרסים ע' שפט. וש\"נ]."],["3893","725","<b>שלא תמצאינה בגסה\"ר</b>: ראה עירובין נה, א."],["3894","726","<b>דעומק רום. . בעומק תחת</b>: ראה ס\"י פ\"א, מ\"ה. מאמרי אדה\"א דברים ח\"א ע' מג. וש\"נ. שע\"ת כג, א ובהערה 3. לקמן פ' בא קיח, ד. בשלח קעא, ג. רל, ד. משפטים רצט, ב."],["3895","727","<b>את מי אשכון</b>: ישעי' נז, טו [ושם: אשכון ואת דכא — ראה לקמן פ' בא קח, ג. בשלח קעא, ג. משפטים רצז, ג. רצט, ב. תצוה שכד, ד. מאמרי אדה\"ז תקע\"א ע' רחצ. מאמרי אדה\"א שמות ח\"א ע' רמח. וש\"נ. קונטרסים ע' קסט. וש\"נ]."],["3896","728","<b>שכל הגבוה. . מטה ביותר</b>: נסמן לעיל כא, ב."],["3897","729","<b>רו\"מ עילוי</b>: גט: רוממו' מעלת."],["3898","730","<b>ולקח את צפורה</b>: שמות ב, כא."],["3899","731","<b>יוסף. . אסנת בת פרעה </b>[בד: ליתא]: מקץ מא, מה."],["3900","732","<b>ועברתי באמ\"צ אני ולא מלאך</b>: נסמן לעיל נד, ב."],["3901","733","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670143\" data-slug=\"torat-chaim\" data-id=\"2300670143\">וידבר ג</a>\"א משל</b>: מלכים-א ה, יב. ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' שצג. לקמן פ' בשלח קצא, א. יתרו רסא, ב. תו\"ח לך פא, ד ובהערה 31. שעה\"י קמ, ב ובהערה 27."],["3902","734","<b>מג'</b>: גט: מב'."],["3903","735","<b>הכל</b>: בד: הכת\"ר."]]],[2300540847,"השתל'<sup data-n=\"3904\">736</sup> בעצם דוקא כנ\"ל, והכל א' לפי שזאת השפלות הגדולה בנפשו באה מצד שרשו למעלה גבוה מאד נעלה משום דהא בהא תליא דוקא כנ\"ל<sup data-n=\"3905\">737</sup> וד\"ל. ולפי שעצם לב נשבר ונדכה נבזה בעיניו נמאס כו' דמשה זהו תכלית המנגד לגה\"ר<sup data-n=\"3906\">738</sup> דקליפה דפרעה ששרשו בעורף כנ\"ל, ע\"כ ע\"י בחי' לב נשבר ונדכה<sup data-n=\"3907\">739</sup> ושפלות עצומה דמשה הוא שיכול לעשות הכנעה ושפלות לבטל גסות דקליפה דפרעה ג\"כ שיכנע לבבו הקשה כברזל לשבור לגמרי כו', כי כל גסות וחוצפה קשה אין לו ביטול רק בשתי סיבות, או בביטושים גדולים ביותר כמו עד\"מ שמכים ביותר קשה בהכאה גדולה בצור, או שיפול מצד המנגדו שהוא תכלית בחי' האין האלקי שיכול לעשות ביטול היש הגס ביותר, ושניהם היו ע\"י משה דוקא להיותו בתכלית עומק רוח נשברה ונפש שפילה ביותר והוא הי' אלקים לפרעה להכותו מכות גדולות כמ\"ש ראה נתתיך אלקים לפרעה כו' עד שגם אבן קשה [כ]פרעה נכנע ונשבר לפניו שלא הי' זה ע\"י אהרן רק ע\"י משה דוקא מטעם הנ\"ל וד\"ל. וזהו מ\"ש אתה תדבר אל פרעה<sup data-n=\"3908\">740</sup> כו', פי' תדבר לשון הכנעה כמו ידבר עמים תחתינו<sup data-n=\"3909\">741</sup> כו' וכמו ותדבר את זרע הממלכה<sup data-n=\"3910\">742</sup> כו' שזהו ענין הכנעה להכניעם ולהשפילם בתכלית כו', כך בבחי' דבור [ד]משה אל פרעה כו' הי' מכניע לפרעה להיות בתכלית הביטול <span data-k=\"pg\">244</span> ּ לאלקות רק שה' הכביד לבו כדי להרבות אותות ומופתים כו' ולכך לגבי פרעה דוקא הי' משה עיקר המדבר ולא אהרן וד\"ל.\n<b>וזהו</b> הם המדברים אל פרעה הוא משה ואהרן פי' המדברים אל פרעה להכניעו [ו]להשפילו כו' [ב]פי' ידבר עמים תחתינו כו', הוא משה ע\"י משה דוקא מטעם הנ\"ל ואח\"כ אהרן שהי' לו למתורגמן לפרש דבריו לבד, אבל העיקר הי' משה כמו [שנא'] ראה נתתיך כו', משא\"כ בסדר ההדרגה ביצ\"מ להוציא את בנ\"י ממצרים שם נהפוך שאהרן קדם למשה וע\"כ א' הוא אהרן ואח\"כ משה אשר כו', והוא מטעם הנ\"ל דאהרן נק' שוש' דמט' לעורר לבב בנ\"י באה\"ר שלזה מיאן משה בשליחותו עד שא\"ל ה' אהרן יהי' לך לפה דוקא כנ\"ל<sup data-n=\"3911\">743</sup>. והנה התורה היא נצחית<sup data-n=\"3912\">744</sup> בכל דור ובכל זמן ויש גם עכשיו בכל דור ובכל זמן בחי' משה ואהרן שנק' ראשים<sup data-n=\"3913\">745</sup> לכנ\"י ואהרן שודמ\"ט כו' היינו לגבי כנ\"י דקדים למשה בבחי' העלאת מ\"ן, והוא בכל סדר התפלה באוי\"ר בהתבוננות להעלות נש\"י בפסד\"ז עד ק\"ש בא' ואהבת בכל לבבך כו' שהיא התלהבות וצמאון נה\"א לדבקה בו ית', ואח\"כ משה שהוא שודמ\"ל להמשיך אח\"ז דוקא גילוי אוא\"ס ע\"י תומ\"צ והוא מ\"ש והיו הדברים כו' ודברת בם בשבתך<sup data-n=\"3914\">746</sup> כו' שזהו עיקר בענין",[["3904","736","<b>השתל'</b>: בד: השפלות."],["3905","737","<b>והכל א'. . כנ\"ל</b>: ניתוסף ע\"פ: ט."],["3906","738","<b>לגה\"ר</b>: בדט: לגבו'. ג: לגסות."],["3907","739","<b>ונדכה</b>: בד: ליתא."],["3908","740","<b>אל פרעה</b>: ניתוסף ע\"פ: ט."],["3909","741","<b>ידבר עמים תחתינו</b>: תהלים מז, ד."],["3910","742","<b>ותדבר את זרע הממלכה</b>: דהי\"ב כב, י [בדילוג]."],["3911","743","<b>משא\"כ בסדר. . כנ\"ל</b>: ניתוסף ע\"פ: גט."],["3912","744","<b>התורה היא נצחית</b>: נסמן לעיל פ' שמות א, א."],["3913","745","<b>ראשים</b>: בד: רועים."],["3914","746","<b>בשבתך</b>: ניתוסף ע\"פ: ט."]]],[2300540856,"הבירורים לברר מעה\"ד טו\"ר בסו\"מ בפו\"מ וע\"ט כו' שזהו דוקא<sup data-n=\"3915\">747</sup> כל היום אחר התפלה רק ע\"י משה דוקא [משום] דבחכ' אתברירו כו', והוא ע\"י בחי' הענוה ושפלות בעצם הנ\"ל שהוא לב נשבר ונדכה בעצם שלמעלה הרבה מן הצמאון וההתלהבות כו' הוא היפוכו בתכלית שהרי הצמאון והתלהבות הנפש הוא בחי' העלאה ורוממות הנפש שמתנשא ויגביר<sup data-n=\"3916\">748</sup> לבו לעלות למעלה, ואע\"פ שבעת התפלה יעלה בהר ה' באוי\"ר כו', הרי אנו רואים שתומ\"י אחר שעה יפול למטה לגמרי ונשאר הנו\"ן<sup data-n=\"3917\">749</sup> כמו שהוא ולא יש ביכלתו לברר לעה\"ד ולהפך חשוכא לנהורא כו' בסו\"מ כו', אך ע\"י בחי' ענוה ושפלות בעצם הנ\"ל שהוא עומק לב נשבר ונדכה בתכלית הוא הכח והעוז דוקא שיוכל להיות כל היום סו\"מ בתכלית כו' גם כשהולך במקום חשך וטומאה והופך חשך לאור כו' שלא הי' זה ע\"י התבוננות<sup data-n=\"3918\">750</sup> לפי שזהו בבחי' משה הנ\"ל שהוא דוקא המדבר אל פרעה דוקא לבטש ולהכניע גסות קשה דקליפ' דעומק רע כו'. וז\"ש [הם] המדברים אל פרעה הוא משה דוקא ואח\"כ אהרן שהוא המעלה מחלק הטוב דק\"נ בתפלה אחר הבירור דמשה בתו' בכל<sup data-n=\"3919\">751</sup> היום כמשל השובר את קליפת הפרי שבקל יכול<sup data-n=\"3920\">752</sup> ליטול את הפרי אח\"כ [ולאכלו] וא\"צ טורח כלל<sup data-n=\"3921\">753</sup> כו' וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש מי יעלה בהר ה' כו' נקי כפים [כו'] אשר לא נשא לשוא נפשו, ויש בתיבה זו דנפש[ו] קר\"י וכתיב<sup data-n=\"3922\">754</sup> נפשו כתי' ונפש[י] קרי (ופירש\"י<sup data-n=\"3923\">755</sup> אשר לא נשבע בשמי ובנפשי לשוא ר\"ל<sup data-n=\"3924\">756</sup> שבועה אפי' אל החפץ<sup data-n=\"3925\">757</sup> כמו נשבעה בנפשו<sup data-n=\"3926\">758</sup> ) ושניהם אמת, והענין הוא כי הכ[תי'] מורה על בחי' משה שהן אותיות התו' כמו התושב\"כ<sup data-n=\"3927\">759</sup> דוקא שהוא ע\"י משה כו' [ב]ענין כ\"ד ספרי' דאורייתא שנמשך מים הגדול ע\"י משה כמ\"ש וגם דלה דלה [לנו] כו', וזהו [שהכתי'] נפשו בחי' נפש דמשה כמ\"ש כ\"א בתורת ה'<sup data-n=\"3928\">760</sup> חפצו ובתורתו יהגה יומם ולילה כו' שהוא אחר התפלה דוקא<sup data-n=\"3929\">761</sup>, שע\"י בחי' שפלות וענוה וביטול עצמות כל חפצו להגות בתו' ומעשה המצות להבדיל בין טו\"ר כל היום, אבל<sup data-n=\"3930\">762</sup> כל מה שהי' לו צמאון והתלהבות הנפש שזהו נשיאת הנפש בחי' העלאה והגבהה למעלה באלקות לא לשוא נשא [את] נפשו דהיינו נפשו דמשה שהוא לומד באותיות התורה שיש בה מבחי' אוא\"ס שבח\"ע שהוא בחי' משה שנא' בו <span data-k=\"pg\">קכב</span> ּ כי מן המים עליונים דח\"ע משיתיהו כו' כנ\"ל, אבל הקרי הוא נפש[י] (כמו הנשבע בשם הוי' לשוא שנושא [את] שם הוי' לשוא) היינו כאשר לא בא לבחי' ביטול וענוה ושפלות כלל אחר התפלה, הגם שהתפלל בכוונה שלימה לפי דעתו והתפעל בהתלהבות ותשוקת",[["3915","747","<b>כו' שזהו דוקא</b>: ניתוסף ע\"פ: ט."],["3916","748","<b>ויגביר</b>: בד: ויגבה."],["3917","749","<b>הנו\"ן</b>: ג: ריק. ט: ריקן."],["3918","750","<b>התבוננות</b>: גט: ההתלהבות."],["3919","751","<b>בתו' בכל</b>: גט: בתו\"מ כל."],["3920","752","<b>יכול</b>: ניתוסף ע\"פ: ט."],["3921","753","<b>כלל</b>: ניתוסף ע\"פ: ט."],["3922","754","<b>דנפש[ו] קר\"י וכתיב</b>: ראה מנחת שי לתהלים כד, ד."],["3923","755","<b>ופרש\"י</b>: עה\"פ [תיבת ”אשר\" לא נמצא שם]."],["3924","756","<b>ר\"ל</b>: ט: דל'. וברש\"י: מצינו לשון."],["3925","757","<b>אפי' אל החפץ</b>: בד: נופל על החפץ. ט: (וברש\"י) נופל על הנפש (נפש)."],["3926","758","<b>נשבעה בנפשו</b>: בד: נשבע ה' בנפשו [ראה ראב\"ע שם. הנסמן לקמן פ' בשלח רמט, ב]. וברש\"י נשבע ה' צבאות בנפשו."],["3927","759","<b>התושב\"כ</b>: ט: שבאים בכתב."],["3928","760","<b>כ\"א בתורת ה'</b>: תהלים א, ב."],["3929","761","<b>דוקא</b>: ניתוסף ע\"פ: ט."],["3930","762","<b>אבל</b>: ט: א\"כ."]]],[2300540865,"אלקי בצמאון הנפש כו' אבל לא הי' בלבו ודעתו רק להגיע להתפעלות זאת שהוא רק התנשאות והגבהת [ה]לב שייטיב לבו בזה עצמו כמו לא יחפוץ כסיל בתבונה<sup data-n=\"3931\">763</sup> כ\"א בהתגלות לבו וכמ\"ש במ\"א, עד שיוכל להיות מזה שמיד אחר התפעלות אהבה ותשוקה לאלקות ישכח מיד ויפול מזה לגמרי ולא ישאר רק בחי' גבהות וגסות הלב שהוא רק התנשאות גשמיות בלב[ו] ומה שהי' לו התפעלו' ודביקות כדמיון הכוזב ויגבה לבו בגשמיות לומר הלא דבר הוא ומתגאה על הכל בגיאות גשמיות שנק' גסות הרוח ממש והוא מוטעה מאד בנפשו להחזיק עצמו ברוב קדושה יתירה עד שירדוף ממנה<sup data-n=\"3932\">764</sup> בכבודו כאחד הגיאים וריקים כו', והוא מ\"ש אמרו אחיכם שונאיכם<sup data-n=\"3933\">765</sup> כו' למען שמי יכבד הוי' כמ\"ש בר\"מ על אנשי שם<sup data-n=\"3934\">766</sup> כו' שכל נקודתו אינו<sup data-n=\"3935\">767</sup> רק להתגדל ולקנות שם כו', נמצא שלא נשאר רק החיצוניות שהוא ההתנשאות גשמיות לבד ולא יותר הרי לשוא ממש נשא את נפשו בהתלהבות בתפלה.\n<b>וראי'</b> לזה [ו]הסימן המורה ע\"ז הוא מה שלא יחפוץ כלל במעשה טוב כמו בלימוד ת\"ת ומעשה המצות אחר התפלה לפי שכבר מילא לבבו והוטב לו מאשר הי' לבו בהתפעלות ובזה די לו כי לזאת הי' מגמתו מפני שאינו רוצה רק [ב]צמאון זה לבד (כ[נ\"ל ב]משל הצמא ואינו שותה כלל שאין זה צמאון כלל כ\"א הי' הצמאון אמת לא הי' מרווה הצמאון כ\"א בשתיית המים) (אך עכ\"ז יש רבים טועים בזה [להחמיר] ביתר מכפי המדה לאסור בנפשם כל הרגשה בהתפעלות אלקות מטעם זה, ישגו בזה מאד, שכ\"ז היינו שאינו חפץ בקרבת אלקי' מצד אלקות כלל רק להתפעל בהתלהבות ולא יותר [ו]הוא מצד שאינו בבחי' ביטול היש כלל וכמו שהוא בגסותו יחפוץ להתפעל באהבה ודביקות ואין בו הזזה ממקומו כלל, ועיקר המכוון באהבה והדביקות אינה מצד האהבה והדביקות עצמה רק שיהי' דבוק בהוי' דוקא שהוא בחי' הביטול עצמי לידבק בבוראו כמ\"ש לדבקה בו דוקא וכן ואתם הדבקים בהוי' כו', והוא עושה הדביקות עצמו עיקר ולא מצד אלקות כלל שהרי ניכר ממנו ממה שאינו חפץ בתו\"מ שזהו המעיין שמרווה צמאון וכמ\"ש הוי כל צמא<sup data-n=\"3936\">768</sup> לכו למים מפני שאין צמא באמת כלל, אבל מי שקרבת אלקים יחפוץ באמת היינו לדבקה בו ית' דוקא אינו חפץ בהרגשת אהבה ודביקות מצד עצמו אלא המכוון מזה שיהא דבוק בו ית' דוקא שהוא בחי' ביטול עצמותו לימשך ולדבק בהוי' כו', א\"כ מזה יובן דדוקא הרגשת התפעלות אלקות לחיות גמור זהו הסימן שאהבה ודביקות הזאת הוא באלקות ממש כמ\"ש",[["3931","763","<b>לא יחפוץ כסיל בתבונה</b>: משלי יח, ב. ראה מאמרי אדה\"א קונטרסים ע' סב ואילך. דברים ח\"א ע' ח. וש\"נ."],["3932","764","<b>ממנה</b>: בד: למי שפגע."],["3933","765","<b>אמרו אחיכם שונאיכם</b>: ישעי' סו, ה. ראה הנסמן בשע\"ת סד, ג הערה 7."],["3934","766","<b>בר\"מ על אנשי שם</b>: ראה זהר בראשית כה, ב. מאמרי אדה\"א קונטרסים ע' קמד."],["3935","767","<b>אינו</b>: ניתוסף ע\"פ: ט."],["3936","768","<b>הוי כל צמא</b>: ישעי' נה, א."]]],[2300540874,"ואהבת את הוי' בכל לבבך כו' בשני יצריך כו' דהיינו אהבה מורגשת בלב שאין מקרא יוצא מידי פשוטו<sup data-n=\"3937\">769</sup> וכמ\"ש לאהבה את הוי' אלקיך כי הוא חייך ממש וכמאמר קרבת אלקים<sup data-n=\"3938\">770</sup> לי טוב לי ממש, רק כשכוונת[ו] בקרבת אלקים מצד אלקות דוקא ואע\"פ שהוא הנאת עצמו עד שירגיש בנפשו חיות גמור הרי יחי' נפשו מאלקות ממש וכמ\"ש לבי ובשרי ירננו<sup data-n=\"3939\">771</sup> כו' כי הוא צור לבבי<sup data-n=\"3940\">773</sup> כי הוא חיינו<sup data-n=\"3941\">772</sup> ממש כו' ואין מורגש יותר מן השיעור וניגון <span data-k=\"pg\">246</span> ּ והוא עיקר האהבה והדביקות באלקות כמ\"ש וחסידיך ירננו<sup data-n=\"3942\">774</sup> כו' וכמו\"כ בכל [ה]מזמורים שבתהלים וד\"ל).\n<b>וזהו</b> שהקרי נפשי שאינו בא לכלל דביקות וקירוב אמיתי ביחו\"ע<sup data-n=\"3943\">775</sup> דתו\"מ שהוא בחי' משה רק הוא בבחי' הפירוד עצמי ע\"כ<sup data-n=\"3944\">776</sup> נפש\"י ולא נפשו דמשה (וכפירש\"י שנושא שם הוי' לשוא כו' והוא בתפלה של שוא נפשי חסר<sup data-n=\"3945\">777</sup> כמו הצמאון שוא הנ\"ל שהרי הוא כאלו מעיד עדות שקר כנ\"ל בנפשו באמרו ואהבת כו', וכללות נש\"י<sup data-n=\"3946\">778</sup> [נק'] נפשי כמו צמאה לך נפשי<sup data-n=\"3947\">779</sup> כו'), כי התנשאות של שוא הי' ממש כו' אחר שלא נשאר בו רק הגסות לברר<sup data-n=\"3948\">780</sup> כו'. אך מי יעלה בהר הוי' בתפלה (ומי יקום במקום קדשו בהיכל ד\"א של הלכה שהוא בהיכל ק\"ק<sup data-n=\"3949\">781</sup> ) נקי כפים ובר לבב פי' מי שאינו חפץ רק להוי' לבדו והוא בר לבב בביטול כל העצמות ואי[נו] מטעה א\"ע כלל<sup data-n=\"3950\">782</sup> לחפוץ למלאות לבבו בהתפעלות עצמיות רק להוי' ולדבקה בו דוקא, הוא איש אשר לא נשא לשוא נפשי כי העלאת נפש[ו] הוא לה' דוקא והתנשאות זו להוי' היא ולא לשוא כו' כי הוא איש אשר ישא ברכה מאת הוי' כו' דהיינו בדבר ה' זו הלכה באמיתיות<sup data-n=\"3951\">783</sup> התו' שלומד מיד אחר התפלה שממשיך תוס' ברכה והמשכה בגילוי אוא\"ס בחכ' שבתורה כמ\"ש כ\"א בתורת ה' חפצו ובתורתו כו' להאיר נפשו לדבקה בו ית' ממש, וזהו ישא ברכה מאת הוי' בתורה על נפשו וצדקה מאלקי ישעו ע\"י מצות מעשיות שנק' צדקה כמו זורע צדקות כידוע וד\"ל. אבל מי שאין חפצו בתורת ה' כלל מיד אחר התפלה הוא איש אשר נשא לשוא נפשו בתפלה כו' וזהו נפשי ולא נפשו דמשה, וע\"כ לא ישא ברכה מאת הוי' כלל בתו\"מ וגם ממילא יובן שאינו ממשיך כלום בח\"י ברכות דשמו\"ע באומרו בא\"י כו' מאחר שלשוא נשא נפשו בהעלאות כו' וד\"ל. ובאמת גם מי שהתפעלות אהבתו להוי' היא בהעלאת וביטול עצמותו לדבקה בו ית' כו' עד שהוא מרגיש בנפשו לחיות גמור כמ\"ש כי הוא חייך ממש בלי שום תערובות עצמו כלל, הרי [ז]ה נק' בחי' רצוא שאין זה שלימות כלל ולא בזה חפץ הוי' כמ\"ש הסבי עינייך<sup data-n=\"3952\">784</sup> מראות<sup data-n=\"3953\">785</sup> כו' דמוקדין לי' בשלהובא",[["3937","769","<b>שאין מקרא יוצא מידי פשוטו</b>: שבת סג, א."],["3938","770","<b>וכמאמר </b>[ט: וכן א']<b> קרבת אלקים</b>: תהלים עג, כח."],["3939","771","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["3940","773","<b>צור לבבי </b>[ט: ניתוסף: כו']: תהלים עג, כו."],["3941","772","<b>כי הוא צור לבבי כי הוא חיינו</b>: כ\"ה גם בהכת\"י."],["3942","774","<b>וחסידך ירננו</b>: תהלים קלב, ט."],["3943","775","<b>ביחו\"ע</b>: בד: בח\"ע."],["3944","776","<b>ע\"כ</b>: בד: נק'."],["3945","777","<b>שוא נפשי חסר</b>: ב: מס\"נ שוא. גד: שוא מסר נפשו. ט: שוא נשא נפשו."],["3946","778","<b>נש\"י</b>: ניתוסף ע\"פ: ט."],["3947","779","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["3948","780","<b>לברר</b>: בד: לבד."],["3949","781","<b>שהוא בהיכל ק\"ק</b>: ניתוסף ע\"פ: גט."],["3950","782","<b>כל. . כלל</b>: ניתוסף ע\"פ: ט. בד: ליתא."],["3951","783","<b>באמיתיות</b>: בד: באותיות."],["3952","784","<b>הסבי עינייך. . דרחימותא</b>: שה\"ש ו, ה. ראה זהר קדושים פד, א. מאמרי אדה\"א שמות ח\"א ע' קלה. וש\"נ."],["3953","785","<b>מראות</b>: בד: ליתא."]]],[2300540883,"דרחימותא כו', אלא העיקר הוא בבחי' שוב<sup data-n=\"3954\">786</sup> הוא שהמשיך גילוי אלקו' בתומ\"צ שהוא בחי' משה כמ\"ש ודברת בם כו' וע\"כ יראה בלא חכ' שבתורה הן פירוד בין א' למא\"ו<sup data-n=\"3955\">787</sup> דהיינו אתתא אתתרכת מבעלה<sup data-n=\"3956\">788</sup> כו' כמ\"ש בזהר. וכך הוא מי שנשאר בחיות אלקי גם זה בחי' רצוא<sup data-n=\"3957\">789</sup> בהיותו קרוב ודבוק באמת בהתלהבות אמיתי, כי הרי א' חסד חפצתי בתומ\"צ בפו\"מ ולא זבח<sup data-n=\"3958\">790</sup> דתפלה במקום קרבן<sup data-n=\"3959\">791</sup> דהיינו העלאת הנפש באוי\"ר לבד. וזהו ג\"כ מ\"ש מי יעלה בהר הוי' אשר לא נשא לשוא נפשו בחי' רצוא<sup data-n=\"3960\">792</sup> שיהי' בבחי' נפשו דוא\"ו דתורה בבחי' שוב דוקא, וכן להיפוך מי שאומר אין לי אלא תורה אפילו בביטול וענוה ושפלות כו' אפי' תורה אין לו כשלא קדם לו בחי' רצוא באהבה כו' בק\"ש ותפלה, דמי שלא [י]עלה בהר הוי' בסדר המדריגות דתפלה עד ק\"ש בהעלאת דרצוא הוא<sup data-n=\"3961\">793</sup> לא יוכל לקבל אור דתורה כלל וכלל ואין ענוה ושפלות שלו בלא התפעלות בתפלה אמת, כ\"א אחר הרצוא דתפלה הוא בא לבחי' ענוה ושפלות וביטול אמיתי הוא אשר ישא ברכה מאת הוי' בתומ\"צ כל היום וד\"ל (והוא הפי' הפשוט במ\"ש מי יעלה בהר ה' ומי יקום דקאי הכל בהיכלא עילאה דתורה אשר לא נשא לשוא נפשו בתפלה כו') וד\"ל<sup data-n=\"3962\">794</sup>.\n<b>ומעתה</b><sup data-n=\"3963\">795</sup> יש להבין מ\"ש בראש פ' זו אלה ראשי בית אבותם<sup data-n=\"3964\">796</sup> בני ראובן בכור ישראל כו' ובני שמעון<sup data-n=\"3965\">797</sup> כו' ואלה שמות בני לוי<sup data-n=\"3966\">798</sup> כו' עד הוא אהרן ומשה אשר אמר הוי' [להם הוציאו כו'] מה סמיכות כ\"ז לענין הוא אהרן ומשה כו', ואם מפני שרצה לייחס תולדות אהרן ומשה הי' לו להתחיל רק בשבט לוי ולמה התחיל בשבט ראובן ושמעון שאין מהצורך לזה בשביל יחוס אהרן ומשה שהרי אינם מראשי בית אבותם של אהרן ומשה כלל כו', ומובן מזה דמה<sup data-n=\"3967\">799</sup> שייכות לראובן ושמעון עם לוי דוקא לייחוס של אהרן ומשה ולמה ראובן ושמעון שייכי' יותר מכל השבטים כו'. ועוד י\"ל מה שייכות ענין זה דאלה ראשי בית אבותם לתחלת הפרשה דוארא עם מה שאמר בסוף פ' שמות למה הרעות<sup data-n=\"3968\">800</sup> כו' והשיבו עתה תראה כו' וארא כו' עד לכן אמ[ו]ר כו', וגם בגוף ענין התשובה על השאלה אינו מובן כלל דמה זו תשובה עתה תראה כו' שאין זה רק הבטחה לבד וכבר",[["3954","786","<b>העיקר. . שוב</b>: ראה גם לעיל פ' שמות ז, ג. לקמן פ' בשלח קעז, ד. דרך מצותיך קסב, ב. מאמרי אדה\"ז תקס\"ו ע' רסב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680066\" data-slug=\"torat-chaim\" data-id=\"2300680066\">תו\"ח ח\"ש קלב, ד</a>. מקץ ריג, א."],["3955","787","<b>א' למא\"ו</b>: בד: ה\"א לוא\"ו."],["3956","788","<b>אתתא אתתרכת מבעלה</b>: ראה זהר ויקהל רטז, ב."],["3957","789","<b>גם. . רצוא</b>: ט: זה גם."],["3958","790","<b>חסד חפצתי. . ולא זבח</b>: הושע ו, ו."],["3959","791","<b>דתפלה במקום קרבן</b>: ראה ברכות כו, א-ב. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["3960","792","<b>בחי' רצוא</b>: ניתוסף ע\"פ: ט."],["3961","793","<b>הוא</b>: בד: הנ\"ל."],["3962","794","<b>דתורה. . נפשו. . וד\"ל</b>: ט: בתו\"מ.. בד: ליתא. ט: נפשי.. ט: ליתא."],["3963","795","<b>ומעתה</b>: ע\"כ נמצא בתו\"ח. ומכאן ואילך נדפס מטו. אולי מיוסד על סיום ד\"ה וידבר. . ויצוום תקס\"ח [באוה\"ת וארא ע' רח]."],["3964","796","<b>אלה ראשי בית אבותם</b>: וארא ו, יד."],["3965","797","<b>ובני שמעון</b>: שם ו, טו."],["3966","798","<b>ואלה שמות בני לוי</b>: וארא שם, טז."],["3967","799","<b>דמה</b>: יגיז: דיש."],["3968","800","<b>למה הרעות. . עתה תראה. . וארא. . לכן אמ[ו]ר</b>: שמות ה, כב. ו, א. ו, ג. ו, ו."]]],[2300540892,"הבטיחם ע\"ז ואין כל חדש בזה כלל. והשאלה במקומה עומדת שא' שאין ההבטחה מתקיימת שהרי בנ\"י מוכים ונדחקים ביותר ע\"ד העבודה כמ\"ש ויוכו שוטרי בנ\"י<sup data-n=\"3969\">801</sup> כו' וז\"ש למה הרעות כו' לא די שלא הצלת כהבטחתך כו' אלא שהרעות להם יותר כו' ומה זה שא' וארא אל כו' עד לכן אמ[ו]ר כו' שאין זו תשובה כלל על השאלה. והעיקר י\"ל מה זו סמיכות פרשה זו דאלה ראשי בית אבותם שמתחיל לספר יחוס ראשי בית אבותם דמשפחות השבטי' שאין זה שייך כלל לענין הצלת בנ\"י מקושי עבודתם כו' ולא<sup data-n=\"3970\">*802</sup> בשביל להודיע יחוס אהרן ומשה משבט לוי אין זה שייך כלל לענין הקדום להשיב על השאלה רק במה שא' הוא אהרן ומשה אשר אמר ה' להם כו' הרי זה כבר ציוה להם כו'.\n<b>אך</b> הנה הענין הוא דכ\"ז יתורץ בהקדמה א' דבחי' ראובן ושמעון הוא שייך דוקא לבחי' לוי שע\"כ א' אח\"כ הוא אהרן ומשה כו', וגם יתורץ מה שבתחלה א' הוא אהרן ומשה ובסוף א' הוא משה ואהרן (באופן אחר). להיות ידוע בשורש כללות נש\"י שהוא בציור אדם כמ\"ש נעשה אדם בצלמינו<sup data-n=\"3971\">802</sup> כו' והוא בבחי' אדם העליון דאצי'. והנה כללות ע\"ס דאצי' נחלקו לג' קווין חח\"נ קו ימין, בג\"ה קו שמאל, [דת\"י קו האמצעי כולל ב' הקוין כידוע, דהיינו שכלול מחסדים דקו ימין חח\"ן ומגבורות דקו השמאל] ובחי' ההתכללות משניהם יחד הוא קו האמצעי דוקא שנק' בריח התיכון<sup data-n=\"3972\">804</sup> כו', והיינו ג\"כ ענין ג' שמות דשם ע\"ב<sup data-n=\"3973\">805</sup> ושם ס\"ג<sup data-n=\"3974\">806</sup> ושם מ\"ה<sup data-n=\"3975\">807</sup> הכלול משניהם יחד שהוא עיקר בחי' אד\"ם גימט' מ\"ה<sup data-n=\"3976\">808</sup> כידוע. והענין הוא דשם ע\"ב הוא בחכ'<sup data-n=\"3977\">809</sup> דקו הימין בבחי' החסדים דחכ' חסד כו'. ושם ס\"ג הוא בבינה<sup data-n=\"3978\">810</sup> קו השמאל בג\"ה כו' בינה גבורה כו' בבחי' הגבו', ושם מ\"ה כלול מחו\"ג דע\"ב ס\"ג, ומאמצעות התכללות שניהם יחד נמשך והוא המחבר לשניהם יחד שהוא בחי' קו האמצעי דת\"י כידוע בס' הקבלה. וזהו כללות ענין פ' זו דאלה ראשי בית אבותם שלשה שבטים ראובן ושמעון ולוי שהן בחי' הג' קווין דחג\"ת שכולל כל ציור קומת אדם והן ג' שמות דע\"ב ס\"ג מ\"ה בחי' חב\"ד, ובחי' ראובן הוא בקו הימין חח\"נ כו' דשמו מורה ע\"ז רא\"ו ב\"ן<sup data-n=\"3979\">811</sup> כידוע דראי' בחכ'<sup data-n=\"3980\">812</sup> וחסד הוא ענף החכ'<sup data-n=\"3981\">813</sup> ע\"כ שמו רא\"ו ב\"ן דב\"ן מסטרא דחסד<sup data-n=\"3982\">814</sup> כמו כי זכר",[["3969","801","<b>ויוכו שוטרי בנ\"י</b>: שמות ה, יד."],["3970","*802","<b>ולא</b>: אוצ\"ל: ואם."],["3971","802","<b>נעשה אדם בצלמינו</b>: בראשית א, כו."],["3972","804","<b>קו האמצעי. . בריח התיכון</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקמט ואילך."],["3973","805","<b>דשם ע\"ב</b>: ראה זהר תרומה קלב, ב. פרדס (שער פרטי השמות) שכ\"א, פ\"ה. מכתב להרב בראנדט נדפס ברשימות חוברת מא (לפ' אחו\"ק)."],["3974","806","<b>ושם ס\"ג</b>: ראה זהר (רע\"מ) פינחס רמו, ב."],["3975","807","<b>ושם מ\"ה</b>: ראה זהר בהקדמה ד, א ובדרך אמת שם. הנסמן במאמרי אדה\"א נ\"ך ע' עא."],["3976","808","<b>אדם גימט' מ\"ה</b>: נסמן לעיל פ' שמות ד, ב."],["3977","809","<b>דשם ע\"ב הוא בחכ'</b>: ראה ע\"ח (שער רפ\"ח ניצוצין) שי\"ח, פ\"ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שנג."],["3978","810","<b>ושם ס\"ג הוא בבינה</b>: ראה ע\"ח שער הכללים פ\"ח. שער רפ\"ח ניצוצין שם. הנסמן במאמרי אדה\"א שמות שם. לקמן פ' תשא שפד, ד."],["3979","811","<b>ראובן. . רא\"ו ב\"ן</b>: ראה ב\"ר פע\"א. (ראה גם) שע\"ת לח, ג. מאמרי אדה\"א נ\"ך ע' קצח. וש\"נ."],["3980","812","<b>דראי' בחכ'</b>: נסמן לעיל פ' שמות כז, ג."],["3981","813","<b>וחסד הוא ענף החכ'</b>: ראה זהר ואתחנן רסב, סע\"א. לך צד, א. תרומה קעה, ב. במדבר קיח, ב."],["3982","814","<b>דב\"ן מסטרא דחסד</b>: ראה גם לעיל לד, סע\"ב ואילך ובהנסמן שם."]]],[2300540901,"חסדו<sup data-n=\"3983\">815</sup> כו' והוא שם ע\"ב דחכ' וחסד דחס\"ד גימט' ע\"ב<sup data-n=\"3984\">816</sup> כידוע. ובחי' שמעון הוא בקו השמאל בג\"ה כו' ושמו מורה ע\"ז לשון שמיעה כמ\"ש כי שמע הוי'<sup data-n=\"3985\">817</sup> כו', וידוע דשמיעה בבינה<sup data-n=\"3986\">818</sup> והוא בחי' ס\"ג כו', וידוע דהחכ' מקור החסדים ובינה מקור הגבורות שהן ב' קווין דחח\"נ [ו]בג\"ה כו'. ובחי' לוי הוא בחי' קו האמצעי<sup data-n=\"3987\">819</sup> דת\"י<sup data-n=\"3988\">803</sup> שכולל חו\"ג דראובן ושמעון והוא בחי' שם מ\"ה שכולל שם<sup data-n=\"3989\">820</sup> ע\"ב וס\"ג כנ\"ל. ולזה לא ייחס רק לג' שבטים הללו בשביל שלימות דיחוס תולדות אהרן ומשה שבאים משבט לוי שהוא קו האמצעי שכולל חו\"ג דראובן ושמעון, ולכך הזכיר תחלה לייחס לראובן ושמעון מפני שמהם בא בחי' התכללות [ד]חו\"ג בלוי שהוא קו האמצעי בחי' שם מ\"ה [ה]נ\"ל. ואם לא ראובן ושמעון דב' קווין דחו\"ג לא הי' קו האמצעי [שכלול משניהם כו', וכ\"ז בשביל יחוס תולדו' אהרן ומשה משבט לוי להיותם בבחי' הפנימי' דשם מ\"ה שבקו האמצעי] וכמ\"ש ונחנו מ\"ה מ\"ה ממש (וכמ\"ש מ\"ה שמו<sup data-n=\"3990\">821</sup> ומ\"ה שם בנ\"ו, ולהיותם מבחי' לוי דוקא ע\"כ ייחס לראובן ושמעון [בתחלה ג\"כ מטעם הנ\"ל, וזהו שמסיים בפ' זו הוא אהרן ומשה כו' דבשביל זה היה כונתו להזכיר יחוס ראובן ושמעון ב]תחלה, ולזה עיקר המכוון בפ' זו דאלה ראשי בית אבותם כו' וד\"ל. להיות שבחי' שם מ\"ה דמשה ואהרן הוא שורש כל התו\"מ שהוא רק לאכללא שמאלא בימינא וימינא בשמאלא<sup data-n=\"3991\">822</sup> שהוא בחי' התכללות דחו\"ג גבו' דשמאלא בחסד[י'] דימינא וימינא כו', וזהו עיקר ענין התשובה על השאלה במה שהתחיל בפ' זו (כמשי\"ת). וזהו ג\"כ מה שא' תחלה הוא אהרן ומשה ובסוף א' הוא משה ואהרן לפי ששרשם [מ]בחי' מ\"ה דקו האמצעי דלוי כנ\"ל ששם בחי' ההתכללות דחו\"ג שמאלא בימינא וימינא בשמאלא כמ\"ש משה ונחנו מ\"ה מ\"ה ב[בחי' הת]כללות ע\"כ הקדים אהרן למשה ומשה לאהרן וד\"ל.\n<b>ולהבין</b> ביאור כ\"ז הנה תחילה יש להבין ביאור טעם לבחי' ראובן ושמעון שראובן בבחי' החסד ושמעון בבחי' הגבו' כו', ותחלה יובן ע\"ד הפשוט כפי שמצינו בסיפור המעשה בכתובים אנו רואים דראובן הי' טבעו מסט' דחסד דוקא שהרי במעשה דיוסף כתיב וישמע ראובן<sup data-n=\"3992\">823</sup> ויצילהו מידם שלא הסכים כלל בהריגת יוסף וכמ\"ש אל תשפכו דם<sup data-n=\"3993\">824</sup> כו' למען הציל אותו כו' וכאשר לא מצאו בבור קרע שמלותיו וא' הילד איננו<sup data-n=\"3994\">825</sup> ואני אנה אני בא, לפי שראובן רא\"ו ב\"ן הוא מסטרא דחסד דקו הימין כנ\"ל ויוסף הוא בחי' יסוד<sup data-n=\"3995\">826</sup> כנ\"ל<sup data-n=\"3996\">827</sup> כידוע, וכאשר הצדיק אבד בגלות<sup data-n=\"3997\">828</sup> כו' שזהו בחי' יסוד אז אין מקום כלל לבחי' החסד",[["3983","815","<b>כי </b>[ה: ליתא]<b> זכר חסדו</b>: נסמן לעיל לד, ג. וראה גם לעיל כו, א ובהערה 93."],["3984","816","<b>דחס\"ד גימט' ע\"ב</b>: פרדס (שער ערכי הכינויים) שכ\"ג, מערכת חסד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380055\" data-slug=\"likkutei-torah\" data-id=\"4001380055\">לקו\"ת</a> להאריז\"ל שמות עה\"פ (ג, ד) וירא ה' כי סר לראות."],["3985","817","<b>כי שמע הוי' </b>[ט: ליתא]: ויצא כט, לג."],["3986","818","<b>דשמיעה בבינה</b>: נסמן לעיל כז, ג."],["3987","819","<b>לוי. . קו האמצעי</b>: ראה גם לעיל פ' שמות כא, ד."],["3988","803","<b>חח\"נ. . בג\"ה. . דת\"י</b>: ראה זהר (רע\"מ) בהעלותך קנג, ב. פרדס (שער סדר עמידתן) ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' ריז. וש\"נ."],["3989","820","<b>שם</b>: ניתוסף ע\"פ: ט."],["3990","821","<b>מ\"ה שמו</b>: משלי ל, ד."],["3991","822","<b>לאכללא שמאלא בימינא וימינא בשמאלא</b>: כ\"ה בכ\"מ. ראה זהר בראשית טז, ב. וארא כז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670418\" data-slug=\"torat-chaim\" data-id=\"2300670418\">תו\"ח בראשית כו, א</a> הערה 3. ולהעיר מברכות נה, ב זקפא דידא דימינא כו'."],["3992","823","<b>וישמע ראובן</b>: וישב לז, כא."],["3993","824","<b>אל תשפכו דם</b>: וישב שם, כב."],["3994","825","<b>הילד איננו</b>: שם שם, כט."],["3995","826","<b>ויוסף הוא בחי' יסוד</b>: ראה זהר (רע\"מ) פינחס רלו, א. פרדס (שער ערכי הכינויים) שכ\"ג, מערכת יוסף."],["3996","827","<b>כנ\"ל</b>: היד: ליתא."],["3997","828","<b>הצדיק אבד בגלות</b>: ישעי' נז, א. ראה זהר שמות יא, א."]]],[2300540908,"דראובן, כי כל אור החסדים אינו נמשך ונגלה רק ביסוד [ו]כמ\"ש יומם יצוה ה' חסדו<sup data-n=\"3998\">829</sup> (וכידוע דחסדים דאימא דבינה בקו השמאל מסתיים בחז[ה] כו' ומחסדים דאבא בקו ימין מאיר ביסוד<sup data-n=\"3999\">*830</sup> דוקא וז\"ש הילד איננו א\"כ אנה אני בא וד\"ל), אבל שמעון הי' מסט' דדין דקו השמאל כנ\"ל ע\"כ הי' בו בחי' דין קשה על יוסף שהרי הוא הי' הראשון שא' לכו ונהרגהו<sup data-n=\"4000\">830</sup> כו' ולזה אסר יוסף את שמעון לעיניהם<sup data-n=\"4001\">831</sup> כידוע, ולזה א' יעקב שמעון ולוי אחים<sup data-n=\"4002\">832</sup> כו' שניהם בסט' דדין קשה כמ\"ש ועברתם כי קשתה<sup data-n=\"4003\">833</sup> כו' (אך בחי' גבו' דלוי להיותם באים מהתכללות החסדים דקו הימין נמתקו ע\"י משה ואהרן כו' ומסט' דחסד דכהנים שנכללי' בהם בחי' גבו' דלוים כידוע בענין תנופת הלוים<sup data-n=\"4004\">834</sup> כו' וד\"ל).\n<b>ומעתה</b> יש להבין איך שהי' שורש ראובן ושמעון למעלה בשני קוין דחו\"ג שהוא בחו\"ב דע\"ב וס\"ג כנ\"ל, דהנה מבואר למעלה בפי' ראובן רא\"ו ב\"ן שהוא בבחי' ראי' דחכ' כו', וביאור הענין ידוע בהפרש שבין חכ' ובינה כמו שיש הפרש בין ראי' לשמיעה דאינו דומה שמיעה לראי'<sup data-n=\"4005\">835</sup> דראי' מקרוב שרואה במהות הדבר לאמיתתו כמו שהוא ממש כמו איזהו חכם<sup data-n=\"4006\">836</sup> הרואה את הנולד כמו שרואה בעיניו ממש לפי שהחכ' נק' אור המאיר כו'. וכך הוא בראיית עין השכל באלקות שהוא מקרוב דוקא שמכיר לאמיתית עצמותו ית' והוא להיותו למעלה מבחי' השגה והבנת שכל שנק' שמיעה מרחוק דלית מח' תפיסא בי' בעצמותו כו', כמו השומע גדולת המלך מרחוק שאינו דומה כלל לראי' במהותו כו', וע\"כ היא הנותנת דהחכמה מקור החסדים כי כל ראי' מקרוב מוליד אהבה וחסד היפוך הדין. וכמו שאנו רואים בחוש במי שמקורב ורואה תמיד פני המלך יהופך כל דין וקטרוג עליו לזכות וחסד משא\"כ כשאינו רואה פני מלך ישפוט אותו ע\"פ השכל המחייב רק דין, וגם מי שחטא ביותר כשיבא בראי' מקרוב יהופך מדין לחסד, אבל מרחוק ידקדקו עליו במדה\"ד לפי שע\"פ השג[ת השכל] שנק' שמיעה מרחוק יותר ידקדקו [עליו] בעיון השכל בטעמים וסברות המטים כלפי דין יותר, וכ\"ז מפני שבחי' החכ' הוא המטה כלפי חסד גם ברוב הקטרוגים יכול להפוך הכל לזכות. וראי' ממי ששכלו עמוק ורחב יותר יותר יכול לסבול כל מנגד להטות הכל כלפי חסד, וע\"כ הגדול בשנים יותר יוכל לסבול דבר המנגד ויותר יטה כלפי חסד היפוך הדין, ומי ששכלו מצומצם ביותר כתינוק לא יוכל לסבול כלל שום מנגד לפי שהשגתו בצמצום הוא ע\"כ אינו",[["3998","829","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."],["3999","*830","<b>דחסדים. . דאבא. . ביסוד</b>: ראה גם ע\"ח (שער הנסירה) שכ\"ט, פ\"ח. פ\"ט. לעיל פ' שמות לד, ב ובהערה 359."],["4000","830","<b>לכו ונהרגהו</b>: וישב לז, כ. ראה ב\"ר פפ\"ד, טז. פצ\"א, ו. תנחומא ויגש ד. מקץ — באבער — בסופו. רש\"י מקץ מב, כד."],["4001","831","<b>אסר יוסף את שמעון לעיניהם</b>: מקץ מב, כד."],["4002","832","<b>שמעון ולוי אחים</b>: ויחי מט, ה."],["4003","833","<b>ועברתם כי קשתה</b>: ויחי שם, ז."],["4004","834","<b>בענין תנופת הלוים</b>: ראה זח\"ג (תוספת) שג, א. מאמרי אדה\"ז אתהלך לאזניא ע' קנג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670451\" data-slug=\"torat-chaim\" data-id=\"2300670451\">תו\"ח וירא קטז, ד</a> ובהערה 24."],["4005","835","<b>דאינו דומה שמיעה לראי'</b>: ראה גם לעיל פ' שמות כב, ב וש\"נ."],["4006","836","<b>איזהו חכם</b>: תמיד לב, א."]]],[2300540915,"יכול לקבל דבר שנגד שכלו והבנתו כלל וכלל, משא\"כ החכם ביותר שכלו רחב ביותר לקבל כל מנגד ולהטות הכל כלפי חסד (מפני שיש לכל דבר מנגד מקום אצלו כו'). וזהו שהחסד הוא ענף החכמה דוקא לפי שהחכ' מקור החסדים, והוא בחי' שם ע\"ב במילוי יודי\"ן<sup data-n=\"4007\">837</sup> דע\"ב גימט' חס\"ד כו', וזהו בחי' ראובן רא\"ו ב\"ן דחסד דב\"ן מסט' דאבא<sup data-n=\"4008\">838</sup> קאתי, וכמ\"ש כי אתה אבינו<sup data-n=\"4009\">839</sup> כמ\"ש כי בנים אתם<sup data-n=\"4010\">840</sup> כו', וע\"כ הי' טבע ראובן להטות לחסד במעשה דיוסף כנ\"ל (וכנ\"ל בענין מ\"ש הילד איננו כו'). והוא טעם דגל מחנה ראובן תימנה לסט' דדרום כו' (וגם מטה שמעון נכלל בו<sup data-n=\"4011\">841</sup> כו'), אבל בחי' שמעון שהי' [בבחי'] דין קשה במעשה דיוסף זהו מצד שרשו בקו השמאל בגבו' דבינה כמ\"ש אני בינה לי גבורה<sup data-n=\"4012\">842</sup> כו' כמ\"ש בזוהר דבינה מינה דינין מתערין<sup data-n=\"4013\">843</sup> כו' ועד\"מ הנ\"ל במי ששכלו מצומצם רק כפי השגתו והבנתו לא יוכל לסבול למנגד ויתעורר בדין קשה על המנגד כו', והוא בחי' השמיעה שמרחוק דוקא שהוא בבינה והשגת השכל שאינו רק כפי הצמצום המושג כו' והיינו בחי' שם ס\"ג דבינה בקו השמאל והוא מקור הגבו' (ואעפ\"י שהשמחה בבינה כמ\"ש אם הבנים שמחה<sup data-n=\"4014\">844</sup> והשמחה הוא המתקת הדינין<sup data-n=\"4015\">845</sup> כידוע, זהו [ב]בחי' פנימי' בינה דוקא והוא יי\"ן<sup data-n=\"4016\">846</sup> המשמ\"ח<sup data-n=\"4017\">847</sup> כו' אבל [ב]חיצוני' דבינה דינין מתערין כנ\"ל וכמ\"ש בזוהר בענין ועבד הלוי הוא<sup data-n=\"4018\">848</sup> כו') (וכמשי\"ת). וזהו שבהשתלשלות דקו השמאל למטה מטה ביותר מסתעף דינין קשים ונק' גבור[ו]ת קשות ממש רצועא לאלקאה<sup data-n=\"4019\">849</sup> כו' והוא מבחי' ס\"ג דס\"ג שבו הי' השבירה<sup data-n=\"4020\">850</sup> כידוע (כמו שא' שמעון ולוי לכו ונהרגהו כו' ויעקב קללם וא' ארור אפם כי עז<sup data-n=\"4021\">851</sup> כו' שהגבו' קשות ממש הן בבחי' ארור דקליפה שעז ביותר כו') (אבל אור החסד גם בירידתו למטה ביותר אין אורו מתעבה<sup data-n=\"4022\">852</sup> ולא נחשך כלל מצד שרשו בחכ' שהוא מקור החסדים וכתיב ימותו ולא בחכ'<sup data-n=\"4023\">853</sup> שלא הי' בו שבירה כלל, והוא מטעם הנ\"ל בבחי' ראי' מקרוב כו'). אך הנה הלוים הגם שהיו בסט' דדין קשה דשמעון שהרי א' ארור אפם כו' המתיקו הדיני'",[["4007","837","<b>שם ע\"ב במילוי יודי\"ן</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א. (שער רפ\"ח ניצוצין) שי\"ח, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קצב."],["4008","838","<b>דב\"ן מסט' דאבא</b>: נסמן לעיל לד, ב."],["4009","839","<b>כי אתה אבינו </b>[ה: כ\"ז ליתא]: ישעי' סג, טז."],["4010","840","<b>כי </b>[יד: ליתא]<b> בנים אתם</b>: פ' ראה יד, א [בהוספת תיבת ”כי\" — ראה לקמן פ' בא צה, ב. בשלח קעב, א. תצוה שמז, ד. שעא, ג. ויקהל תכה, ב. ש\"א לא, ב. מאמרי אדה\"א ויקרא ח\"א ע' שצ. דברים ח\"א ס\"ע קעז]."],["4011","841","<b>מטה שמעון נכלל בו</b>: במדבר ב, י. יב."],["4012","842","<b>אני בינה לי גבורה</b>: משלי ח, יד."],["4013","843","<b>דבינה מינה דינין מתערין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["4014","844","<b>אם הבנים שמחה</b>: תהלים קיג, ט. ראה מאמרי אדה\"א נ\"ך ע' מח. וש\"נ."],["4015","845","<b>והשמחה הוא המתקת הדינין</b>: ראה לעיל סט, ג. וש\"נ."],["4016","846","<b>בינה. . יי\"ן</b>: נסמן לעיל נ, א."],["4017","847","<b>יי\"ן המשמ\"ח</b>: ראה ס' שופטים ט, יג. תהלים קד, טו."],["4018","848","<b>ועבד הלוי הוא</b>: נסמן לעיל לד, א."],["4019","849","<b>רצועה לאלקאה</b>: ראה זהר בהקדמה יא, ב."],["4020","850","<b>ס\"ג דס\"ג. . השבירה</b>: ראה מבו\"ש ש\"ב ח\"א, פ\"א. מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 9. לקמן פ' תשא שפה, א."],["4021","851","<b>ארור אפם כי עז</b>: ויחי מט, ז."],["4022","852","<b>אור החסד. . אין אורו מתעבה</b>: ראה פע\"ח (שער יו\"כ) שכ\"ז, פ\"ג. הובא ברמ\"ז ר\"פ יתרו סז, א. לקמן פ' ויקהל תכב, ד. מאמרי אדה\"א דברים ח\"ג ע' א'לו. וש\"נ. הנחות תקע\"ז ע' מ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670486\" data-slug=\"torat-chaim\" data-id=\"2300670486\">תו\"ח וירא קו, א</a> ובהערה 7."],["4023","853","<b>ימותו ולא בחכ'</b>: ראה גם לעיל מב, ב. וש\"נ."]]],[2300540922,"הקשים בגבו' רשפי אש התשוקה האלקי' בשיר שלהם ובעבודתם במשכן כו' וכמ\"ש ועבד הלוי הוא [כו'] והוא במה שנלוו אל הכהנים שה[ן] בקו הימין (כמשי\"ת בבחי' לוי כידוע).\n<b>והנה</b> בחי' לוי הוא הממוצע בין בחי' חסד וגבו' דראובן ושמעון כנ\"ל שהוא בקו האמצעי דת\"י כו', והענין הוא כידוע כמו שבחי' יעקב הוא בבחי' הת\"ת<sup data-n=\"4024\">854</sup> שהוא כלול מחו\"ג דאברהם ויצחק כמ\"ש אלהי אבי אברהם<sup data-n=\"4025\">855</sup> ופחד יצחק הי' לי כו', כך בחי' משה הוא בחי' הדעת<sup data-n=\"4026\">856</sup> שהוא הממוצע בין חו\"ב<sup data-n=\"4027\">857</sup>, כידוע דהדעת כולל חו\"ג<sup data-n=\"4028\">858</sup> לפי שכלול מחו\"ב והוא מחסדים דאבא דקו ימין ומגבו' דאימא דקו השמאל שהרי נק' דעת נוטה<sup data-n=\"4029\">859</sup> שמטה את השכל כלפי חסד או כלפי דין בקו המשקולת שמכריע לימין או לשמאל כו'. והוא עיקר בחי' קו האמצעי שהוא בחי' שם מ\"ה דמשה מ\"ה שמו כו' שכלול מב' שמות דע\"ב וס\"ג דחו\"ב כו', וכידוע בזוהר דמשה מלגאו ויעקב מלבר<sup data-n=\"4030\">860</sup> פי' משה הוא בחי' הדעת שכלול מחו\"ב וע\"כ<sup data-n=\"4031\">861</sup> כולל לחו\"ג היינו בחי' פנימי' דשם מ\"ה, ויעקב בחי' הת\"ת שכלול מחו\"ג ממש הוא בחי' חיצוני' והיינו יעקב מלבר והוא מדה\"ר שכלול מחו\"ג<sup data-n=\"4032\">862</sup> כידוע, והוא בחי' דעת ות\"ת דקו האמצעי שזהו כמו אור וכלי<sup data-n=\"4033\">863</sup> שהדעת הוא פנימי' לרחמים שכל מי שיש בו דעה יותר יותר ירחם כו' (כמ\"ש במ\"א בענין מי שאין בו דעה<sup data-n=\"4034\">864</sup> אסור לרחם עליו כו'). וזהו ענין לוי בכללות שהוא בחי'<sup data-n=\"4035\">*865</sup> בקו האמצעי דת\"י שכלול מחו\"ב דע\"ב וס\"ג דראובן ושמעון ע\"כ כולל חו\"ג יחד כמו להטות לזכות או לחוב כנ\"ל וד\"ל. וראי' לזה הוא ממה שמצינו בשבט לוי שהי'<sup data-n=\"4036\">865</sup> התכללות מחו\"ג דכהנים ולוים שהן ב' הפכים ממש כמים ואש שהרי הכהנים מסט' דחסד<sup data-n=\"4037\">866</sup> דוקא כידוע והלוים מסט' דדין<sup data-n=\"4038\">867</sup> דוקא (וע\"כ הזהיר להעביר תער ע\"כ בשרם כו' וכתיב הזה עליהם מי חטאת<sup data-n=\"4039\">868</sup> כו' וכמ\"ש בזוהר בענין קרח<sup data-n=\"4040\">869</sup> ), ועכ\"ז הרי היו כלולי' זב\"ז רק שהגבו' דלוים נכללו בחסדים דכהנים וכמ\"ש וילוו עליך וישרתוך<sup data-n=\"4041\">870</sup> שהיו משמשים",[["4024","854","<b>יעקב. . הת\"ת</b>: ראה זהר (ס\"ת) ויצא קנז, ב. ח\"ג (תוספת) שב, א."],["4025","855","<b>אלהי אבי אברהם</b>: ויצא לא, מב [בדילוג — ראה לקמן פ' בא קכז, ג. משפטים רפו, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תשסג. וש\"נ. שה\"א כה, א הערה 8]."],["4026","856","<b>משה. . הדעת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא</a> פמ\"ב. מאמרי אדה\"א בראשית ע' ר. וש\"נ. לעיל פ' שמות מב, א. לקמן פ' בשלח קנה, ג. משפטים רפג, ג. תצוה שנח, ג. שנט, א. שס, ב. שעח, ג. שפ, ג. ויקהל תד, ד. פקודי תנא, ג."],["4027","857","<b>הדעת. . בין חו\"ב</b>: ראה גם לקמן פ' תצוה שעז, ג. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370090\" data-slug=\"torah-or\" data-id=\"3901370090\">תו\"א תולדות יט, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370334\" data-slug=\"torah-or\" data-id=\"3901370334\">משפטים עה, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670239\" data-slug=\"torat-chaim\" data-id=\"2300670239\">תו\"ח וירא קיב, א</a>."],["4028","858","<b>דהדעת כולל חו\"ג</b>: נסמן לעיל נז, ד."],["4029","859","<b>דעת נוטה</b>: נסמן לעיל מב, א."],["4030","860","<b>דמשה מלגאו ויעקב מלבר</b>: ראה ת\"ז תי\"ג (כט, א). לקמן פ' משפטים רפג, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380634\" data-slug=\"likkutei-torah\" data-id=\"4001380634\">לקו\"ת פינחס עח, סע\"ג</a>. מאמרי אדה\"א במדבר ח\"א ס\"ע יט ואילך."],["4031","861","<b>וע\"כ</b>: ניתוסף ע\"פ: יד."],["4032","862","<b>מדה\"ר שכלול מחו\"ג</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"ב ע' תצז (נוסח ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670380\" data-slug=\"torat-chaim\" data-id=\"2300670380\">תו\"ח בראשית מ, א</a> ובהערה 4. מאמרי אדה\"א במדבר ח\"א ע' יז. לקמן פ' משפטים רפג, ד. תרומה שז, א."],["4033","863","<b>דעת ות\"ת. . אור וכלי</b>: ראה פע\"ח (שער הלולב) שכ\"ט, פ\"ג (בשם התיקונים)."],["4034","864","<b>מי שאין בו דעה</b>: ברכות לג, א. ראה מאמרי אדה\"ז תקס\"ג שם ס\"ע תצז ואילך (נוסח א). ע' תצח (נוסח ב). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550326\" data-slug=\"torat-chaim\" data-id=\"2300550326\">תו\"ח ויצא קעז, ד</a> בהערה 46. לקמן פ' משפטים רפג, ד."],["4035","*865","<b>בחי'</b>: אהטיד: ליתא."],["4036","865","<b>שהי'</b>: ניתוסף ע\"פ: יד."],["4037","866","<b>הכהנים מסט' דחסד</b>: ראה זהר נשא קמה, ב. צו כז, א. מאמרי אדה\"א הנחות תקע\"ז ע' עד. וש\"נ. לקמן הערה 869."],["4038","867","<b>והלוים מסט' דדין</b>: ראה זהר שמיני לט, א. בהעלותך קנא, ב. קרח קעז, ב. לקמן הערה 869."],["4039","868","<b>להעביר תער. . הזה עליהם מי חטאת</b>: בהעלותך ח, ז."],["4040","869","<b>בזהר בענין קרח</b>: ראה זהר תזריע מח, ב וביאוה\"ז לשם עא, ד־ אחרי עו, ב. קרח צד, ב ואילך."],["4041","870","<b>וילוו עליך וישרתוך</b>: קרח יח, ב."]]],[2300540929,"לכהנים כו'. וזהו ענין תנופ[ת] הלוים ע\"י אהרן דוקא שבתנופה זאת נתכללו בסט' דחסד כו', ולזה ציוה הוי' שיוכללו בחסדים לפי שמסתעף מהם גבו' קשות ביותר, וכמו שהי' במחלוקת קרח ועדתו ע\"כ מיד ציוה שיומתקו ע\"י החסדים דכהנים כידוע, אבל לע\"ל יהי' בהיפוך שכהנים יוכללו בלוים [ו]כמ\"ש [ו]הכהנים הלוים<sup data-n=\"4042\">871</sup> כלומר הלוים יהיו כהנים כו' לאכללא ימינא בשמאלא כו' וכמ\"ש במ\"א. וא\"כ הרי עכ\"פ יוכל להיות התכללות דחו\"ג בב' אופנים גבו' בחסדים וחסדים בגבו' וזהו אינו רק מצד ששורש הכהנים ולוים בקו האמצעי דדעת ות\"ת שהוא בחי' לוי (והוא ג\"כ מה שהתורה נמשך ע\"י הוראה דלוי כמ\"ש בלוים יורו משפטיך ליעקב<sup data-n=\"4043\">872</sup> כו' לפי שהתו' היא בקו האמצעי דת\"ת כמ\"ש מימינו א\"ש ד\"ת<sup data-n=\"4044\">873</sup> כו' והוא לאכללא שמאלא בימינא וימינא בשמאלא כענין ה\"ח וה\"ג דמ\"ע ול\"ת. וכענין אנכי ולא יהי' לך בדבור א'<sup data-n=\"4045\">874</sup> נאמרו כידוע וד\"ל).\n<b>וזהו</b> שייחס לראובן ושמעון בשביל לוי ויחס ללוי בשביל משה ואהרן שהן בבחי' פנימי' דשם מ\"ה דדעת כו' וכמ\"ש ונחנו מ\"ה מ\"ה ממש והם יחדיו כא' ממש כלולים בשם מ\"ה מבלי חילוק מדריגות ביניהם כלל, והענין הוא שהן בבחי' נו\"ה דדעת שנק' תרין פלגי גופא<sup data-n=\"4046\">875</sup> שכלולי' כא' ממש ואעפ\"י שהנצח ענף החכ'<sup data-n=\"4047\">876</sup> והוד ענף הגבו'<sup data-n=\"4048\">877</sup> מתכללי' יחד וע\"כ הי' ביניהם אהבה ואחוה ורעות, שהרי א' אהרן אחיך הלוי כו' יוצא לקראתיך וראך ושמח בלבו כו' וכתיב וישק לו<sup data-n=\"4049\">878</sup> כו', וכשהי' משה עובד בימי המלואים<sup data-n=\"4050\">879</sup> הי' אהרן משרתו בבחי' לוי<sup data-n=\"4051\">880</sup> לגבי משה שהי' כהן וז\"ש אהרן אחיך הלוי לפי שנצח דאבא שורש משה<sup data-n=\"4052\">881</sup> גובר על הוד דאמא<sup data-n=\"4053\">882</sup> שבדעת עצמו ועכ\"ז א' ונחנו מ\"ה שכלולי' כא' ממש בשם מ\"ה דבחי' הדעת. ולזה לפעמים א' הוא אהרן ומשה ולפעמים הוא משה ואהרן דלפעמים זה קודם ולפעמים זה קודם משום דכלולים זמ\"ז והי' לאחדים ממש כי שרשם א' הוא והוא הדעת שכולל חו\"ג כנ\"ל וז\"ש אהרן אחיך הלוי כו' וד\"ל. וזהו אלה ראשי בית אבותם בני ראובן כו' דהנה אעפ\"י שעיקר המכוון בייחוס ראובן ושמעון אינו רק בשביל משה ואהרן והם אינם ראשי בית אבותם כלל, עכ\"ז הוצרך דוקא להזכיר יחוס ראובן ושמעון בתחלה ואח\"כ לוי לפי שראובן ושמעון דוקא הם ראשי בית אבותם של משה ואהרן והוא מטעם הנ\"ל, דעיקר בחי'",[["4042","871","<b>[ו]הכהנים הלוים</b>: יחזקאל מד, טו. ראה לקו\"ת להאריז\"ל יחזקאל (ב). מאמרי אדה\"א דברים ח\"א ע' קפז. ח\"ג ע' א'ל. ח\"ד ע' א'תלז. ובהנסמן בהנ\"ל. בראשית ע' קעו. הנחות תקע\"ז ע' קסח."],["4043","872","<b>יורו משפטיך ליעקב</b>: ברכה לג, י."],["4044","873","<b>מימינו א\"ש ד\"ת</b>: ברכה לג, ב."],["4045","874","<b>אנכי. . בדיבור א'</b>: יתרו כ, ב. ג. ראה שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"ח."],["4046","875","<b>נו\"ה. . תרין פלגי גופא</b>: ראה זהר (רע\"מ) פינחס רלו, א."],["4047","876","<b>שהנצח ענף החכ'</b>: אוצ\"ל: החסד — ראה זהר (רע\"מ) פינחס רמג, סע\"א. הנסמן במאמרי אדה\"א קונטרסים ע' רכח."],["4048","877","<b>והוד ענף הגבו'</b>: ראה זהר (רע\"מ) פינחס רמג, ריש ע\"ב. הנסמן במאמרי אדה\"א קונטרסים שם."],["4049","878","<b>וישק לו</b>: שמות ד, כז."],["4050","879","<b>משה עובד בימי המילואים. . שהי' כהן</b>: ראה זבחים קב, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301490087\" data-slug=\"likkutei-sichot\" data-id=\"1301490087\">לקו\"ש צו [כרך לב] ע' 28</a> ואילך ובהנסמן לשם."],["4051","880","<b>בימי המילואים הי' אהרן. . לוי</b>: כ\"ה גם בהכת\"י."],["4052","881","<b>שנצח דאבא שורש משה</b>: ראה סידור שער בהמ\"ז קז, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכ."],["4053","882","<b>אהרן. . הוד דאמא</b>: ראה עמה\"מ (שער או\"א) שי\"ג, פמ\"ט (פ, ג)."]]],[2300540936,"לוי שהוא התכללות דחו\"ג שבבחי' הדעת שרש משה ואהרן אינו בא רק מהתכללות דחו\"ג שהן ראובן ושמעון בחי' ב' קווין דימין ושמאל, ושפיר שייך לקרות לראובן ושמעון אלה ראשי בית אבותם של משה ואהרן אעפ\"י שאינם ראשי בית אבותם ממש [מ\"מ נק' ראשי בית אבותם] להיותם הם כלולים בלוי שהוא קו האמצעי שאינו בא רק מכללות דראובן ושמעון שהן ב' שמות דע\"ב וס\"ג כנ\"ל שמהם בא בחי' שם מ\"ה דדעת שבאים<sup data-n=\"4054\">883</sup> יחד כו'. וע\"כ א\"א לו להתחיל מלוי בלבד בלא ראובן ושמעון בתחלה ולא הוצרך להזכיר רק לג' השבטים אלה דראובן ושמעון ולוי לפי שהם עיקר ראשי בית אבותם [ד]משה ואהרן מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b> י\"ל מה שא' הוא אהרן ומשה אשר א[מר] הוי' להם כו' ותחלה י\"ל מ\"ש על צבאותם [למעלה מצבאותם], דהנה ידוע שכאשר יעקב וביתו ירדו מצריימה ירדה שכינה עמו כמ\"ש אנכי ארד עמך מצרימה<sup data-n=\"4055\">884</sup> ואנכי אעלך כו' הרי אנכי ממש ירד עמו, והוא גילוי שכינה כמו שהוא למעלה ממש וירדה למטה היינו עם המרכבה עליונה כידוע דמעולם לא ירדה שכינה למטה בלא מרכבה כמו כל [ה]נביאים שראו גילוי שכינה עם המרכבה כמו ישעי' ויחזקאל<sup data-n=\"4056\">885</sup> גם בגלות כמו<sup data-n=\"4057\">886</sup> על נהר כבר כו', וכמו עד\"מ המלך שהולך דרך רחוקה שהוא הולך עם כל צבא חילו ומרכבתו כו'. וכך הי' בגלות מצרים כשא' ליעקב אנכי ארד עמך מצרימה כו' הלך עם כל צבא חילו וכל מרכבה עליונה כו'. וראי' לזה מיציאת מצרים כידוע בענין ס\"ר מלאכי' עליונים שיצאו עם ישראל<sup data-n=\"4058\">887</sup> ממצרים כמ\"ש בעצם היום הזה יצאו כל צבאות ה' ממש ממצרים כו'. אך כל זמן שהיו ישראל בגלות מצרים לא היו נק' בשם צבאות ה' ממש רק אחר שנגאלו ע\"י משה כתיב בעצם היום הזה דוקא יצאו כל צבאות ה' כו'. והענין הוא כידוע שיש ב' מדריגות שהן ב' שמות דהוי' ואלקי', ויש ב' מיני מרכבה א' מרכבה עליונה<sup data-n=\"4059\">889</sup> דשם הוי' דאצי' נק' צבאות הוי' כמו הוי' צבאות הוא מלך הכבוד<sup data-n=\"4060\">890</sup> כו' וכן ישעי' אמ' ואראה את הוי' צבאות<sup data-n=\"4061\">891</sup> כו', וגם בירידת האור דשם הוי' בגלות נק' הוי' צבאות כמו שא' זכרי' כה א[מר] הוי' צבאות<sup data-n=\"4062\">892</sup> כו'. והב' מרכבה תתאה<sup data-n=\"4063\">888</sup> דשם אלקי' והן מלאכי' שנק' מחנה אלקי'<sup data-n=\"4064\">893</sup> וכמרכבה דפני ארי'<sup data-n=\"4065\">894</sup> ופני שור כו' בעולם היצירה ועשי' כידוע דשם אלקי' הוא בחי' הצמצום<sup data-n=\"4066\">895</sup> וההסתר דוקא עד שמסתתר",[["4054","883","<b>שבאים</b>: ה: שכלולים. ט: כבפנים. יד: שכוללם."],["4055","884","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד. ראה גם לקמן פ' בא קכח, א. ויקהל ת, ג."],["4056","885","<b>המרכבה. . ישעי' ויחזקאל</b>: ישעי' פ\"ו. יחזקאל פ\"א. פ\"י."],["4057","886","<b>כמו</b>: ניתוסף ע\"פ: יד."],["4058","887","<b>ס\"ר מלאכי' עליונים שיצאו עם ישראל</b>: ראה מכילתא ויל\"ש בא יב, יז. תוספות השלם בא יב, מא. ציוני לך יב, ו. יל\"ר ר\"פ וישלח [ושם: ק\"ן רבוא]."],["4059","889","<b>עליונה</b>: היד: עילאה."],["4060","890","<b>הוי'. . מלך הכבוד</b>: תהלים כד, י."],["4061","891","<b>ואראה את הוי' צבאות</b>: ישעי' ו, א [ושם: ואראה את אדני]. ה: ה' צבאות ראו עיני — ישעי' ו, ה. ראה לקמן פ' בא צז, ג. קיד, ד. מאמרי אדה\"א נ\"ך ע' קמב. וש\"נ."],["4062","892","<b>כה א[מר] הוי' צבאות</b>: זכרי' א, ג. ועוד."],["4063","888","<b>מרכבה עליונה. . תתאה</b>: ראה זח\"א (רע\"מ) בהשמטות רסו, ב. (וראה גם) מאמרי אדה\"א ויקרא ח\"א ע' רכג. וש\"נ. שע\"ת צב, ג ובהערה 31."],["4064","893","<b>מלאכי' שנק' מחנה אלקי'</b>: ויצא לב, ג."],["4065","894","<b>וכמרכבה דפני ארי'</b>: יחזקאל א, י."],["4066","895","<b>דשם אלקי'. . הצמצום</b>: נסמן לעיל פ' שמות לד, ד."]]],[2300540943,"מאד להיות מלך אלקי' על גוים כו' והוא ענין גילוי אלקות<sup data-n=\"4067\">896</sup> בע\"ש. וכך הי' בגלות מצרים דכתיב אנכי ארד עמך כו' הרי הי' בחי' ירידה גדולה בהתלבשות וצמצום גדול דבחי' אלקי' [ב]מ\"ח צרופים אחרונים דמל' דמל' דעשי' [ב]שר של מצרים, וע\"כ היו ישראל אז משועבדים לפרעה בעבודה קשה בחומר ו[ב]לבנים כו' שהוא [ב]בחי' אחוריי' [ו]עורף דמל' דקליפה כו'. וע\"כ כל זמן הגלות היו ישראל במדריגה התחתונה מאד היינו למטה מטה הרבה מבחי' המלאכי' שנק' מחנה אלקי' שהיו בהתלבשות בשר של מצרים בסוד גלות השכינה כמ\"ש אנכי ארד עמך כו' (והוא מפני בחי' הבירורי' דשם ב\"ן כו' שהגלות הוא ענין הבירור כמו ענין<sup data-n=\"4068\">897</sup> הבירור לכסף במצרף כו', וע\"כ נק' גלות מצרים כור הברזל<sup data-n=\"4069\">898</sup> כו' וכמ\"ש בס' לק\"ת שדור דגלות מצרים היו נצוצות הגבוהות דדור הפלגה שנפלו בנהר נילוס<sup data-n=\"4070\">899</sup> ויצאו ל[ה]תקן בדור זה דגלות מצרים כפי מדתם לעבוד בחומר ו[ב]לבנים ויזעקו מן העבודה כו'. ובזה נתקן הפגם שפגמו דור הפלגה בעבודתם לבנות מגדל כו'), רק שהיו נשמרים שם ע\"י המלאכים דמחנה אלקי' שהיו עם השכינה כו'. ואמנם לאחר שנגאלו ממצרים ע\"י גילוי שכינה כמ\"ש ובמורא גדול<sup data-n=\"4071\">900</sup> זו גילוי שכינה שיצאו מבחי' ההסתר דשם אלקי' המצמצם כו', אז נאמר יצאו צבאות הוי' שהוא שם ה' דתיקון דאצי' שהוא למעלה הרבה מבחי' מרכבה דשם אלקי' שנושאות את הכסא דמל' דיצי' או עשי', לפי שנגאלו ע\"י משה שהוא בבחי' שם מ\"ה דדעת ש[ז]הו בחי' התיקון דהוי' דאצי' וע\"כ על ידו דוקא נתנה התורה שה[י'] בבחי' התיקון כידוע. וע\"כ נק' ישראל בשם צבאות הוי' דוקא לפי שהיו בבחי' צבאות הוי' דמרכבה עליונה שיצאו עמהם עם גילוי אור שם הוי', וראי' לזה ממ\"ש ויסע מלאך האלקי'<sup data-n=\"4072\">901</sup> ההולך לפניהם ויעמוד מאחריהם כו', וזהו מ\"ש על צבאותם למעלה מצבאותם [ה]ראשונה דמחנה אלקי' אלא על צבאותם, והוא צבאות הוי' שלמעלה הרבה משם אלקי' כידוע להיותם אחר הבירור דגלות שעלו להיות בבחי' שם [הוי' דבחי' התיקון וכמ\"ש ישראל אשר בך אתפאר<sup data-n=\"4073\">902</sup> שהוא בחי' הת\"ת דתומ\"צ ששרשו בבחי' הדעת דמשה שהוא בבחי' שם מ\"ה]. ולזה סמך זה לאחר שייחס ג' השבטים דראובן ושמעון ולוי שהוא כלול בבחי'<sup data-n=\"4074\">903</sup> התיקון דקו האמצעי שמזה יצאו תולדות אהרן ומשה כנ\"ל ע\"כ אמ' מיד הוא אהרן ומשה כו' הוציאו את בנ\"י על צבאותם כו'<sup data-n=\"4075\">904</sup> וד\"ל.\n<b>אך</b> עדיין יש להבין מה שאמר כאן הוא אהרן ומשה הזכיר אהרן תחלה ואח\"כ משה כו' וזהו שא' אשר אמר ה' להם",[["4067","896","<b>גילוי אלקות</b>: הטיד: גלות השכינה."],["4068","897","<b>ענין</b>: היד: ליתא."],["4069","898","<b>גלות מצרים כור הברזל</b>: נסמן לעיל ו, ג."],["4070","899","<b>בס' לק\"ת. . דדור הפלגה. . נילוס</b>: נסמן לעיל מ, ב."],["4071","900","<b>ובמורא גדול</b>: תבוא כו, ח ובספרי שם. הגש\"פ."],["4072","901","<b>ויסע מלאך האלקי'</b>: בשלח יד, יט [ושם: לפני מחנה ישראל וילך מאחריהם — ראה מאמרי אדה\"א נ\"ך ע' כה ובהנסמן שם]."],["4073","902","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["4074","903","<b>כלול בבחי'</b>: היד: כללות בחי'."],["4075","904","<b>כו'</b>: יד: דוקא."]]],[2300540950,"הוציאו כו' והלא עיקר הציווי הי' למשה ולא לאהרן, ולמה בענין הציווי הוציאו כו' הזכיר תחלה אהרן, להיות מבואר למעלה דשורש משה ואהרן הן בבחי' נו\"ה דאבא וידוע דאיהו (המשפיע) בנצח ואיה[י] (המקבל) בהוד<sup data-n=\"4076\">905</sup> כו', ע\"כ א' הוא אהרן הוא שושבינא דמטרוניתא דאיה[י] בהוד והוא לעשות אתעדל\"ע<sup data-n=\"4077\">906</sup> לעורר ר\"ר העליונים וז\"ש אני שמעתי את נאקת בנ\"י<sup data-n=\"4078\">907</sup> כו' לכן אמור לבנ\"י כו'. וזהו שהזכיר אהרן תחלה במ\"ש אשר א' הוי' להם הוציאו כו' כי כדי שיהי' התעוררות ר\"ר שיומשך מלמעלה למטה ע\"י העלאות מ\"נ דצעקת בנ\"י מלמטה הרי אהרן הי' המעלה אתעדל\"ע<sup data-n=\"4079\">908</sup> להיות אתעדל\"ע דר\"ר כו' להיות נגאלים. אך<sup data-n=\"4080\">909</sup> בבחי' הגאולה ממש שהוא לדבר אל פרעה להוציא את בנ\"י בפו\"מ [א' הם המדברים אל פרעה כו' הוא משה ואח\"כ אהרן כו'] להיות[ו] בבחי' שושבינא דמלכא להמשיך כח אור א\"ס למטה להיות הגאולה בפ\"מ משום דאיהו בנצח שזהו שורש משה כו'.\n<b>ובזה</b> יתור[צו] כל הדקדוקי' הנ\"ל בסדר פרשה זו. ובענין התשובה דוארא על מה שא' למה הרעות כו', דהנה משה<sup data-n=\"4081\">910</sup> א' לה' ומאז באתי [אל פרעה]<sup data-n=\"4082\">911</sup> לדבר בשמך שהוא שם הוי' דוקא דמשה ואהרן א' לפרעה בשם הוי' כה אמר<sup data-n=\"4083\">912</sup> כו' הרע לעם הזה משום דשורש של<sup data-n=\"4084\">913</sup> פרעה באחוריי' דשם אלקי' המצמצם דמלך אלקי' על גוים, לא ידע בשם הוי' כלל, ע\"כ א' מי הוי'<sup data-n=\"4085\">917</sup> אשר כו' וכמו שא' בסוף לפרעה<sup data-n=\"4086\">914</sup> וידעו מצרים כי אני הוי'<sup data-n=\"4087\">915</sup> שע\"י האותות ומופתים נגלה להם שם הוי' שלמעלה משרשם באלקי' כו' ע\"כ נכנע פרעה. וזהו שהשיב לו עתה תראה אשר אעשה לפרעה והתחיל לומר לו אני הוי' וארא כו' ושמי הוי' לא נודעתי להם כו' כי הגם שיעקב הוא בבחי' הת\"ת כלול מחו\"ב<sup data-n=\"4088\">916</sup> דע\"ב וס\"ג מ\"מ אין זה שם הוי' דשם הוי'<sup data-n=\"4089\">926</sup> הפנימי' דמשה הנ\"ל שורש<sup data-n=\"4090\">918</sup> הדעת דמשה מלגיו [ואיהו שם מ\"ה מלגיו<sup data-n=\"4091\">919</sup> ] דאיהו אורח כל<sup data-n=\"4092\">*920</sup> האצי' שקיו דאילנא כו' שהוא שורש התורה. וגם הקימותי<sup data-n=\"4093\">920</sup> כו' לתת להם את ארץ כנען כו' שהוא שם ב\"ן<sup data-n=\"4094\">921</sup> לאחר הבירור. וגם אני שמעתי כו' לכן אמ[ו]ר לבנ\"י אני הוי' כו' עד והייתי לכם לאלקי'<sup data-n=\"4095\">922</sup> פי' להאיר להם משם מ\"ה דתו\"מ דוקא שלא נודע לאבות כלל. וגם והבאתי אותם<sup data-n=\"4096\">923</sup> אל הארץ שהוא שם ב\"ן להיות להם למורשה<sup data-n=\"4097\">924</sup> דוקא שהוא א\"י כשיקיימו תו\"מ דוקא<sup data-n=\"4098\">925</sup> ארץ ישראל ע\"ש התיקון דמ\"ה מברר לב\"ן כו' אני הוי'. ואמנם איך יכול להיות בחי' גילוי שם הוי' זה להם, והי' רוצה שיהי' ע\"י משה לבדו בלא",[["4076","905","<b>דאיהו. . בהוד</b>: נסמן לעיל פ' שמות טו, א."],["4077","906","<b>אתעדל\"ע</b>: ה: אתעדל\"ת."],["4078","907","<b>אני שמעתי את נאקת בנ\"י</b>: וארא ו, ה."],["4079","908","<b>אתעדל\"ע</b>: א: אתעדל\"ת."],["4080","909","<b>אך</b>: היד: אבל."],["4081","910","<b>משה</b>: ניתוסף ע\"פ: יד."],["4082","911","<b>ומאז באתי [אל פרעה]</b>: שמות ה, כג."],["4083","912","<b>כה אמר</b>: ניתוסף ע\"פ: יד. — שמות ה, א."],["4084","913","<b>של</b>: ניתוסף ע\"פ: יד."],["4085","917","<b>הוי'</b>: היד: מ\"ה."],["4086","914","<b>לפרעה</b>: ה: הפרשה."],["4087","915","<b>וידעו מצרים כי אני הוי'</b>: וארא ז, ה."],["4088","916","<b>מחו\"ב</b>: טיד: מחו\"ג."],["4089","926","<b>הוי'</b>: אה: מה."],["4090","918","<b>שורש</b>: היד: שהוא."],["4091","919","<b>ואיהו שם מ\"ה מלגיו</b>: נסמן לעיל פ' שמות יג, ד."],["4092","*920","<b>כל</b>: נסמן לקמן פ' בא קיג, ג."],["4093","920","<b>וגם הקימותי</b>: וארא ו, ד."],["4094","921","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670512\" data-slug=\"torat-chaim\" data-id=\"2300670512\">ארץ כנען. . שם ב</a>\"ן</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קמט. שע\"ת קג, ד. מאמרי אדה\"א נ\"ך ע' קצד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680272\" data-slug=\"torat-chaim\" data-id=\"2300680272\">תו\"ח לך פט, ד</a>. תולדות קנג, ב."],["4095","922","<b>והייתי לכם לאלקי'</b>: וארא ו, ז."],["4096","923","<b>והבאתי אותם </b>[יד: אתכם]: וארא ו, ח."],["4097","924","<b>להם </b>[ה: לכם]<b> למורשה</b>: וארא שם."],["4098","925","<b>דוקא</b>: אה: שנק'. יד: כבפנים."]]],[2300540957,"אתעדל\"ת ע\"י אהרן וע\"כ א' מיד בא דבר אל פרעה<sup data-n=\"4099\">927</sup> וישלח את בני ישראל כו', והשיבו משה הן בנ\"י<sup data-n=\"4100\">928</sup> לא שמעו אלי ואיך ישמעני פרעה כו' וא' וידבר הוי' אל משה ואל אהרן ויצום<sup data-n=\"4101\">929</sup> אל בני ישראל ע\"י אהרן ואל פרעה ע\"י משה מטעם הנ\"ל. לכך התחיל לייחס ג' השבטים דראובן ושמעון ולוי, ואמר<sup data-n=\"4102\">930</sup> אלה הם ראשי בית אבותם שמהם יצאו משה ואהרן בחי' שם מ\"ה הנ\"ל כמ\"ש ונחנו מ\"ה שלזה א' הוא אהרן ומשה הוא משה ואהרן שמתכללי' כא' להיותם בנצח והוד תרין פלגי גופא כנ\"ל. וע\"כ א' בסמוך לפרשה זו וידבר הוי' אל משה אני הוי' דבר אל פרעה<sup data-n=\"4103\">931</sup> כו' נתתיך אלקים לפרעה כו' [ו]אהרן אחיך יהי' לך לפה מטעם הנ\"ל עד סוף הפ' שא' וידעו מצרים כי אני הוי' דוקא ואז א' וילך משה ואהרן<sup data-n=\"4104\">932</sup> כאשר צוה הוי' כן עשו פי' בכאן נגמר הדבר לבא בפ\"מ שיהי' גילוי שם הוי' אל פרעה שיכנע וישלח את בני ישראל, וגם נמשך שם מ\"ה דהוי' דתומ\"צ לישראל וע\"כ כפל הדבר בעשי' זו כי הרי זה כאלו כבר עשו, והיינו מה שא' למשה תחלה עתה תראה אשר אעשה לפרעה וד\"ל.",[["4099","927","<b>בא דבר אל פרעה</b>: וארא ו, יא [בדילוג]."],["4100","928","<b>הן בנ\"י</b>: וארא שם, יב."],["4101","929","<b>וידבר. . ויצום</b>: שם שם, יג."],["4102","930","<b>ואמר</b>: ניתוסף ע\"פ: יד."],["4103","931","<b>וידבר ה'. . דבר אל פרעה</b>: וארא ו, כט."],["4104","932","<b>וילך </b>[היד: ויעש]<b> משה ואהרן</b>: וארא ז, ו [בדילוג]."]]],[2300540061,"<b>ב\"ה פ' בא חג הפסח תקפ\"ג</b>\n<span data-k=\"pg\">קכג</span> ּ[א] ועבר ה' לנגוף<sup data-n=\"4105\">1</sup> את מצרים וראה את הדם על המשקוף וב' המזוזו' ופסח<sup data-n=\"4106\">2</sup> ה' על הפתח כו', הנה באמת יש להבין בשרש ענין חג הפסח שהטעם שנק' חג הפסח דוקא ידוע במ\"ש ואמרתם זבח פסח<sup data-n=\"4107\">3</sup> הוא כו' אשר פסח ה' על בתי בנ\"י כו' והוא מ\"ש כאן ועבר ה' כו' ופסח ה' על הפתח, ופסיחה זו הוא ענין דילוג<sup data-n=\"4108\">*4</sup> הוא וכמו קול דודי מדלג<sup data-n=\"4109\">4</sup> על ההרים ומה שנק' דילוג בשה\"ש נק' כאן פסח, אך יש להבין מ\"ש על הפתח דוקא הי' הפסיחה הזאת, ומהו ענין טעם הפסיחה לפי שראה ירא' את הדם על המשקוף וב' המזוזות דוקא כו', והנה יש להקדים תחלה ענין מ\"ש ויהי בחצי הלילה<sup data-n=\"4110\">5</sup> וה' הכה כל בכור באמ\"צ כו' וארז\"ל וה' הוא ובית דינו<sup data-n=\"4111\">6</sup> דוקא, וידוע דשם הוי' הוא בחי' חסד<sup data-n=\"4112\">7</sup> וב\"ד הוא בחי' הגבורה<sup data-n=\"4113\">8</sup> והי' בזה התכללות מחו\"ג יחד ולכאורה איך יכול להיות חיבור ב' הפכים כא', אך הנה ע\"ד הפשוט יובן ע\"פ פשוט לפי שא' ונגפתי את מצרים<sup data-n=\"4114\">9</sup> נגוף ורפוא נגוף למצרים ורפוא לישראל<sup data-n=\"4115\">10</sup>, וכמו שהי' ברוב המכות שהי' מכה למצרים והצלה לישראל כמו במכת ערוב שנא' והפליתי כו' ושמתי",[["4105","1","<b>ועבר ה' לנגוף</b>: מיוסד על ד\"ה זה שנדפס במאמרי אדה\"ז תקס\"ז ע' קי הנחת כ\"ק אדה\"א [ושם קרוע כמעט כל המאמר ונמצא בשלימות בבוך 66 ע' צה]. והנחת הר\"מ נדפסה שם ע' קיד ופתיחתה משא מצרים הנה ה' רוכב על ע\"ב ק\"ל. הנחת אדה\"א הנ\"ל נדפסה עם הערות וכו' מהצ\"צ באוה\"ת בא (כרך ז) ע' ב'תרלג ואילך. וראה גם (כרך ח) ע' ב'תתקמד ואילך. סה\"מ תרמ\"ו ע' ז. תרנ\"ח ע' צה. תרע\"ח ע' רלט. תש\"ו ע' 69. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["4106","2","<b>ועבר ה' לנגוף. . ופסח</b>: בא יב, כג [ושם: ועל שתי]."],["4107","3","<b>ואמרתם זבח פסח</b>: בא יב, כז [ושם: הוא לה' אשר פסח]."],["4108","*4","<b>ופסיחה. . דילוג</b>: ראה רש\"י בא יב, יא. יג. לקמן צ, ג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקלד. מאמרי אדה\"א הנחות תקע\"ז ע' כא וע' לא. אוה\"ת ויקרא (כרך ד) ס\"ע תתקעח ואילך."],["4109","4","<b>קול דודי מדלג</b>: שה\"ש ב, ח [בדילוג]."],["4110","5","<b>ויהי בחצי הלילה</b>: בא יב, כט."],["4111","6","<b>וה' הוא ובית דינו</b>: במאמרי אדה\"ז תקס\"ז הנחת הר\"מ כאן: ונז' בזוה' ע\"ז — זהר בא לז, ב. וראה גם הנסמן לעיל פ' שמות יא, ד."],["4112","7","<b>דשם הוי'. . חסד</b>: ראה גם לקמן פ' תרומה דש, ד. תצוה שיח, ד. מאמרי אדה\"א בראשית ע' קעג. דברים ח\"ג ע' תתקפא. נ\"ך ע' קכג ובהנסמן בהנ\"ל."],["4113","8","<b>וב\"ד. . הגבורה</b>: ראה גם ביאוה\"ז תשא נה, ב. דרמ\"צ ע, א ואילך."],["4114","9","<b>ונגפתי את מצרים</b>: וכ\"ה בסמוך. במאמרי אדה\"ז תקס\"ז כאן: ונגף ה' את מצרים, ומציין הצ\"צ ע\"ז בישעי' סי' יט, כב."],["4115","10","<b>נגוף למצרים ורפוא לישראל</b>: זהר בא לו, א."]]],[2300540099,"פדות<sup data-n=\"4116\">11</sup> כו' וכן בדבר וממקנה ישראל<sup data-n=\"4117\">12</sup> לא מת אחד וכן בחשך ולכל בנ\"י הי' אור<sup data-n=\"4118\">13</sup> כו' עד מכת בכורות שהי' נגע האחרונה וקשה מכולן שהוא גמר הדבר להיותו נגד בחי' החכ'<sup data-n=\"4119\">14</sup> ובזה יהי' הצלה לבכורי ישראל כמ\"ש משה לפרעה כחצות הלילה<sup data-n=\"4120\">15</sup> כו' ומת כל בכור<sup data-n=\"4121\">16</sup> כו' ולכל בנ\"י לא יחרץ<sup data-n=\"4122\">17</sup> כו' למען תדעון אשר יפלה ה' כו' וע\"כ א' קדש לי כל בכור<sup data-n=\"4123\">18</sup> כו', וא\"כ הרי בהכותו כל בכור באמ\"צ באותה השעה עצמ' הי' צריך להציל לישראל ונמצא הי' בחי' דין למצרים וחסד ורחמים לישראל בשעה ורגע א' ממש והוא בחצות הלילה דוקא (כמשי\"ת), ולכך א' וה' הוא וב\"ד לפי שז\"ש נגוף ורפא נגוף למצרים בדין קשה ורפוא לישראל שכלול בזה חו\"ג יחד שבאמת זהו פלא גדול שא\"א שישלטו ב' מדות הפכי' כאלה ברגע א' שהרי בשעה שהדין שולט אין מקום למדת חסד ורחמים כלל שהרי אין מרחמים בדין<sup data-n=\"4124\">19</sup> כלל (ומ\"ש ברוגז רחמי' תזכור<sup data-n=\"4125\">20</sup> זהו לישראל לבד, לפי שזהו בטבע רחמי האב על הבן דגם בקצפו עליו יזכור רחמי' העצמיי' כו', וכ\"ש כאן שנזכר ברחמי' לישראל בשעה שהי' הדין למצרים כו' לפי שהי' צריך להבדיל ביניהם בתכלית כמ\"ש או הנסה אלקי'<sup data-n=\"4126\">21</sup> לקחת גוי מקרב גוי כו', הרי אותו מדה\"ד עצמו",[["4116","11","<b>והפלתי. . ושמתי פדות</b>: וארא ח, יח. יט."],["4117","12","<b>וממקנה ישראל</b>: וארא ט, ו [ושם: בני ישראל]."],["4118","13","<b>ולכל בנ\"י הי' אור</b>: בא י, כג."],["4119","14","<b>בכורות. . החכ'</b>: נסמן להלן הערה 35."],["4120","15","<b>כחצות הלילה</b>: בא יא, ד."],["4121","16","<b>ומת כל בכור</b>: בא שם, ה."],["4122","17","<b>ולכל בנ\"י לא יחרץ</b>: שם שם, ז."],["4123","18","<b>קדש לי כל בכור</b>: בא יג, ב."],["4124","19","<b>אין מרחמים בדין</b>: כתובות פד, א (במשנה)."],["4125","20","<b>ברוגז רחמי' תזכור</b>: חבקוק ג, ב [ושם: רחם — ראה לקמן פ' תצוה שנג, ג הערה 480. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670508\" data-slug=\"torat-chaim\" data-id=\"2300670508\">תו\"ח בראשית כח, ג</a> הערה 15]."],["4126","21","<b>או הנסה אלקי'</b>: ואתחנן ד, לד [ושם: לבוא לקחת לו]."]]],[2300540137,"דוקא שהי' למצרים הוא עצמו שהי' מדה\"ר לישראל כמו עד\"מ שמשכל וטעם זה עצמו שהוא מחייב לזה הוא עצמו הטעם שמזכה לזה וכמו במ\"ת שירדה שנאה לאוה\"ע<sup data-n=\"4127\">22</sup> כו' דהא בהא תליא. אך א\"כ אין כאן ב' הפכים דחו\"ג כלל בנגוף ורפוא מאחר שמצרים וישראל ב' הפכים הן וכשנגף לזה ממילא רפוא לזה כנ\"ל, הענין הוא דזה עצמו לעשות הבדלה זו עצמה להיות ישראל ומצרים ב' הפכים עד שיהי' נגף למצרים רפא לישראל כמ\"ש לקחת גו\"י מקר\"ב גו\"י באותות ומופתים כו' ויהי' המופת להבדיל בינם עד שיהי' מנגף דמצרים רפוא לישראל, ה\"ז עצמו התכללו' דבר והיפוכו כא' ומהתכללות דחו\"ג כזה מתחלק להיות <span data-k=\"pg\">248</span> ּ חסד לישראל ודין למצרים שהוא התחלקות אחר ההתכללות ושרשו הוא בהבדלה הראשונה בפנימי' ועצמו' הרוממות ממש (כמשי\"ת<sup data-n=\"4128\">23</sup> ), ואין דין ועונש בשעת החסד והרחמים, וגם אם הי' חסד ורחמים לישראל והדין והעונש למצרים מ\"מ איך שלטו ב' מדות דחו\"ג כאלה שהן ב' הפכים מן הקצה לקצה ברגע א', והעיקר במכות בכורות שלטו ב' מדות דחו\"ג בהתכללות א' ברגע לנגוף למצרים ורפוא לישראל כו' (ומשמע דב' מדות אלה מדה א' הי' דמכח הדין למצרים נמשך החסד לישראל כנ\"ל, או שבסיבת אור החסד לישראל להצילם ולהוציאם מקליפ' דנש\"ט נמשך הדין דמכ' בכורו' למצרים כו'). ובאמת כפי הפשוט בפי' נגוף ורפוא קאי הכל על מצרים<sup data-n=\"4129\">24</sup> כמ\"ש ונגפתי את מצרים נגוף ורפוא כו'. והענין הוא כפשוטו משום דכל המכות הי' דין קשה בתחלתו וסופו חסד ורחמים כי הי' פרעה מבקש ממשה להתפלל להסיר מעליו המכה ונגע והתפלל משה ונענה, אף שזה הי' כדי להכביד את<sup data-n=\"4130\">25</sup> לבו כו' ולמען יספר כו' עכ\"ז לא הי' הדין הקשה בכל המכות לתכליתו רק לשעה לבד, וזהו נגוף ומיד רפו\"א למצרים. והטעם הי' להראות לפרעה דק\"נ שמקבלים מדינין וצמצומי' דאחוריים דשם אלקי', שבחי' החסד גדול כחו לעשות כרצונו לבטל לדין קשה, והוא חסדים דשם הוי' שגובר על בחי' גבורו' דשם אלקי' וכמ\"ש וידעו מצרים כי אני הוי'<sup data-n=\"4131\">26</sup>, דבחי' החסד שמושל על שם אלקי' וממילא כל כחו' הדינין שנשתלשלו משם אלקי' למטה מטה מתבטלים לגמרי מפני שם הוי', והן הי' ענין המכות בדין קשה לשבור אותם בתוקף הגבורו' העליונו' ולהמתיקם מיד בחסדים דשם הוי' ע\"י תפלת משה להראותם ששם הוי' עיקר והריוח והצלה שהי' ע\"י תפלת משה אחר מעשה הדין הקשה גדול כחו מגוף הדין כו', והי' זה יותר לפלא גדול בעיני פרעה וזקיניו מגוף המופתים במכות שגם חרטומי מצרים יכלו לעשות כן, רק",[["4127","22","<b>במ\"ת שירדה שנאה לאוה\"ע</b>: שבת פט, סע\"א."],["4128","23","<b>(כמשי\"ת)</b>: כנראה כאן הוא סיום הסוגר שהתחיל לעיל פז, ב בשו\"ה בדין — (ומ\"ש."],["4129","24","<b>קאי הכל על מצרים</b>: רש\"י ישעי' שם. מגילה יג, ב. שהש\"ר פ\"ד, ה (א)."],["4130","25","<b>את</b>: בגוכי\"ק אינו ברור. בד: ליתא."],["4131","26","<b>וידעו מצרים כי אני הוי'</b>: וארא ז, ה."]]],[2300540174,"להמתיק הדין ולהפכו לחסד כמו להוציא הכנים לא יכלו<sup data-n=\"4132\">27</sup> כו'. וז\"ש נגו\"ף ורפו\"א למצרים שלמדות אלה חו\"ג שבמכות עצמם אין כאן דבר והיפוכו כי שם אלקים דבחי' הדין<sup data-n=\"4133\">28</sup> מתייחד ומתכלל בשם הוי' דחסד כמ\"ש כי הוי' הוא האלקי'<sup data-n=\"4134\">29</sup> והוא מ\"ש יתרו עתה ידעתי כי גדול הוי' מכל האלקי\"ם<sup data-n=\"4135\">30</sup> כו', וזהו ג\"כ ענין מה שארז\"ל נגוף למצרים ורפוא לישראל גם בתחילת הדין הקשה הפלה ה' לישראל כו' לפי שישראל הן בבחי' שם הוי' דחסד שלא שלט בהן בחי' דינין קשי' דשם אלקי' שירדו להכות לאלקי מצרים כלל, והכל הוא נכלל בענין מ\"ש וה' הכה כו' הו\"א וב\"ד שהוא שם הוי' ואלקים שכלולים חו\"ג יחד למעלה כנ\"ל)<sup data-n=\"4136\">31</sup>.\n<b>אך</b> מה שלא א' וה' הוא וב\"ד בכל המכות רק במכו' בכורות דוקא, הענין הוא ע\"ד הפשט דבמכ' בכורו' הי' הדין הקשה נעשה בפו\"מ שמת כל בכור<sup data-n=\"4137\">32</sup> באמ\"צ מבכור פרעה כו' עד בכור השפחה כו' ולא הוחזר לחסד כלל כשאר המכות והוא הי' גמר הדבר להוציא ולהבדיל לפרי מקליפתו, ישראל ממצרים כידוע, ונמצא שהי' מכה זו ע\"פ כח הדין של ב\"ד העליון שנמשך בחי' הגבו' למטה לפעול הדין בפו\"מ להרוג כל בכור כו' והי' זה ע\"י הסכם דשם הוי' דוקא וכמ\"ש וה' הוא וב\"ד דמשמע שהוי' הסכים עם <span data-k=\"pg\">קכד</span> ּ ב\"ד שהוא שם אלקי' ואד' דינא דמל'<sup data-n=\"4138\">33</sup> כו' וכמ\"ש ויהרוג הוי' כל בכור<sup data-n=\"4139\">34</sup> כו' והי' הצלה לבכורי ישראל שזהו עיקר ההבדלה הפנימי' כנ\"ל דהיינו בשם הוי' עצמו נמשך להיות כח הדין קשה בפו\"מ להרוג כל בכור מצרים שהוא חכ'<sup data-n=\"4140\">35</sup> דק\"נ ולהציל לבכו\"ר ישראל שמפני זה א' קד\"ש לי כל בכו\"ר כו' והוא מ\"ש או הנסה אלקים לקחת לו גו\"י מקרב גו\"י כו' לעשות הבדלה כזו להוציא פרי מקליפתו במסות באותות כו' והוא הי' במכ' בכורו' דוקא שהי' נגו\"ף למצרים ורפוא לישראל בפו\"מ כו' שזה הי' ע\"פ בחי' הדין דשם הוי' דוקא ובזה יש התכללות דחסד דהוי' בגבורו' ודינין דאלקים שבהוי' עצמו ולא כשאר המכות שנמתקו ע\"י חסדים דשם הוי' כנ\"ל וד\"ל)<sup data-n=\"4141\">36</sup> (ובזהר<sup data-n=\"4142\">37</sup> א' על מ\"ש ויהרוג הוי' כו' דכמו דסט\"א קטיל ואפיק נשמתי' בההוא גונא ממש עביד קוב\"ה ויהרוג הוי' כו' וז\"ש לסוסתי כו' דמיתיך רעייתי<sup data-n=\"4143\">38</sup> כו', והוא להוציא ולהפוך כח ושרש הראשון דק\"נ שהוא כו\"ח<sup data-n=\"4144\">39</sup> דקליפה שקדמה לפרי<sup data-n=\"4145\">40</sup> כו', שזהו בכור אותיות ברוך<sup data-n=\"4146\">41</sup>, והוא מ\"ש והי' בן הבכו\"ר לשניא\"ה<sup data-n=\"4147\">42</sup> דעשו הוא הבכור<sup data-n=\"4148\">43</sup> כמו שהוא בשרשו בחושך שקדם לאור וכמ\"ש ואלה המלכים<sup data-n=\"4149\">44</sup> כו' וע\"י בחי' התיקון דשם הוי' דכו\"ח",[["4132","27","<b>להוציא הכנים לא יכלו</b>: וארא ח, יד."],["4133","28","<b>אלקים דבחי' הדין</b>: נסמן לעיל פ' וארא סה, א."],["4134","29","<b>כי הוי' הוא האלקי'</b>: ואתחנן ד, לה. לט."],["4135","30","<b>עתה ידעתי. . האלקי\"ם</b>: יתרו יח, יא."],["4136","31","<b>כנ\"ל)</b>: בגוכי\"ק לא נרשם התחלת הסוגר."],["4137","32","<b>שמת כל בכור</b>: בא יא, ה."],["4138","33","<b>ואד' דינא דמל'</b>: נסמן לקמן בהערה 51."],["4139","34","<b>ויהרוג הוי' כל בכור</b>: בא יג, טו. ראה גם לעיל פ' וארא נד, ב."],["4140","35","<b>בכור. . חכ'</b>: ראה זהר בהקדמה יג, ב. ואתחנן רסב, א. פרדס (שער ערה\"כ) שכ\"ג, מערכת בכור. מאמרי אדה\"א ויקרא ח\"א ע' סב. וש\"נ."],["4141","36","<b>וד\"ל)</b>: בגוכי\"ק לא נרשם התחלת הסוגר."],["4142","37","<b>ובזהר</b>: ראה זהר ס\"פ ויגש ריא, ב. ביאוה\"ז שם קלו, ב ואילך. מאמרי אדה\"א בראשית ע' תקכא."],["4143","38","<b>לסוסתי. . רעייתי</b>: שה\"ש א, ט."],["4144","39","<b>כו\"ח</b>: כתר וחכמה."],["4145","40","<b>דקליפה שקדמה לפרי</b>: לקמן פ' בשלח קלה, א בשם הזהר. ראה זהר (סבא) משפטים קח, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"א ע' רט. וש\"נ. לעיל פ' שמות מא, ג. לקמן פ' בשלח קצב, ג."],["4146","41","<b>בכור אותיות ברוך</b>: ראה פע\"ח (שחה\"מ) שכ\"א, פ\"ז (קרוב לסופו)."],["4147","42","<b>והי' בן הבכו\"ר לשניא\"ה</b>: תצא כא, טו [ושם: הבן — ראה מאמרי אדה\"א דברים ח\"ב ע' תקצג]."],["4148","43","<b>דעשו הוא הבכור</b>: תולדות כה, כה. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכד וע' תשל. מאמרי אדה\"א דברים ח\"ב ע' תקע ואילך וע' תקצג ואילך."],["4149","44","<b>ואלה המלכים</b>: נסמן לעיל פ' שמות מג, ג."]]],[2300540211,"דקדושה שז\"ש את בכורת\"י לק\"ח וגם ברכתי<sup data-n=\"4150\">45</sup> כו' שעי\"ז ניתוסף האור בשם הוי' דיתרון האור מן החשך<sup data-n=\"4151\">46</sup> כידוע, וזהו ויהרוג הוי' דוקא שהוא ע\"י תו\"מ שישראל כו' שמהפכי' חשך לאור, והיינו כמו דסט\"א קטיל כו' להוסיף יניקה לחיצונים מהיפוך האור דקדושה דנשמת הוי' לחושך כו' וכמ\"ש במ\"א). וז\"ש וה' הכה כו' הוא וב\"ד שהוא בחי' הדין שבחסד דהוי' שהוא תכלית ההבדלה הפנימי' להבדיל בין קדש לחול כו', שלזה הי' רבותא גדולה יותר הצלת ישראל במכת בכורו' יותר משאר המכות עד שהוצרך לראות הדם על המשקוף<sup data-n=\"4152\">47</sup> כו' ואם לאו לא היו ניצולים כלל אע\"פ שבשאר המכות הפלה ה' כו', והוצרך להיות בחצו' לילה<sup data-n=\"4153\">48</sup> דוקא (כמשי\"ת), משא\"כ בשאר המכות שהיו כולם ביום דוקא וד\"ל.\n<b>וזש\"א</b> וה' הכה כו' הוא וב\"ד כו' שזהו בחי' זו\"נ דאצי' שבחי' המל' נק' ב\"ד<sup data-n=\"4154\">49</sup> דז\"א דצדק איהי דין<sup data-n=\"4155\">50</sup> דינ\"א דמלכותא דינא אותיות אדנ\"י<sup data-n=\"4156\">51</sup>, וכן א' הנה ה' רוכ\"ב<sup data-n=\"4157\">52</sup> על עב קל ובא מצרים כו' פי' ע\"ב קל ע\"ב הוא בחי' כלי החכ'<sup data-n=\"4158\">53</sup> שהוא שם ע\"ב והן בחי' ע\"ב גשרים<sup data-n=\"4159\">54</sup> דחס\"ד שחס\"ד גימט' ע\"ב<sup data-n=\"4160\">55</sup> והיינו מטעם דהחס\"ד ענף החכ'<sup data-n=\"4161\">56</sup> כידוע, וק\"ל הוא בחי' גבו' (די' פעמים הוי' הוא ר\"ס שזהו כי ס\"ר לראות<sup data-n=\"4162\">57</sup> וחלק החצ' דמל' שהוא בחי' הגבו' היינו ק\"ל וע\"ז א' נשים דעתן קלות<sup data-n=\"4163\">58</sup> שהוא בחי' עטרא דגבורה דנוק' כו'), וז\"ש ה' רוכב על ע\"ב ק\"ל הוא בחי' התכללו' דחו\"ג דדכר ונוק' שבחי' הזכר רובו חסדים<sup data-n=\"4164\">59</sup> ומיעוטו גבורה והנוק' רובה גבורה<sup data-n=\"4165\">60</sup> ומיעוטה חסדים כמו כי זכ\"ר חסדו<sup data-n=\"4166\">62</sup><sup data-n=\"4167\">61</sup>, וכך א' בלילא מאי עביד<sup data-n=\"4168\">63</sup> קוב\"ה רוכב על כרו\"ב ק\"ל שלו ושט בח\"י אלף עולמות שזהו התלבשות החסדי' דשם הוי' בגבורה דנוק' שנק' כרו\"ב ק\"ל ושט כו' ונק' רכב אלקי\"ם רבותיי'<sup data-n=\"4169\">64</sup> כו' שעי\"ז עולה בהעלא' למעלה בח\"י אלף כו', וכך הוא בבחי' ירידה שרוכב על ע\"ב ק\"ל ובא מצרים לברר להיכלות דק\"נ וכמ\"ש ועברתי באמ\"צ אני ולא מלאך<sup data-n=\"4170\">65</sup> כו' והיינו בב' מדות דחו\"ג דע\"ב ק\"ל וזהו וה' הוא וב\"ד יחד בבחי' התכללות דחו\"ג דוקא להיות נגוף <span data-k=\"pg\">250</span> ּ למצרים ורפוא לישראל במכ\"ב כו' כנ\"ל וד\"ל.",[["4150","45","<b>את בכורת\"י. . ברכתי</b>: תולדות כז, לו [ושם: והנה עתה לקח ברכתי]."],["4151","46","<b>דיתרון האור מן החושך</b>: קהלת ב, יג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קסט. וש\"נ. בראשית ע' תט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, ד</a>."],["4152","47","<b>לראות הדם על המשקוף</b>: בא יב, ז. יג. כג."],["4153","48","<b>בחצו' לילה</b>: בא יא, ד. יב, כט."],["4154","49","<b>המל' נק' ב\"ד</b>: ראה גם זהר משפטים קיז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קיח וע' קכא. שע\"ת טז, א הערה 6. לקמן פ' משפטים רצא, ב."],["4155","50","<b>דצדק איהי דין</b>: ראה ת\"ז בהקדמה (יז, ב). הדרת מלך סקע\"ו (קיג, ב). מאמרי אדה\"א דברים ח\"ב ע' תרנט. וש\"נ."],["4156","51","<b>דינ\"א דמלכותא דינא אותיות אדנ\"י</b>: גיטין י, ב. ראה זהר (רע\"מ) משפטים קיח, א. פינחס רנז, סע\"ב. סידור תפלת ר\"ה רלו, ג ואילך. מאמרי אדה\"א דברים ח\"ג ע' א'ט ואילך. דברים ח\"א ע' רלח. וש\"נ."],["4157","52","<b>הנה ה' רוכ\"ב</b>: ישעי' יט, א."],["4158","53","<b>ע\"ב. . כלי החכ'</b>: נסמן לעיל פ' וארא פד, ד הערה 809."],["4159","54","<b>ע\"ב גשרים</b>: ראה פרדס (שער פרטי השמות) שכ\"א, פ\"ה. מאמרי אדה\"א ויקרא ח\"א ע' כה. וש\"נ. שע\"ת לח, ג ובהערה 17."],["4160","55","<b>שחס\"ד גימט' ע\"ב</b>: נסמן לעיל פה, א הערה 816."],["4161","56","<b>דהחס\"ד ענף החכ'</b>: נסמן לעיל פד, ד הערה 813."],["4162","57","<b>כי ס\"ר לראות</b>: שמות ג, ד. ראה לקו\"ת להאריז\"ל שם. מאמרי אדה\"א שבהערה שלאח\"ז."],["4163","58","<b>נשים דעתן קלות</b>: שבת לג, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171149\" data-slug=\"likkutei-sichot\" data-id=\"1300171149\">לקו\"ש תזריע (כרך יז) ע' 149</a> הערה 14. מאמרי אדה\"א נ\"ך ע' צח. וש\"נ."],["4164","59","<b>הזכר רובו חסדים</b>: נסמן לעיל לד, ג."],["4165","60","<b>והנוק' רובה גבורה</b>: נסמן לעיל פ' שמות לד, ד."],["4166","62","<b>זכ\"ר חסדו</b>: נסמן לעיל כו, א."],["4167","61","<b>כי זכ\"ר חסדו</b>: נסמן לעיל לד, ג."],["4168","63","<b>בלילא מאי עביד</b>: ראה ע\"ז ג, ב."],["4169","64","<b>רכב אלקי\"ם רבותיי'</b>: תהלים סח, יח."],["4170","65","<b>ועברתי. . ולא מלאך</b>: נסמן לעיל נד, ב."]]],[2300540243,"[ב] <b>והנה</b> באמת יש להפלא בזה איך הי' באפשרי שישלטו ב' מדות אלה דחו\"ג ברגע א' אחר שהמה ב' הפכים בתכלית מן הקצה לקצה, ועוד זאת אשר באו בהתחלקות להיות נגוף למצרים ורפוא לישראל כנ\"ל ברגע א' כו'. אך התירוץ לזה הוא מ\"ש ויהי בחצי הלילה וה' הכה כל בכור כו' בחצי הלילה דוקא<sup data-n=\"4171\">66</sup> שאז הוא השעה שיוכל להיות ב' הפכים דחו\"ג אלה יחד ברגע א' ממש והוא מ\"ש וה' הכה כו' הוא וב\"ד שהן בחי' חו\"ג ב' הפכים כנ\"ל. וביאור הענין הנה באמת יש להבין למה הי' מכת בכורו' בחצי הלילה דוקא ולא ביום כשאר המכות וע\"י ה' בעצמו כמ\"ש ועברתי באמ\"צ כו', והענין הוא כידוע בשרש מדת יום ומדת לילה בכלל שזהו בחי' זו\"נ<sup data-n=\"4172\">67</sup> דאצי' שמדת יום הוא בחי' ז\"א שהוא בבחי' החסד כמ\"ש חסד אל כל היום<sup data-n=\"4173\">68</sup> דוקא וכמארז\"ל י\"ב שעות הוי היום<sup data-n=\"4174\">69</sup> העליון דבחי' ז\"א וג\"ש יושב כו' והן י\"ב צירופי הוי'<sup data-n=\"4175\">71</sup>, ומדת לילה הוא בחי' מל' דאצי' שהן י\"ב צירופי שם אד'<sup data-n=\"4176\">70</sup> דלילה וכמא' בלילא מאי עביד מעין יממא כו', שזהו מה שבחי' המל' שנק' מראה דמות כבוד הוי'<sup data-n=\"4177\">72</sup> דז\"א הוא כח האלקי המתפשט להחיות כל העולמות מאין ליש ומסתתרת ומתצמצמת להיות ראש ומקור להתהוות בע\"ג ולהשפיע להם טרף ומזון האלקי מראש כל דרגין עד סוף הכל כמ\"ש מלכותך מכ\"ע<sup data-n=\"4178\">73</sup> וכתיב ואתה מחיה את כולם<sup data-n=\"4179\">74</sup> כידוע דגם בחי' היכלות החיצוני' בסוף עולם העשי' מקבלים ממדת מל' דמלכות\"ו בכל משלה<sup data-n=\"4180\">75</sup> וכמ\"ש מלך אלקי' על גוים<sup data-n=\"4181\">76</sup> כו' והוא שנק' לילה להיותו בבחי' ירידת המדריג' בבחי' צמצום והסתר דשם אלקי' ואדנ\"י כו', כי מבחי' מדת יום שהוא בחי' אור דשם הוי' דאצי' לא יוכלו העולמות בע\"ג לקבל שפע חיותם כלל כו'. וזהו מ\"ש ותקם בעוד לילה<sup data-n=\"4182\">77</sup> דוקא ותתן טרף לביתה כו' טרף הוא רפ\"ח ניצוצו' ע\"ה<sup data-n=\"4183\">78</sup> שמברר שם ב\"ן בלילה דוקא ומזה יבא השפע לעולמות עד היותר תחתונים במדריגה כו', והנה ידוע מ\"ש בזוהר בפי' ליל שמורים הוא<sup data-n=\"4184\">79</sup> כו' לשון זכר כי לילה ליל ה\"א לשון נוק' זהו בחלק חצי הלילה הראשונה מתחלת הלילה עד חצות לילה שהוא בחי' הגבורה דמל' שז\"ש ותקם בעוד לילה ותתן כו', אבל ליל שמורים כו' הוא חלק חצי השני דלילה מחצות לילה עד אור הבוקר שע\"ז אמר דוד חצות לילה אקום",[["4171","66","<b>בחצי הלילה דוקא</b>: ראה זהר כאן (בא לז, ב)."],["4172","67","<b>יום. . לילה. . זו\"נ</b>: טעה\"מ — להאריז\"ל — פ' בראשית."],["4173","68","<b>חסד אל כל היום</b>: תהלים נב, ג."],["4174","69","<b>י\"ב שעות הוי היום</b>: ע\"ז ג, ב."],["4175","71","<b>י\"ב צירופי הוי'</b>: נסמן לעיל כ, ג."],["4176","70","<b>י\"ב שעות. . י\"ב צירופי הוי'. . אד'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, ב</a>) ובס' שיעורים בתניא שם ע' 547 בהערה. מכתב לר\"י פייגין נדפס ברשימות חוברת קמא. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתב."],["4177","72","<b>מראה דמות כבוד הוי'</b>: יחזקאל א, כח. ראה זהר ויקהל רטו, א ובהגהת הרח\"ו שם."],["4178","73","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["4179","74","<b>ואתה מחיה את כולם</b>: נחמי' ט, ו."],["4180","75","<b>דמלכות\"ו בכל משלה</b>: תהלים קג, יט."],["4181","76","<b>מלך אלקי' על גוים</b>: תהלים מז, ט."],["4182","77","<b>ותקם בעוד לילה</b>: משלי לא, טו."],["4183","78","<b>טרף הוא רפ\"ח. . ע\"ה</b>: נסמן לעיל פ' שמות לט, א."],["4184","79","<b>ליל שימורים הוא</b>: בא יב, מב. ראה זהר בא לח, ב. תרומה קלא, א. לך צב, ב. ביאוה\"ז פקודי נז, סע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תתקכ. לקמן קטו, ב."]]],[2300540274,"להודות לך<sup data-n=\"4185\">80</sup> שהוא בחי' עליית המל' לעלות למעלה ברינה ושיר להודות כמארז\"ל כנור הי' תלוי<sup data-n=\"4186\">81</sup> למעלה ממטתו של דוד כיון שהגיע חצות לילה הי' מנגן מאליו כו' והוא בחי' החסדי' דמל' לעלות למעלה באהבה וחדוה כו' (וז\"ש באברהם ויחלק עליהם ליל\"ה<sup data-n=\"4187\">82</sup> שנחלק ה\"א מליל שזהו בחצות הלילה בשעה שנחלק הלילה, דהיינו שנחלקו בחי' הגבו' דה\"א תתאה דמל' ונק' ליל שמורים בבחי' החסד כו', שבכח זה דחסד דמל' יהי' כלול בו בחי' הגבור' ג\"כ שהוא בחצי הלילה שנחלק הלילה בחו\"ג שבה בשעה זו דוקא נצח אברהם להמלכים וכמ\"ש ויחלק עליהם לילה ויכם והי' כדוגמא זו כאן במכת בכורו' בחצי הלילה דוקא). והנה בשעת חצות לילה אז הוא זמן שמתחברים בחי' <span data-k=\"pg\">קכה</span> ּ גבורות דו' שעות צירופי אד' הראשונים עם חסדים דמל' בו' צרופי אד' שמחצי הלילה עד הבוקר וברגע א' ממש שמתחברי' הוא שמתחלקים כי בהגיע חצי הלילה מסתלקים בחי' הגבו' ומתחילים החסדים להאיר כו'. והתחלקות זו היא דרך כלל שנחלק הלילה חצי הלילה הראשונה נסתלקת וחצי הלילה הב' מתחלת, ואמנם ברגע זו שנחלקת הלילה הרי יש כאן חיבור והתכללות דוקא מסוף הארת הגבורו' דחצי הלילה הראשונה עם התחלת החסדים דחצי הלילה הב' יחדיו המה ידובקו והיו לאחדים ברגע זאת, רק שברגע זו עצמה הן מתחלקים שהגבו' מסתלקי' והחסדים מאירים, וכמו חצות לילה אקום להודות בבחי' החסד מיד אחר כלות בחי' הגבורו' והצמצום דחצי לילה הא', שנמצא יש בהקמה זאת לעלות למעלה מירידתו בשינה להחיות רוח שפלים<sup data-n=\"4188\">83</sup> התכללות מחו\"ג וגם בחי' התחלקות כו' (וכמו דוגמת הקרן שמסתיים בו כותל זה ומתחיל בו הב' כו'). ונמצא מובן עכ\"פ שברגע זו דחצות לילה יש בה ההתכללו' מב' חצאי הלילה בכלל וגם בחי' התחלקו' דב' חצאי הלילה שזהו התחלקות חצי הא' דגבו' מחצי הב' דחסדים וכמ\"ש ויחלק וד\"ל.\n<b>ובדוגמא</b> זו יובן במ\"ש ויהי בחצי הלילה דוקא וה' הכה כו' הוא וב\"ד ב' הפכי' דחו\"ג, להיות שהי' צריך כאן שיבא המשכת הדין בפו\"מ להכות כל בכור באמ\"צ מן בכור פרעה כו' שא\"א להיות זה כ\"א מבחי' המל' שהוא בחי' דינא דמל' שנק' ב\"ד שלמעלה שנק' סופא דכ\"ד<sup data-n=\"4189\">84</sup> והוא שם אדנ\"י<sup data-n=\"4190\">85</sup> א' דין<sup data-n=\"4191\">86</sup> אדון כל הארץ<sup data-n=\"4192\">87</sup> ששופט כל הארץ בחו\"ג כו'. וכאן הי' צ\"ל בב' הפכים מחו\"ג יחד והוא לנגוף למצרים ולרפאות לישראל להציל בכורות שלהם ע\"כ הוצרך להיות דבר זה בחצי הלילה דוקא, כי בשעה ורגע זו מתכללים בחי' חו\"ג דב' חצאי הלילה כנ\"ל, שהן יב\"ש הלילה בכלל י\"ב צירופי אד' שמתכללים ביחד כמו זה עולה וזה יורד שפוגעים יחד ומתחלקים ברגע זו דוקא שאז הוא ההתחלקות בכלל לב' חצאי הלילה (כנ\"ל בפי'",[["4185","80","<b>חצות לילה. . לך</b>: תהלים קיט, סב."],["4186","81","<b>כנור הי' תלוי</b>: ראה ברכות ג, ב. מאמרי אדה\"א נ\"ך ע' יט. וש\"נ. לקמן פ' יתרו רעג, ב. תצוה שכב, סע\"א ואילך."],["4187","82","<b>ויחלק עליהם ליל\"ה</b>: לך יד, טו. ראה גם מאמרי אדה\"ז הקצרים ע' קמו. שע\"ת נא, ב. לקמן קכה, ב. תצוה שכט, ד."],["4188","83","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["4189","84","<b>דמל'. . סופא דכ\"ד</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["4190","85","<b>דמל'. . שם אדנ\"י</b>: נסמן לעיל פ' וארא עה, ב."],["4191","86","<b>א' דין</b>: בגוכי\"ק נחתך הגליון. בד: ליתא. נסמן לקמן פ' בשלח רמד, א."],["4192","87","<b>אדנ\"י. . אדון כל הארץ</b>: זהר בראשית טז, סע\"ב. שמות יג, א. יהושע ג, יא."]]],[2300540302,"ויחלק עליהם לילה כו'). ולהיות שיש בחי' התכללות דחו\"ג דב' חצאי הלילה ברגע זו דחצות לילה יחדיו ידובקו, זהו הטעם שהי' יכול להיות דבר והיפוכו כא' ממש ברגע א' הזאת לנגוף למצרים ולהציל לישראל וכמ\"ש ופסח הוי' על הפתח כו', והוא מ\"ש ויהי בחצי הלילה דוקא וה' הכה כו' הוא וב\"ד שהן בחי' חו\"ג דהוי' ואלקי'<sup data-n=\"4193\">88</sup> בהתכללות יחד ונתחלקו לחסד לישראל ולדין למצרים באותה הרגע עצמ' דוקא. אבל אם לא הי' ברגע זו דחצי הלילה ממש לא הי' באפשר שישלטו ב' הפכים כאלה יחד במעשה א', כי אם הי' בשעה שקודם חצות לילה שהן מצרופים דאד' מבחי' הגבורה הי' הדין גם לישראל, ואם הי' בשעה שאחר חצי הלילה הי' חסד גם למצרים כו', באופן שהי' או לכולם חסד או לכולם דין כמו שהי' בקי\"ס שטענה מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"4194\">89</sup> אחר שגם ישראל לא קיבלו תומ\"צ עדיין, אבל שיהי' בחי' התחלקות המדה לנגוף לזה ולהציל לזה שהוא חסד ודין בהבדלה והתחלקות מזה לזה ברגע א' זהו דוקא בחצי הלילה, לפי שאז זמן ושעה של בחי' ההתחלקות של המדה לחו\"ג שבא' מתוך בחי' <span data-k=\"pg\">252</span> ּ ההתכללות דחו\"ג יחד דוקא כנ\"ל הטעם, שמפני זה שההתחלקות בא' אחר ההתכללו' יכול להיות אז בחי' ההבדלה הפנימי' לנגוף למצרים ולרפאות לישראל ברגע זו דוקא וד\"ל.\n<b>(ועדיין</b><sup data-n=\"4195\">90</sup> אין זה מובן דבאמת זה עצמו דבר והיפוכו כא' והוא בחי' ההתכללו' עם בחי' ההתחלקות, דהתכללו' סובל דבר והיפוכו חו\"ג כא' והתחלקות נחלקו חו\"ג כאו\"א בפ\"ע דוקא, ואיך מבחי' ההתכללות דחו\"ג בחצי הלילה עצמ' יבא היפוכו שהוא ההתחלקות שהרי התחלקות זו הי' ברגע א' מכח א' באה והיינו מכח א' דהתכללות דחו\"ג דהוא וב\"ד דוקא כנ\"ל. וגם יש להבין למה הי' מכ\"ב בחצי הלילה דלילה הוא בחי' הדין דמל', והלא א' ויהרוג ה' כל בכור כו' מבחי' החסד דהוי' דוקא שהסכים עם ב\"ד דמל' כנ\"ל, והלא גם שאר המכות הי' נגוף ורפוא, למצרים נגיפה ולישראל הצלה כמ\"ש והפלה ה' כו' והוא ג\"כ בחי' התכללות דחו\"ג יחד והתחלקות אח\"כ והי' כולם ביום ולא בחצי הלילה כו'. אך שרש הענין הוא כנ\"ל בהבדל שבין מכ\"ב לשאר מכות דבשאר מכות הי' נגוף ורפוא למצרים עצמם שלא הי' הדין קשה בגמר בפו\"מ ע\"כ הי' ביום ועכ\"ז הפלה ה' בין כו' שגם בתחלת הדין הפלה ה' כו', שישראל הן בשם הוי' והמכות למצרים הי' ג\"כ שידעו כי אני הוי' כו' כנ\"ל. אבל מכ\"ב הי' בדין קשה בפו\"מ שלזה הוצרך להיות בלילה דוקא שאז הדינין דמל' שולטים, ואמנם כתיב ועברתי באמ\"צ<sup data-n=\"4196\">91</sup> בלילה הזה וכן א' ועבר הוי' לנגוף כו' דמשמע דבחי' שם הוי' עצמו עבר לנגוף ולא ע\"י שם אלקים",[["4193","88","<b>חו\"ג דהוי' ואלקי'</b>: ראה בהנסמן לעיל בהערה 7. לקמן פ' תצוה שנג, ב."],["4194","89","<b>מה נשתנו אלו מאלו</b>: לשון הגמ' שבת נה, א. ראה זהר תרומה קע, ב. יל\"ר בשלח יד, כח. לקמן פ' בשלח קסט, ג. קפד, א."],["4195","90","<b>(ועדיין</b>: בגוכי\"ק לא נרשם סיום הסוגר."],["4196","91","<b>ועברתי באמ\"צ</b>: בא יב, ב."]]],[2300540327,"וכמ\"ש אני ולא מלאך שהוא השכינה שנק' המלאך הגואל<sup data-n=\"4197\">92</sup> כו', וגם בגוף המעשה להרוג כל בכור כו' הי' מבחי' שם הוי' דחסד בעצמו כמ\"ש ויהרוג הוי' כו' וכמ\"ש בזוהר קוב\"ה קטיל כו' כגוונא כו' כנ\"ל, הענין הוא דשם הוי' דז\"א הוא בחי' ת\"ת<sup data-n=\"4198\">93</sup> שהוא בחי' הדעת<sup data-n=\"4199\">94</sup> כידוע שכולל חו\"ג<sup data-n=\"4200\">95</sup> כא' ממש להיותו בבחי' אין דכתר<sup data-n=\"4201\">96</sup> שסובל ב' הפכים דחסד ודין כמו דעת נוטה<sup data-n=\"4202\">97</sup> לחו\"ג יחד, וכך מדת הת\"ת שכלול מחו\"ג<sup data-n=\"4203\">98</sup> יחד כאש ומים שכלולים ברוח<sup data-n=\"4204\">99</sup> וכדעת המכריע<sup data-n=\"4205\">100</sup> שיסבול ב' דיעות הפכים כידוע. וידוע דבשם הוי' דבחי' ת\"ת החסדים גוברים<sup data-n=\"4206\">101</sup> על בחי' דין שבו שנק' גבורות ממותקות שתחילתו קשה וסופו רך וז\"ש נגוף ורפוא בשאר מכות שהרפואה הוא בבחי' ת\"ת<sup data-n=\"4207\">102</sup> להמתיק הדין בסופו שזה הי' להראות לפרעה שידעו המתקות הדינין דאלקי' בהוי' כמ\"ש יתרו כו' כנ\"ל, אבל במכת בכורות הרי נתלבש וירד שם הוי' במל' דוקא לגמור הדין בפו\"מ והיינו בחצי הלילה דוקא שכלול מחו\"ג יחד כנ\"ל, ואע\"פ שגבו' שבמל' באים לפו\"מ כאן א' ויהרוג הוי' כל בכור כו' וכמ\"ש וה' הכה כו' הוא וב\"ד יחדיו ששם הוי' עצמו עבר לנגוף, לפי שזה הי' הגמר לאיבוד שרש ומקור דק\"נ שהוא בחי' החכ' דבכור שנק' ראשית ולהציל לישראל שיהי' בכור שלהם בבחי' קדש העליון ראשית תבואתו<sup data-n=\"4208\">103</sup> וכמ\"ש בני בכורי ישראל<sup data-n=\"4209\">104</sup>, הוצרך להיות הבדלה פנימי' זו להבדיל בין קדש לחול ע\"י בחי' החכ' דשם הוי' עצמו באופן שבשעה ורגע א' דחצי הלילה הי' נגוף למצרים ורפוא לישראל והכל משם הוי' עצמו שנתלבש בחו\"ג דחצי הלילה שזהו הוא וב\"ד יחד כנ\"ל. וזהו כמשל סם הרפואה שמחי' לזה ויזיק וימית לזה כך הי' אופן שפע והמשכה א' שיהי' נגוף למצרים והיא עצמה רפוא לישראל, כמו סם חיים דתורה למימינים בה ולמשמאילים<sup data-n=\"4210\">105</sup> בה סמא דמותא כו'. וזהו מצד שנמשך מבחי' ההתכללות, דחו\"ג דת\"ת דהוי' הוא שבא <span data-k=\"pg\">קכו</span> ּ לבחי' התחלקות להיות דין קשה בפו\"מ למצרים והוא עצמו הי' הצלה לישראל וע\"כ הי' בחצי הלילה דוקא וד\"ל<sup data-n=\"4211\">106</sup>.",[["4197","92","<b>השכינה שנק' המלאך הגואל</b>: ויחי מח, טז. ראה זהר ויחי רל, א. משפטים קטז, ב. [ביאיר נתיב למאו\"א מערכת מלאך סס\"א מוסיף: ”וע' בר\"מ פ' ויחי דף רכ\"ט ע\"א\" והוא הנדפס בזהר משפטים הנ\"ל]. ביאוה\"ז בלק קמו, ג ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרצב ואילך."],["4198","93","<b>דשם הוי'. . ת\"ת</b>: נסמן לעיל פ' וארא סו, ב."],["4199","94","<b>ת\"ת שהוא בחי' הדעת</b>: ראה גם לעיל פ' וארא פה, ד הערות 862-63. וש\"נ."],["4200","95","<b>הדעת. . שכולל חו\"ג</b>: נסמן לעיל נז, ד."],["4201","96","<b>הדעת. . אין דכתר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380512\" data-slug=\"likkutei-torah\" data-id=\"4001380512\">לקו\"ת שלח נ, א</a>. סידור שער הלולב רסה, א."],["4202","97","<b>דעת נוטה</b>: נסמן לעיל פ' שמות מב, א."],["4203","98","<b>הת\"ת שכלול מחו\"ג</b>: ראה זהר (רע\"מ) צו כח, סע\"א. ע\"ח (שער פרטי עי\"מ) שכ\"ז, פ\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670120\" data-slug=\"torat-chaim\" data-id=\"2300670120\">תו\"ח בראשית ח, ג</a> הערה 52."],["4204","99","<b>כאש ומים שכלולים ברוח</b>: נסמן לעיל פ' שמות כח, א."],["4205","100","<b>וכדעת המכריע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670163\" data-slug=\"torat-chaim\" data-id=\"2300670163\">תו\"ח וירא קי, ד</a> ואילך."],["4206","101","<b>ת\"ת החסדים גוברים</b>: ראה אגה\"ק סי\"ב. הנסמן במאמרי אדה\"א בראשית ע' רפו."],["4207","102","<b>שהרפואה הוא בבחי' ת\"ת</b>: ראה פע\"ח (שער העמידה) ש\"ט, פי\"ט בברכת רפאינו. סידור האריז\"ל שם. ביאוה\"ז במדבר פו, ג."],["4208","103","<b>ראשית תבואתו</b>: ירמי' ב, ג."],["4209","104","<b>בני בכורי ישראל</b>: שמות ד, כב."],["4210","105","<b>למימינים בה ולמשמאילים</b>: נסמן לעיל פ' שמות ג, ד."],["4211","106","<b>וע\"כ. . דוקא וד\"ל</b>: ב: וד\"ל וע\"כ. . דוקא. ובגוכי\"ק נחתך הגליון."]]],[2300540350,"[ג] <b>והנה</b> עדיין י\"ל שרש הדברים איך יתחלק הלילה שהוא בחי' המל' כנ\"ל להיות סובל ב' הפכים ברגע א' [ממש] נגוף למצרים ורפוא לישראל בהעברה א' [ו]ברגע א' ממש שעבר הוי' בחצי הלילה ופסח [ה'] על בתי בנ\"י כו', שאם בחי' לילה הוא בחי' מל' הלא עד\"מ בדוגמא<sup data-n=\"4212\">107</sup> דמל' למטה אין ב' המדות הללו דחסד ודין שולטין כא' כנ\"ל. אך יש להקדים תחלה בשרש ענין יצ\"מ דכתיב ויוציאנו [הוי'] ממצרים<sup data-n=\"4213\">108</sup> ביד חזקה ובזרוע נטוי' שזהו בחי' או\"א דאצי' שנק' הוי' אלקינו<sup data-n=\"4214\">109</sup> ביד חזקה ובזרוע נטוי' הן ב' זרועות דא\"א, דאו\"א מלבישים לזרועות דא\"א<sup data-n=\"4215\">110</sup>, שאור אבא מלביש לחסד דא\"א ואור אימא מלביש לגבורה דא\"א וכמ\"ש אני בינה לי גבורה<sup data-n=\"4216\">111</sup> דא\"א כו' (והן שרש התחלקות דקו ימין חח\"ן וקו שמאל בג\"ה<sup data-n=\"4217\">112</sup> כידוע), וגם ידוע דשרשי המשכות המוחין לאו\"א הוא בא מבחי' [ב'] מזלות דא\"א דאור אבא יונק ממזל הח'<sup data-n=\"4218\">113</sup> ונוצר ואור אימא ממזל הי\"ג ונקה שנמשכים מבחי' ח\"ס דא\"א שלמעלה מבחי' זרועות דא\"א (וז\"ש ואנכי תרגלתי לאפרים קחם על זרועותיו<sup data-n=\"4219\">114</sup> למעלה מזרועות דא\"א). ומבואר במ\"א ביאור ענין ההפרש<sup data-n=\"4220\">115</sup> הזה בין הלבשת או\"א לזרועות דא\"א שהוא רק הלבשת השכל והטעם למדות שברצון שמצד הרצון מתלבשת בשכל וטעם לרצון כמו השוחד כו' ובין בחי' יניקת שרש התהוות השכל והחכ' מאין דכתר שנק' ח\"ס ע\"י בחי' המזלות כמו מזל מחכים<sup data-n=\"4221\">116</sup> כו' [ו]כמש\"[א] הכל תלוי במזל<sup data-n=\"4222\">117</sup> אפי' ס\"ת בהיכל שהוא יחוד פנימי דאו\"א כו', וגם בא\"א עצמו בא שם בחי' הארת המדות דחו\"ג דע\"י דחסד דע\"י מלובש בגלגלתא דא\"א וגבורה דע\"י מלובש בח\"ס<sup data-n=\"4223\">118</sup> דא\"א, ועד\"ז גם בע\"י עצמו נחלק לבחי' חו\"ג שהוא<sup data-n=\"4224\">119</sup> מ\"ה וב\"ן דע\"י<sup data-n=\"4225\">120</sup> ואע\"ג דלית שמאלא בהאי ע\"י<sup data-n=\"4226\">121</sup> כו', וכן עד רום המעלות עד בחי' חו\"ג שבעצמות<sup data-n=\"4227\">122</sup> המאציל ממש. וידוע דבחי' חו\"ג דאו\"א נמשכים להיות שרש הבנין דזו\"נ שמתחלק גם בהם לחו\"ג ע\"י הדעת כו', כידוע דנה\"י דאו\"א<sup data-n=\"4228\">123</sup> נמשכים<sup data-n=\"4229\">124</sup> מוחין לזו\"נ ומבחי' החסד דמ\"ה דאבא [נמשך] בז[\"א] דב\"ן מסט' דאבא<sup data-n=\"4230\">125</sup> קאתי יותר",[["4212","107","<b>בדוגמא</b>: בד: בדינא."],["4213","108","<b>ויוציאנו [הוי'] ממצרים</b>: ואתחנן ו, כא [בהוספת התיבות: ובזרוע נטוי' — ראה הגש\"פ עם לקוטי טעמים ומנהגים ע' יד]."],["4214","109","<b>או\"א דאצי' שנק' הוי' אלקינו</b>: פע\"ח (שחה\"מ) שכ\"א, פ\"ז בביאור פיסקא עבדים היינו. מ\"ח מסכת סדר ליל פסח פ\"ז, מ\"ב. סידור האריז\"ל שם. [תיבת אלקינו — מובא בהגדה. ראה גם לעיל בהערה שלפנ\"ז]."],["4215","110","<b>דאו\"א מלבישים לזרועות דא\"א</b>: ראה בהערה שלפנ\"ז. הנסמן במאמרי אדה\"א קונטרסים ע' ריד."],["4216","111","<b>אני בינה לי גבורה</b>: משלי יח, יד. ראה ע\"ח (שער או\"א) שי\"ד, פ\"ב. ביאוה\"ז נשא פח, ג. שעה\"י קכז, ב. לקמן קל, ד."],["4217","112","<b>דקו ימין חח\"ן וקו שמאל בג\"ה</b>: נסמן לעיל פ' וארא פד, ד הערה 803."],["4218","113","<b>דאור אבא יונק ממזל הח'</b>: נסמן לעיל פ' שמות לו, א."],["4219","114","<b>ואנכי. . זרועותיו</b>: הושע יא, ג. בד: אנכי. . זרעותי — ראה לקמן צ, ד. צה, א. ד. קל, ב. פ' בשלח ר, ד. רא, א. רד, ג. תצוה שמא, ב [ושם נדפס מגוכתי\"ק). תכג, ג. תכה, ג. מאמרי אדה\"ז תקע\"א ע' רנז. הנסמן במאמרי אדה\"א בראשית ע' שצו. שמות ח\"ב ע' תקלג."],["4220","115","<b>ההפרש. . הלבשת או\"א. . יניקת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380242\" data-slug=\"likkutei-torah\" data-id=\"4001380242\">לקו\"ת אמור לט, א</a>. מאמרי אדה\"ז תקס\"ח ח\"א ע' רסג. פרשיות התורה ח\"א ע' קכז ואילך. ח\"ב ע' תקסח. ביאוה\"ז נשא פט, ב. שעה\"י קכז, א ואילך. לקמן קלא, א. פ' בשלח ר, ד."],["4221","116","<b>מזל מחכים</b>: שבת קנו, א. וראה לקמן קלב, ד."],["4222","117","<b>הכל תלוי במזל</b>: נסמן לעיל פ' שמות יא, א."],["4223","118","<b>דחסד דע\"י מלובש בגלגלתא. . בח\"ס</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ו-ז. לקמן פ' בשלח רד, ד."],["4224","119","<b>שהוא</b>: בד: שהן."],["4225","120","<b>מ\"ה וב\"ן דע\"י</b>: ראה ע\"ח (שער עתיק) שי\"ב, פ\"א. פ\"ב."],["4226","121","<b>דלית שמאלא בהאי עתיקא</b>: ראה זהר (אד\"ר) נשא קכט, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["4227","122","<b>חו\"ג שבעצמות</b>: ראה גם לקמן צ, ב. פ' בשלח קנה, א. קצו, ד. שע\"ת פז, א ובהערה 5. ש\"א פד, א."],["4228","123","<b>דנה\"י דאו\"א. . לזו\"נ</b>: ראה שעה\"י קכח, א ובהערה 11."],["4229","124","<b>נמשכים</b>: בד: נעשי'."],["4230","125","<b>דב\"ן מסט' דאבא</b>: נסמן לעיל פ' שמות לד, ג."]]],[2300540373,"כמ\"ש כי זכר חסדו וע\"כ רובו חסדים ומיעוטו גבו' מבחי' גבו' דאימא שבקו השמאל בג\"ה כו', ובבחי' בנין המל' כתי' [ג\"כ] ויבן ה' אלקי' את הצלע דאו\"א תקינו לה<sup data-n=\"4231\">126</sup> כו' שהן או\"א שבז\"א כלול ג\"כ מחו\"ג דאימא<sup data-n=\"4232\">127</sup> רק שהמל' רובה גבור[ו']<sup data-n=\"4233\">128</sup> מסט' דאימא יותר דכאמה בתה<sup data-n=\"4234\">129</sup>. ועכ\"פ מובן [מכל זה] דבחי' חו\"ג דזו\"נ נמשך מאו\"א ואו\"א נמשך מא\"א [וע\"י] עד בחי' חו\"ג שבעצמו' ממש וז\"ש ויוציאנו הוי' אלקינו כו' (וזהו וה' כו'<sup data-n=\"4235\">130</sup> בכור שהוא בחי' חו\"ג דזו\"נ שנק' הוא וב\"ד כנ\"ל).\n<b>והנה</b> להבין ביאור ענין המדות דא\"א וע\"י שזהו בחי' יד חזקה וזרוע נטויה וכמו בקי\"ס דכתי' וירא ישראל<sup data-n=\"4236\">131</sup> את היד הגדולה כו', הנה תחלה י\"ל בבחי' אור הכתר בכלל כידוע בע\"ח שנק' ממוצע<sup data-n=\"4237\">132</sup> בין עצמות המאציל לנאצלים כו', כי אין ערוך כלל בין האורות הנאצלים לגבי עצמות המאציל כמו שאין ערוך לנברא לגבי הבורא, מאחר שהאצי' אינו אלא אור וזיו בעלמא כמו חלק קטן הנבדל מגדול כמו ויאצל [מן הרוח]<sup data-n=\"4238\">133</sup> כו' כמ\"ש במ\"א וכמ\"ש בס\"י שהע\"ס הן כשלהבת הקשורה בגחלת<sup data-n=\"4239\">134</sup> כו' וצריך להיות בחי' אמצעי שיבאו מן העלם לגילוי, דמצד עצמו' המאציל נק' ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"4240\">135</sup> כלל כמ\"ש ולאו מכל אינון מדות כלל<sup data-n=\"4241\">136</sup>, ואותו הממוצע שע\"י יומשך האור ושפע מן המאציל לנאצלים<sup data-n=\"4242\">137</sup> כו' זהו בחי' אור הכתר (שאינו נמנה<sup data-n=\"4243\">138</sup> עם <span data-k=\"pg\">254</span> ּ הי\"ס כאשר הדעת נמנה שהן חב\"ד חג\"ת נהי\"מ). ובהכרח לומר שיש בממוצע זה מבחי' המאציל עצמו רק שהוא מבחי' האחרונה שבו וזהו בחי' הפנימי' שבכתר ונק' ג\"ר שבו בכלל שנחשב מסוף עולם הא\"ס שהוא עצמי' המאציל שלמעלה מע\"ס דאצי' כמ\"ש אנת הוא חד<sup data-n=\"4244\">139</sup> ולא בחושבן י\"ס [כו' כנ\"ל], וגם יש בבחי' הממוצע הזה שהוא הכתר מבחי' הנאצלים אך שהוא בחי' מקור ושרש להם והוא בחי' חיצוני' שבו לבד והן ז\"ת שבו בכלל שמלובשים באו\"א כנ\"ל. והענין הוא כידוע דגם אור הכתר כלול מע\"ס<sup data-n=\"4245\">140</sup> ובחי' המדות שבו עם המוחין הנמשך להם נק' בחי' חיצוני' שלו<sup data-n=\"4246\">141</sup> לבד, כמו שאנו רואים בנפש האדם שכלול מנר\"נ ח\"י<sup data-n=\"4247\">142</sup>, בחי' נר\"ן הן המוחין דחב\"ד ומדות חג\"ת נה\"י מלובשים ומוגבלים בכלים אבל הרצון הוא אור בלתי מוגבל בכלי<sup data-n=\"4248\">143</sup> כלל",[["4231","126","<b>ויבן. . דאו\"א תקינו לה</b>: בראשית ב, כב. ראה זהר בראשית מח, ב. מט, א."],["4232","127","<b>דאימא</b>: בד: דאו\"א."],["4233","128","<b>שהמל' רובה גבור[ו']</b>: ראה גם לעיל פ' שמות לד, ד. וש\"נ."],["4234","129","<b>דכאמה בתה</b>: יחזקאל טז, מד."],["4235","130","<b>כו'</b>: בד: הכה."],["4236","131","<b>וירא ישראל</b>: בשלח יד, לא."],["4237","132","<b>הכתר. . ממוצע</b>: נסמן לעיל פ' שמות יא, ג."],["4238","133","<b>ויאצל [מן הרוח]</b>: בהעלותך יא, כה. ראה מאמרי אדה\"א דברים ח\"ג ע' תתפד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670031\" data-slug=\"torat-chaim\" data-id=\"2300670031\">תו\"ח לך פ, א</a> ובהערה 25."],["4239","134","<b>כשלהבת הקשורה בגחלת</b>: נסמן לעיל פ' שמות כח, ד."],["4240","135","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["4241","136","<b>ולאו מכל אינון מדות כלל</b>: ת\"ז בהקדמה (יז, ב)."],["4242","137","<b>לנאצלים</b>: בד: להאציל."],["4243","138","<b>הכתר (שאינו נמנה</b>: ראה ע\"ח (שער מוחין דצלם) שכ\"ג, פ\"ה. פ\"ח. (שער דרושי אבי\"ע) שמ\"ב, פ\"א. שער ההקדמות דרוש בענין הכתר (רנב, א). הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרטו. לקמן צא, ד. פ' ויקהל שפו, ד. תלח, ג."],["4244","139","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["4245","140","<b>הכתר כלול מע\"ס</b>: ראה טעמי המצות להרח\"ו ר\"פ תשא. ביאוה\"ז שמות לו, ד. סידור שער בהמ\"ז קה, ב. מאמרי אדה\"ז תקס\"ו ע' קפד. מארז\"ל ע' כב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380281\" data-slug=\"likkutei-torah\" data-id=\"4001380281\">לקו\"ת בחקותי מז, ד</a>. שעה\"י קכה, א. לקמן פ' תצוה שס, א."],["4246","141","<b>שלו</b>: בד: שבו."],["4247","142","<b>מנר\"נ ח\"י</b>: ראה ב\"ר פי\"ד, ט. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."],["4248","143","<b>רצון. . בכלי</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרעט. דרמ\"צ פה, ב. וראה שע\"ת קיז, ג."]]],[2300540394,"וכלל ונק' בחי' מקיף [כמו] כצנה רצון תעטרנו<sup data-n=\"4249\">144</sup> כו', ולהיותו נבדל בערך גם מן השכל והחכ' שבמוח, כי הרי אין טעם לרצון כלל<sup data-n=\"4250\">145</sup> אפי' טעם כמוס כידוע, ע\"כ נק' ממוצע להביא ולהמשיך מעצמו' הנפש להאיר מן ההעלם לגילוי כל הי' כחות דחב\"ד [ו]חג\"ת כו', כמו שיאיר אור השכל מן ההעלם לגילוי זהו ע\"י הרצון שהוא בחי' המשכות והטי' הנפש בכלל (כמו חכם לכשירצה<sup data-n=\"4251\">146</sup> דוקא וכן ענין חכם לב<sup data-n=\"4252\">147</sup> כמ\"ש במ\"א). וכך יובן למעלה בכל הספי' ומדות דאצי' משתלשלים ע\"י אור הכתר דוקא שנק' אמצעי בין עצמות המאציל לנאצלים, אך מה שע\"י<sup data-n=\"4253\">148</sup> נמשך האור מן המאציל זהו בחי' חיצוני' שבו לבד כנ\"ל והיינו בחי' ז\"ת שבו שהן המדות חג\"ת כו'. והענין הוא כמו אה\"ר שברצון שלמעלה מן השכל וטעם הגלוי שעי\"ז יבא ויתלבש בשכל וטעם גלוי כמו השוחד כו', שזהו למעלה בחי' [חסד] דא\"א שמלובש באור אבא כו' כנ\"ל וכמו וימינו תחבקני<sup data-n=\"4254\">149</sup> ימין העליון דרצה\"ע וכמו וימינך פשוטה לקבל שבים<sup data-n=\"4255\">150</sup> למעלה מן החכ', וכן בחי' הגבורה שהוא מדה\"ד שברצון שמלובש באימא כמ\"ש אני בינה לי גבורה דא\"א כנ\"ל שזהו שרש ומקור לנאצלים שמקבלים רק מחג\"ת דא\"א לבד (ואע\"פ שמבואר בע\"ח דרק בחי' נה\"י דא\"א נעשו בחי' מוחין לאו\"א<sup data-n=\"4256\">151</sup>, אך זהו בדרך השתלשלו' דעו\"ע אמנם [ב]בחי' [ה]התלבשות או\"א מלבישים לזרועות דא\"א כנ\"ל). [ו]גם מ\"ש דשרש יניקת או\"א מב' מזלות דא\"א ונוצר ונקה היינו ג\"כ רק מבחי' חיצוני' דח\"ס שצומח ממנו [ב]בחי' שערות שנק' ת\"ד הוא [ש]נעשה בחי' שרש ומקור להתהוות החו\"ב כמ\"ש ד[אור] אבא יונק ממזל הח' וכמו שצומח כח עצם השכל מלמעלה מן השכל שנק' כח המשכיל בגידול וריבוי הימים ושנים עד שנק' זקן שקנה חכ'<sup data-n=\"4257\">152</sup> כו' כמ\"ש במ\"א<sup data-n=\"4258\">153</sup> כי ימים ידברו<sup data-n=\"4259\">154</sup> כו', אבל פנימי' ח\"ס הוא עצם כח המשכיל ההיולי שלמעלה מהיות גם מקור לגילוי שכל, וגם למעלה מהיות מקור לתולדות המדות שברצון שנק' טעם כמוס לרצון, דטעם כמוס לרצון הוא המביא לרצון להתחלקות לב' קוין דחו\"ג<sup data-n=\"4260\">155</sup> ונק' טעם לרצון עכ\"פ כמו ענין שתוק כך עלה במח' לפני<sup data-n=\"4261\">156</sup> כו' כידוע ומבואר במ\"א, וכ\"ז הוא הנק' בחי' ז\"ת דא\"א שהן מלובשי' בנאצלים להיות להם מקור בבחי' התחלקות הקוין (ושרשם",[["4249","144","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג."],["4250","145","<b>אין טעם לרצון כלל</b>: ראה של\"ה בית ה' (ד, ב בהגה) בשם ר' יוסף אלקשטיליא. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. שה\"א קב, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670292\" data-slug=\"torat-chaim\" data-id=\"2300670292\">תו\"ח נח סג, א</a>."],["4251","146","<b>חכם לכשירצה</b>: גיטין סז, א. ראה מאמרי אדה\"א בראשית ע' יט. שמות ח\"ב ע' שפו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680302\" data-slug=\"torat-chaim\" data-id=\"2300680302\">תו\"ח וישב רט, ב</a>."],["4252","147","<b>חכם לב</b>: תשא לא, ו. ראה מאמרי אדה\"א נ\"ך ע' תקכח ואילך."],["4253","148","<b>שע\"י</b>: ב: שעל ידו."],["4254","149","<b>וימינו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["4255","150","<b>וימינך פשוטה לקבל שבים</b>: תפלת נעילה."],["4256","151","<b>נה\"י דא\"א. . מוחין לאו\"א</b>: ראה ע\"ח (שער דרושי נקודות) ש\"ח, פ\"ב."],["4257","152","<b>זקן שקנה חכ'</b>: נסמן לעיל פ' שמות לא, ד."],["4258","153","<b>במ\"א</b>: בד: ליתא."],["4259","154","<b>כי ימים ידברו</b>: איוב לב, ז [בהוספת תיבת כי]."],["4260","155","<b>טעם כמוס. . דחו\"ג</b>: ראה גם שעה\"י קכה, א. לקמן קל, ד ואילך."],["4261","156","<b>שתוק כך עלה במח' לפני</b>: מנחות כט, ב. ראה סידור דרושים לחתונה קל, סע\"ג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תתטז. וש\"נ. לקמן קל, ג. פ' בשלח ר, ג."]]],[2300540414,"מבחי' חיצוני' דח\"ס דא\"א כנ\"ל וכמ\"ש בפרד\"ס<sup data-n=\"4262\">157</sup> בשער הצ[י]נורות, וזהו ענין אלקי אברהם כו' הגדול הגבור כו' ה' דהגדול<sup data-n=\"4263\">159</sup> ח\"ס דא\"א כו'). ועד\"ז למעלה יותר בבחי' ז\"ת דע\"י שמלובש בא\"א<sup data-n=\"4264\">160</sup> שנק' ימי קדם<sup data-n=\"4265\">161</sup> [כו'] (ובכלל נק' ע\"י פנימי' הכתר וא\"א חיצוני' הכתר דחיצוני' התענוג במדות חו\"ג שבתענוג כמו <span data-k=\"pg\">קכז</span> ּ אה\"ר בתענוגי' כו' הוא שנעשה מקור לרצון שנק' גלגלתא<sup data-n=\"4266\">162</sup> דא\"א וגבורה דע\"י בח\"ס דא\"א כו', וכן עד\"ז למעלה יותר<sup data-n=\"4267\">163</sup> מז\"ת דא\"ק בע\"י<sup data-n=\"4268\">164</sup> וכך עד בחי' חו\"ג שבעצמות א\"ס ממש כנ\"ל<sup data-n=\"4269\">165</sup>. אבל הנה בחי' ג\"ר דא\"א (שהוא בבחי' כתר שבכתר בכלל) הוא בלתי מלובש בנאצלים כלל והוא שנק' פנימי' הכתר בכלל ששם מאיר מבחי' אור עצמות המאציל ממש דלאו מכל אינון מדות כלל כנ\"ל, והיינו בחי' עצם נקודת הרצון הפשוט שלמעלה גם מטעם הכמוס לרצון שבלתי מתחלק לב' קוין כלל ונק' רעדכ\"ר<sup data-n=\"4270\">166</sup> כו'. וכן בחי' ג\"ר דע\"י והוא בחי' עצם אור התענוג הפשוט שלמעלה מהתחלקות במדות שבו שנק' ז\"ת כו' דעז\"א בדרך כלל בתיקוני' אוא\"ס מלגאו<sup data-n=\"4271\">167</sup> כתרא עילאה מלבר כו' שזהו בחי' פנימי' הכתר בכלל שבו מאיר מעצמו' אוא\"ס ממש שלמעלה מע\"ס דאצי' כנ\"ל וד\"ל (וזהו המלך המרומם לבדו<sup data-n=\"4272\">168</sup> בחי' מל' דא\"ס קודם הצמצום דקו\"ח שהוא מתנשא מימות עולם דנאצלים כו' כידוע).\n[ד] <b>והנה</b> מכ\"ז יובן עכ\"פ שבחי' מקור הראשון יותר להיות מציאות דחו\"ג בזו\"נ שנמשך להם ממוחי' ומדות דאו\"א כנ\"ל הוא מז\"ת דע\"י וא\"א שהוא מקור לנאצלים שזהו ענין זרועות דא\"א, וגם המוחי' דא\"א<sup data-n=\"4273\">169</sup> דח\"ס שנק' טעם כמוס לרצון שמאיר במדות דחג\"ת דא\"א נחשב בכלל חיצוני' הכתר בכלל כנ\"ל. אבל בחי' כח\"ב דא\"א וע\"י שלמעלה מטעם כמוס לרצון כלל זהו למעלה ממקור וסדר ההשתלשלות דע\"ס דאצי' לגמרי אחר שאין בחי' המוחין דאו\"א מגיעים לשם כלל, כי גם בשרשן בח\"ס דא\"א בב' מזלות [ה]נ\"ל אין זה רק חיצוני' בחי' הצומח שבו לבד, וגם הוא למעלה מטעם ומוחין דח\"ס שבמדות דא\"א כנ\"ל שאין או\"א מלבישים שם כלל. וא\"כ הרי מובן מזה שאין בחי' התחלקות דחו\"ג שבזו\"נ שנק' הוא וב\"ד כנ\"ל מגיע רק בבחי' שרש הראשון דחו\"ב דאצי' שהן המוחין ומדות דא\"א",[["4262","157","<b>בפרד\"ס</b>: כ\"ה בכ\"מ בהנחות ודרושי כ\"ק אדה\"א. וראה גם לקמן פ' בשלח קמא, ג ואילך. רד, ד. רכ, ג. תצוה שנב, א. שסא, ב. ויקהל שפט, ב."],["4263","159","<b>אלקי אברהם. . ה' דהגדול</b>: תפלת שמו\"ע. ראה אמ\"ב שער הק\"ש פס\"ג."],["4264","160","<b>ז\"ת דע\"י שמלובש בא\"א</b>: ראה ע\"ח (שער המלכים) שי\"א, פ\"ד. פ\"ח. (שער א\"א) שי\"ג, פ\"א."],["4265","161","<b>ז\"ת דע\"י. . ימי קדם</b>: ראה גם מאמרי אדה\"א בראשית ע' רמא. לקמן צ, ג."],["4266","162","<b>לרצון שנק' גלגלתא</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380505\" data-slug=\"likkutei-torah\" data-id=\"4001380505\">לקו\"ת שלח מח, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380936\" data-slug=\"likkutei-torah\" data-id=\"4001380936\">ר\"ה נד, ב</a>."],["4267","163","<b>למעלה יותר</b>: בד: ליתא."],["4268","164","<b>מז\"ת דא\"ק בע\"י</b>: ראה סידור שער המילה קמ, ד: ”א\"ק. . התלבשות שלו בע\"י. . רק מבחי' נה\"י שבו בלבד ולא כל ז\"ת שלו מתלבשים\". <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380165\" data-slug=\"likkutei-torah\" data-id=\"4001380165\">לקו\"ת תזריע כא, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380706\" data-slug=\"likkutei-torah\" data-id=\"4001380706\">דרמ\"צ יא, א</a>. וראה גם לקו\"ת מסעי צה, סע\"ג ואילך: ”מג\"ר דא\"ק. . רק מז\"ת. . שמקור ההמשכה וכל ההשתלשלות הוא מז\"ת דא\"ק\"."],["4269","165","<b>כנ\"ל</b>: ב: וד\"ל). ד: כו' וד\"ל)."],["4270","166","<b>רעדכ\"ר</b>: נסמן לעיל פ' שמות ה, ג."],["4271","167","<b>בתיקוני' אוא\"ס מלגאו</b>: ראה ת\"ז סתכ\"ב (סח, ב). הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670236\" data-slug=\"torat-chaim\" data-id=\"2300670236\">תו\"ח לך פג, ב</a> הערה 17."],["4272","168","<b>המלך המרומם לבדו</b>: ברכת יוצר. ראה גם לקמן פ' בשלח קסא, סע\"ג ואילך. קסח, ד. קעח, ג. רכו, ד. תצוה שלא, ד. ויקהל תטז, ב. שעה\"י קיח, ב. שה\"א עו, א ואילך."],["4273","169","<b>דא\"א</b>: בד: ליתא."]]],[2300540434,"וע\"י שהן שרשי התחלקות הקוין דאצי' אבל לא למעלה מהם כלל שהוא בחי' ג\"ר שלהם שהוא בחי' עצמות הרצון והתענוג שבלתי יוכל לבא כלל גם בהתלבשו' בחו\"ב ולא במדות ומוחי' דח\"ס דא\"א כי נבדל מהם בערך לגמרי כנ\"ל וד\"ל (וכמבואר בפרד\"ס בשער הצנורות<sup data-n=\"4274\">158</sup> ומצ[ו]ייר באילן<sup data-n=\"4275\">170</sup> ד' בחי' חיצוני' דח\"ס נחלקו לג' קוין<sup data-n=\"4276\">171</sup> דאצי' אבל למעלה מזה אין שם בחי' התחלקות הקוין כלל וכלל). ומובן מזה דבבחי' ג\"ר דא\"א וע\"י שנחשב מבחי' האחרונה שבעצמו' א\"ס ב\"ה ממש אין שם עדיין מקור להתחלקות חו\"ג כלל אלא שם הוא בבחי' התכללו' דחו\"ג למעלה מבחי' התחלקות כאו\"א בפ\"ע (דא\"א לומר שאין שם בחי' חו\"ג כלל שהרי שרש דחו\"ג ישנם גם בעצמו' המאציל, וענין חו\"ג בעצמו' א\"ס<sup data-n=\"4277\">*172</sup> ידוע שזהו מ\"ש דאוא\"ס למעלה [מעלה]<sup data-n=\"4278\">172</sup> עד אין קץ כו' בעא\"ע<sup data-n=\"4279\">173</sup> כו' שזהו בחי' הגבו' שהוא ההעלם שבעצמו' שנק' סדכ\"ס<sup data-n=\"4280\">174</sup> כו', ובחי' החסד שבעצמו' היינו מה שאוא\"ס נמשך ומתפשט למטה מטה עד אין תכלית כו' להיות מקור למקור לע\"ס דאבי\"ע עד סוף העשי' וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4281\">175</sup> כו'. אמנם ב' מדות דחו\"ג שבעצמו' המאציל כלולים בהתכללו' [כא'] ממש [מבלי ניכר בהם שום התחלקו' כלל וכלל (וכמו שבעצם הרצון והתענוג הפשוט יש שם ג\"כ בחי' חו\"ג אך שהן בחי' עצמיו' הנפש ממש], כמו האה\"ר העצמי' שבעצמו' הרצון למעלה [גם] מטעם כמוס כו' דאב לבנו או לאוהבו<sup data-n=\"4282\">176</sup> כנפשו ממש ולהיפך תכלית השנא[ה] בעצם הנפש לשונאו בעצם שלמעלה מהטעם לגמרי כו' (וכמו אהבת עצמו לחיות <span data-k=\"pg\">256</span> ּ ולא למות שכלולים כא' ממש), וכן אהבת נפש דבן לאב בבחי' עצמי' הרצון והתענוג שכלולים בזה ב' קוין ימין ושמאל כמו למס\"נ על קדה\"ש שע\"י בחי' האמונה הפשוטה העצמי' כמשי\"ת).\n<b>והנה</b> לפי כל הנ\"ל עם היות סיבת התעוררות הרצה\"ע למעלה בי[צ]\"מ [מ]בחי' חיצוני' הכתר שהן בחי' המדות חו\"ג דא\"א שנמשך ע\"י טעם לרצון עכ\"פ שנק' טעם כמוס ומשם נמשך ע\"י המדות דרצון לאו\"א שהן<sup data-n=\"4283\">177</sup> בחי' השכל וטעם גלוי שבמדות דז\"א לבחי' המל' בבחי' התחלקות חו\"ג ממש אז לא הי' הצלה לישראל בבחי' החסד ודין למצרים ע\"פ משפט החכ'",[["4274","158","<b>בפרד\"ס בשער הצ[י]נורות</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450678\" data-slug=\"or-hatorah-hb\" data-id=\"8316450678\">אוה\"ת כאן (ע' ב'תרלו</a>) מציין לפ\"ב. וראה גם לקמן פ' בשלח רד, ד. מאמרי אדה\"ז תקס\"ז ע' כו. שעה\"י קכד, ב. אמ\"ב שער התפילין קטז, ג. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ."],["4275","170","<b>ומצ[ו]ייר באילן</b>: ראה גם מאמרי אדה\"ז תקס\"ז כאן [בוך 66 ע' צו — ראה לעיל הערה 1]. הובא באוה\"ת בא כאן ע' ב'תרלו וע' ב'תתקמז. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370179\" data-slug=\"torah-or\" data-id=\"3901370179\">מקץ לט, ג</a>. שע\"ת קמה, א."],["4276","171","<b>ד' בחי'. . לג' קוין</b>: בד: דמבחי'. . ג' הקוין."],["4277","*172","<b>חו\"ג בעצמו' א\"ס</b>: ראה לקמן פ' בשלח קנה, א. קסז, ג. שע\"ת פז, א הערה 5."],["4278","172","<b>דאוא\"ס למעלה [מעלה]</b>: נסמן לעיל פ' שמות ד, ד."],["4279","173","<b>בעא\"ע</b>: ב: בעילוי אחר עילוי."],["4280","174","<b>סדכ\"ס</b>: לשון הזהר בהקדמה ב, א. ועוד."],["4281","175","<b>כי אמרתי. . יבנה</b>: תהלים פט, ג."],["4282","176","<b>לאוהבו</b>: בד: לאו\"נ לאוהב נאמן. — ראה גם לקמן פ' משפטים רפט, ג: אוהבו נאמנו. תצוה שמה, ב. ויקהל שצז, ג. שע\"ת יב, ד הערה 53."],["4283","177","<b>עם היות. . שהן</b>: בד: אם הי'. . שהוא."]]],[2300540454,"ומדות דזו\"נ שנק' הוא וב\"ד כנ\"ל, מאחר שהאור ושפע הי' הולך כפי סדר ההשתל' והתלבשות הפרצופי' מז\"ת דא\"א לאו\"א ומשם לזו\"נ דאצי' שבא האור בדרך עו\"ע בסדר והדרגה שבא בבחי' התחלקות המדות מן השכל וטעם דוקא שאין צד טעם [ו]זכות לישראל יותר לעמוד לנגד מדה\"ד כי לא קיבלו אז עדיין תומ\"צ (וגם זכות אינו אלא בחג\"ת דא\"א וע\"י לבד כידוע [ב]מ\"ש אשר נשבעת לאבותינו מימי קדם<sup data-n=\"4284\">178</sup> שהן חג\"ת דע\"י וא\"א כו'), וכידוע שבשעת קי\"ס טענה מדה\"ד מה נשתנו אלו מאלו כו', אלא במ\"כ<sup data-n=\"4285\">179</sup> הי' האור והשפע בא מלמעלה מסדר ההשתל' וההתלבשות דז\"ת דע\"י וא\"א באו\"א וזו\"נ דהיינו מבחי' פנימי' אור הכתר שבעצמו' המאציל ממש שזהו בחי' פנימי' ועצמי' הרצון ותענוג העליון שא\"א לבא בהתלבשות כלל בטעם לרצון אפי' בטעם כמוס כו'<sup data-n=\"4286\">180</sup> וממילא לא בא בבחי' או\"א דאצי' שהוא גילוי השכל והטעם (שלא ע\"י משפט התורה דאורייתא מח\"ע נפקת<sup data-n=\"4287\">181</sup> מאחר שלא קיבלו ישראל עדיין תומ\"צ כלל), והוא מצד האה\"ר העצמי' ממש דאב לבנו שלא בא בהתחלקות חו\"ג ברצון כלל שנק' פנימית הכתר בבחי' ג\"ר שבו ששם הוא מאיר בחי' פנימי' ועצמי' דאוא\"ס<sup data-n=\"4288\">182</sup> ב\"ה ממש כו'<sup data-n=\"4289\">193</sup>, ומיד שבא אור ושפע זו מבחי' פנימי' ועצמו' אוא\"ס שבכתר הי' הולך ומאיר ובא למטה מטה בסוף כל המדרגות דע\"ס [דוקא] והוא בחי' המל' דוקא שלא ע\"י התלבשות<sup data-n=\"4290\">183</sup> האור תחלה באו\"א וז\"א וגם לא במדות דא\"א כנ\"ל, וזהו הנק' דילוג כמ\"ש קול דודי הנה כו' מדלג על ההרים שהן המדות דרצון<sup data-n=\"4291\">184</sup> ות\"ס<sup data-n=\"4292\">185</sup> בחי' דילוג זה הי' [מ]למעלה מן סדר והדרגה דהשתלשלו' הע\"ס מאור הכתר דהיינו על המדות [ו]חכ' שבו שנק' הרים עליונים ג\"כ והוא למעלה [גם] מבחי' חג\"ת דא\"א הנ\"ל וכמ\"ש ההרים רקדו כאילים<sup data-n=\"4293\">186</sup> כו' כמ\"ש במ\"א, ובחי' דילוג זה הי' דוקא בבחי' המל' לפי שנתחב\"ס<sup data-n=\"4294\">187</sup> דוקא שזהו הכלל בכ\"מ דכל הגבוה<sup data-n=\"4295\">188</sup> גבוה יותר יותר<sup data-n=\"4296\">189</sup> ירידתו והשפלתו למטה מטה ביותר כו' וד\"ל.\n<b>וזהו</b> שרש ענין הפסח שהוא בחי' הדילוג שא' בשה\"ש, רק שבכאן א' להיכן הוא הדילוג והוא מ\"ש ופסח ה' על הפתח שזהו בחי' המל' שנק' פתח האהל<sup data-n=\"4297\">190</sup> (כמשי\"ת בסמוך), והוא מ\"ש ועבר הוי' לנגוף כו' וראה את הדם על המשקוף וב' המזוזות דוקא כו', שמפני שבא האור מבחי' פנימי' הכתר ששם בחי' חו\"ג בהתכללות",[["4284","178","<b>אשר. . מימי קדם</b>: מיכה ז, כ. ראה זהר [אד\"ר] נשא קלד, ב. קלח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעג. אמ\"ב שער הק\"ש פ\"ט. מאמרי אדה\"א בראשית ע' רמא. ויקרא ח\"ב ע' תשעז וע' תתנא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670522\" data-slug=\"torat-chaim\" data-id=\"2300670522\">תו\"ח וירא קז, א</a>. לקמן פ' בשלח קנה, ד. קצט, ד. רד, ד. משפטים ש, ד."],["4285","179","<b>במ\"כ</b>: במכת בכורות ( ). בד: ביצ\"מ."],["4286","180","<b>כו'</b>: בד: כנ\"ל."],["4287","181","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל פ' שמות יא, א."],["4288","182","<b>דאוא\"ס</b>: בד: דא\"ס."],["4289","193","<b>כו'</b>: כנצ\"ל: כו')."],["4290","183","<b>שלא ע\"י התלבשות</b>: ראה אוה\"ת בא כאן (ע' ב'תרלו בהג\"ה וס\"ע ב'תתקמז ואילך)."],["4291","184","<b>הרים המדות דרצון</b>: נסמן לעיל יד, ד."],["4292","185","<b>ות\"ס</b>: בד: וחכ'. ח: וח\"ס וחכ' סתימאה."],["4293","186","<b>ההרים רקדו כאלים</b>: תהלים קיד, ד. ראה מאמרי אדה\"א ויקרא ח\"א ע' שצה ואילך. שה\"א קד, ב ואילך."],["4294","187","<b>שנתחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["4295","188","<b>הכלל בכ\"מ דכל הגבוה</b>: נסמן לעיל כא, ב."],["4296","189","<b>יותר</b>: בד: ליתא."],["4297","190","<b>המל' שנק' פתח האהל</b>: נסמן בפיסקא הבאה."]]],[2300540474,"כא' ממש כנ\"ל ע\"כ מזה הטעם הי' ביכולת בחי' המל' שבבחי' לילה לסבול ב' הפכים דחו\"ג [בהתכללות] כא' ברגע א' לנגוף למצרים ולרפאות לישראל כו'. וז\"ש ויהי בחצי הלילה דוקא וה' הכה כל בכור כו' הוא וב\"ד יחד להיות חסד לזה ודין לזה ברגע <span data-k=\"pg\">קכח</span> ּ א' בחצות לילה שנחלקה הלילה לב' חצאי חלקי' שאז הוא בחי' התכללו' דחו\"ג וגם בחי' ההתחלקות כנ\"ל, משא\"כ אם הי' האור בא בדרך התלבשות באו\"א שהוא בחי' הקוין דחו\"ג מחולקים לא הי' יכול להיות חסד לישראל בשעת הדין למצרים וד\"ל (אך עדיין אין זה מובן דאם הי' האור בא מבחי' פנימי' הכתר ששם כלולים חו\"ג יחד ממש א\"כ איך נחלקים להיות חסד לזה ודין לזה דוקא ובחצות הלילה דוקא מאחר ששם הן שוין ממש בלי התחלקות כלל (וכנ\"ל דבעצם הרוממות דאוא\"ס שבכתר שוין חשך ואור ישראל ועמים שזהו שביקש משה שלא תשרה שכינה<sup data-n=\"4298\">191</sup> כו' משום דקמי' ממש כחשיכה כאורה<sup data-n=\"4299\">192</sup> כו'. ועוד דלפי כל הנ\"ל שהאור בא מלמעלה מבחי' חו\"ג דא\"א שנק' יד הגדולה והחזקה א\"כ איך א' ויוציאנו ה' אלקינו שהן או\"א ביד חזקה כו' שהן בחי' [חו\"ג] דא\"א דוקא כו'. אך שרש הענין הוא משום דגם בעצמו' ופנימי' דא[א]\"ס ב\"ה שכלול מחו\"ג כנ\"ל יש בחי' התחלקות דחו\"ג דוקא, אבל זהו בבחי' פנימי' ועצמו' דוקא כאהבת האב לבן בעצמות נקודת הרצון הפשוט רק שהן כלולים כא' ממש כו' כמו באהבה עצמי' כו', ושם דוקא נבדלו ישראל בבחי' פנימי' ועצמו' כמ\"ש יבחר לנו<sup data-n=\"4300\">194</sup> כו'. וכידוע בענין הגורלות דיו\"כ<sup data-n=\"4301\">195</sup> שגם נקודת מקור הרצון תולה בגורל איך [ש]יפול ולא שיהי' מצד החפץ ורצון עצמו כי מצד בחי' העצמו' ממש ירצה בישראל למעלה מטעם לרצון ולמעלה מעצם הרצון כו' וכמ\"ש שם באורך בענין הפיל פור דהמן שאמר עם הספר ישוב<sup data-n=\"4302\">196</sup> כו'. ולפ\"ז גם כאן הי' בחי' הדילוג גם על ח\"ס דא\"א רק מבחי' פנימי' ועצמו' דבעל הרצון הוא שנחלק דוקא להיות חסד לישראל ודין למצרים, והוא בחי' ההבדלה בפנימי' ועצמי' באהבה עצמי' הנ\"ל רק שהיו כלולים שם ובבחי' המל' למטה יצא לגילוי התחלקו' זו שלא הי' יכול לבוא בחו\"ג<sup data-n=\"4303\">197</sup> ומדות גם ברצון עצמי' כו', רק במל' דוקא בדרך דילוג בסוף הכל, מפני שכנ\"י שהוא בבחי' המל'<sup data-n=\"4304\">198</sup> נק' ג\"כ בצורת משקוף כו' כמשי\"ת שהוא בחי' האמונה העצמי' כו'. וזהו ואנכי תרגלתי לאפרים כו' כאיש גבוה קומה שכופף א\"ע להרים התינוק שמוטל לארץ בידיו הגדולים וכמ\"ש ואעבור עליך<sup data-n=\"4305\">199</sup> ואראך מתבוססת בדמיך כו' (כמשי\"ת), קחם על זרועותיו למעלה מחו\"ג דא\"א, וכידוע בענין רישא דמלכא בחו\"ג אתתקן<sup data-n=\"4306\">200</sup> שהזרועות שרשם למעלה",[["4298","191","<b>שביקש משה. . שכינה </b>[ד: ניתוסף: באוה\"ע]: נסמן לעיל פ' שמות לא, א."],["4299","192","<b>כחשיכה כאורה</b>: ראה גם לעיל סד, א ובהנסמן שם."],["4300","194","<b>יבחר לנו</b>: תהלים מז, ה."],["4301","195","<b>בענין הגורלות דיו\"כ</b>: ראה מאמרי אדה\"א נ\"ך ע' שסז ואילך. וש\"נ."],["4302","196","<b>הפיל פור. . עם הספר ישוב</b>: אסתר ג, ז. ט, כה. ראה מאמרי אדה\"א שם ע' שסט ואילך."],["4303","197","<b>בחו\"ג</b>: בד: בחו\"ב."],["4304","198","<b>שכנ\"י. . המל'</b>: ראה זהר בלק קצז, א."],["4305","199","<b>ואעבור עליך</b>: יחזקאל טז, ו."],["4306","200","<b>רישא דמלכא בחו\"ג אתתקן</b>: ראה זהר (אדרא דמשכנא) משפטים קכב, ריש ע\"ב. לקמן פ' בשלח רמט, א [ושם: באדר\"ז]. שעה\"י קכז, א הערה 13."]]],[2300540492,"מן הראש<sup data-n=\"4307\">201</sup>. וז\"ש ויוציאנו ביד חזקה ובזרוע נטוי' דוקא שלא ע\"י המדות שברצה\"ע אלא ע\"י [המדות ד]חו\"ג שבפנימי' ועצמי' דוקא שלמעלה מראש וגלגלתא דא\"א כו' ומטעם הנ\"ל בענין הגורלות וד\"ל).\n[ה] ומעתה י\"ל ענין מ\"ש ועבר הוי' לנגוף את מצרים וראה את הדם על המשקוף וב' המזוזות דוקא אז ופסח הוי' על הפתח כו', והנה יש להקדים תחלה בשרש ענין הפתח למעלה שזהו בחי' המל' שנק' פתח ושער להוי' כמ\"ש בזהר ע\"פ והוא יושב פתח האהל<sup data-n=\"4308\">202</sup> כו' וכן במ\"ש ותשב בפתח עינים<sup data-n=\"4309\">203</sup> וכה\"ג במ\"ש פתחי לי אחותי<sup data-n=\"4310\">204</sup> כו' דאנת פתחא לאעלאה כו'. והטעם הוא כמו עד\"מ הפתח למטה בגשמי' שעיקר ענינו הוא רק לשמש כניסה ויציאה מן הבית לחוץ ומחוץ לפנים ואם אין פתח <span data-k=\"pg\">258</span> ּ אין אדם נכנס מחוץ לפנים ואינו נק' בית בלא פתח שיכנסו בבית והיכלות<sup data-n=\"4311\">205</sup> ע\"י הפתח ושיוכלו לצאת מן הבית לחוץ, ואע\"פ שהפתח עצמו אינו כלום שהרי אינו רק מקום חלל פתוח לבד ואינו נחשב כלל מן עצם הבנין אבל תועלת[ו] לכניסה ויציאה הוא עיקר המכוון מדירת הבית וכל אשר בו כידוע. וכך יובן למעלה בבחי' הפתח העליון הרוחני' שהוא בחי' המל' שנק' פתח לגבי עולם העליון דאצי' שכל האורות העליונים דאצי' וגם לפני האצי' יוצאים מפנים לחוץ ע\"י בחי' הפתח הזה דוקא וכל העולמות התחתונים שעולין ונכללין באצי' עולים בפתח זה דוקא. והענין הוא כידוע דבחי' הדיבור העליון כמו בעש\"מ נק' מאמר פתוח<sup data-n=\"4312\">206</sup> כמ\"ש פיה פתחה בחכ'<sup data-n=\"4313\">207</sup> כו', כמו הדיבור באדם למטה שבו וע\"י נתגלה הכל מן ההעלם שבנפשו גם ממקור הרצון והתענוג וחכ' ומדות שבשכל ולב ומח' עד סוף המעשה הכל יוצא דרך הפה בדבור, ועד\"ז הן הי\"מ כמו ויאמר יהי אור<sup data-n=\"4314\">208</sup> יהי רקיע<sup data-n=\"4315\">209</sup> כו' הרי גם בחי' מקור הרצון והתענוג [ו]שכל ומדות שמלובש במאמר זה יצא ונגלה לחוץ להיות התהוות אור ורקיע כו', וכך הוא [גם] בכל פרטי התהוות העולמות ומלאכים העליונים מאין ליש ע\"י מאמר פתוח הזה ולכך נק' פתח האוהל בכלל שע\"י יוצאים כל האורות העליונים דע\"ס דאצי' לגילוי בבי\"ע כידוע וד\"ל. וכמו\"כ בהמשכות גילוי השכינה למטה ממש בהיכל ק\"ק והנבואה שבנביאים ובמרכבה עליונה וגם בגילוי הנסים ונפלאות שמאיר מאורות דע\"ס דאצי' ממש בבי\"ע הכל הוא בא ויוצא דרך בחי' המל' שנק' פתח עד\"מ [הפתח] בבית",[["4307","201","<b>שהזרועות שרשם למעלה מן הראש</b>: ראה לקמן צה, ד: כידוע בענין נשיאת כפים [נסמן לעיל פ' וארא עב, ב הערה 52]. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנד. מאמרי אדה\"א שמות ח\"ב ע' תקכא."],["4308","202","<b>והוא יושב פתח האהל</b>: וירא יח, א. זהר בא לו, א (ובמק\"מ שם). בשלח סה, ב. ויקרא יד, א."],["4309","203","<b>ותשב בפתח עינים</b>: וישב לח, יד. ראה זהר בהקדמה א, ב. אחרי עא, ב (ובאוה\"ח שם)."],["4310","204","<b>פתחי לי אחותי</b>: שה\"ש ה, ב. ראה זהר אמור צה, א."],["4311","205","<b>והיכלות</b>: ב: והיכלי'. ד: והכל."],["4312","206","<b>הדיבור. . מאמר פתוח</b>: נסמן לעיל פ' שמות יב, ב."],["4313","207","<b>פיה פתחה בחכ'</b>: משלי לא, כו."],["4314","208","<b>ויאמר יהי אור</b>: בראשית א, ג [בדילוג]."],["4315","209","<b>יהי רקיע</b>: שם א, ו."]]],[2300540510,"גשמי [ש]משמש יציאה מן הבית [מבפני'] לחוץ כו', ואם אין פתח הי' הכל סתום וגנוז בבית אין דבר מה יוצא משם כו' וד\"ל (וכמו שעיקר שלימות הרצון והשכל ומדות לבא לידי מעשה בבנין וחסד בפו\"מ או בשפע דבר חכ' אינו אלא ע\"י הדיבור דוקא. כך הוא למעלה בדבור העליון דכתי' כי אמרתי עולם חסד [יבנה ע\"כ] כו'<sup data-n=\"4316\">210</sup> גם בחי' שלימות דרצון וחכ' דמע\"ב הוא כאשר יצא[ו] מן ההעלם לגילוי בפה [העליון] שנק' פתח כמ\"ש פיה פתחה בחכ' וכן בד\"ת). והנה כמו\"כ תועלת השני דפתח העליון לשמש כניסה מחוץ לפנים שזהו כל בחי' העלאות מ\"נ דמלאכים ונשמות דבי\"ע שכולן עולין בכל חדש ושבת<sup data-n=\"4317\">211</sup> להשתחוות לפני הוי'<sup data-n=\"4318\">212</sup> בבחי' האצי' ממש לאשתאבא בגופא דמל[כא<sup data-n=\"4319\">213</sup> ממש], כידוע בענין עליות העולמות בכל ערב שבת<sup data-n=\"4320\">214</sup> כי זהו<sup data-n=\"4321\">215</sup> ג\"כ ע\"י המל' שנק' פתח ושער כמ\"ש זה השער להוי'<sup data-n=\"4322\">216</sup> דאצי' [ו]כמ\"ש יעקב וזה שער השמים<sup data-n=\"4323\">217</sup> כו', וגם כל העלאות ובירורי' דרפ\"ח כו' עולין הכל בבחי' המל' דוקא גם בקרבנות ועבודות שבבהמ\"ק כמ\"ש בזא\"ת יבא אהר\"ן<sup data-n=\"4324\">218</sup> כו' כמ\"ש בזהר ולמטה הוא שנק' פתח אהל מועד<sup data-n=\"4325\">219</sup> כו' (והוא ענין היראה תתאה שנק' זאת<sup data-n=\"4326\">220</sup> שעז\"א פתח[י] לי כו' שאם אין יראה<sup data-n=\"4327\">221</sup> אין חכ' כו', וזהו שת\"ח שאין בו יר\"ש<sup data-n=\"4328\">222</sup> דומה לגזבר<sup data-n=\"4329\">223</sup> כו' כמ\"ש במ\"א). וידוע דרוח אייתי רוח<sup data-n=\"4330\">224</sup> ואמשיך רוח שע\"י העלאת מ\"ן דעולמות שעולין באצי' אח\"כ נמשך המשכת מ\"ד דחסדים עליונים דאצי' בבי\"ע ה\"ז נק' בשם יציאה מפנים לחוץ שהוא דוקא ג\"כ ע\"י בחי' הפתח שהוא בחי' המל' אחר שנק' שער [ל]ה' כנ\"ל שמשמש כניסה ויציאה שזהו עיקר התועלת דאוהל כו' וד\"ל.\n<b>ומעתה</b> י\"ל בענין צורת הפתח הזה <span data-k=\"pg\">קכט</span> ּ שהוא המשקוף וב' המזוזות דוקא ואם לא בציור כזה אינו נק' פתח כלל והיינו שהמשקוף העליון מחבר הוא לב' המזוזות דימין ושמאל והוא המחזקם ומקיימם ובלעדו אין להם קיום, ולכך המזוזות דימין ושמאל נשלבים בתוך המשקוף שיחזקם ויחברם [יחד] ואין פתח בלא משקוף וב' מזוזות לימין ושמאל דוקא. ולכאורה אין מהצורך לתועלת הפתח לשמש כניסה ויציאה במשקוף וב' מזוזות דוקא כי גם [ב]פתח חל[ו]ל לבד יהי' תועלת לזה, ולמה דוקא בב' מזוזות ולא בג' וד' כו', אך הנה ענין צורת הפתח במשקוף וב' מזוזות מורה על יחוד מקום הפתח שבו יהי' הכניסה ויציאה לכל ולא במקום אחר זולתו כו'. ויובן דוגמתו למעלה",[["4316","210","<b>כו'</b>: בד: ליתא."],["4317","211","<b>ונשמות. . עולין בכל חדש ושבת</b>: נסמן לעיל פ' שמות לה, ב."],["4318","212","<b>להשתחוות לפני ה'</b>: ישעי' סו, כג [בדילוג]."],["4319","213","<b>לאשתאבא בגופא דמל[כא]</b>: נסמן לעיל ה, ב."],["4320","214","<b>עליות העולמות בכל ערב שבת</b>: ראה פע\"ח (שער השבת) שי\"ח, פ\"ו ואילך. שע\"ת לג, סע\"ד. ש\"א כח, א. לקמן פ' ויקהל תלז, א."],["4321","215","<b>כי זהו</b>: בד: כו' (ו)זהו."],["4322","216","<b>זה השער להוי'</b>: תהלים קיח, כ. ראה זהר בהקדמה ז, ב (ובמפרשים שם). (רע\"מ) תרומה קנח, א (ובאוה\"ח שם). מאמרי אדה\"ז תקס\"ט ע' מט וע' נז. מאמרי אדה\"א במדבר ח\"ב ע' תו."],["4323","217","<b>וזה שער השמים</b>: ויצא כח, יז."],["4324","218","<b>בזא\"ת יבא אהר\"ן</b>: אחרי טז, ג. ראה ת\"ז בהקדמה (יא, סע\"ב). פרדס (שעה\"כ) שכ\"ג, מערכת זאת."],["4325","219","<b>פתח אהל מועד </b>[ב' תיבות אחרונות ליתא בד]: תצוה כט, ד. ועוד."],["4326","220","<b>היראה. . זאת</b>: ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב. וש\"נ."],["4327","221","<b>שאם אין יראה</b>: אבות פ\"ג, מי\"ז."],["4328","222","<b>ת\"ח שאין בו יר\"ש</b>: ראה שבת לא, סע\"ב [כגי' הר\"ח — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשב. וש\"נ. הנחות תקע\"ז ע' פג. וש\"נ]. לקמן פ' בשלח רכז, ב."],["4329","223","<b>ת\"ח. . דומה לגזבר</b>: ראה גם מאמרי אדה\"א ויקרא שם ע' תשטו."],["4330","224","<b>דרוח אייתי רוח</b>: נסמן לעיל פ' וארא סג, ג."]]],[2300540528,"בבחי' פתח העליון שהוא בציור כזה [ח] (והוא כמו ציור אות הח' דוקא ולא בציור אחר כו'), דהנה מבואר למעלה שבחי' הדבור עליון נק' פתח לפי שהוא המגלה כל מצפון והעלם דע\"ס דאצי' כמו אור הרצון ושכל הנעלם ומדות ומח' וכל פרטי פרטיהן הכל בא בגילוי בפה בדבור העליון ולפ\"ז הרי אין בדבור רק כהע\"ס כמו שהן<sup data-n=\"4331\">225</sup> למעלה באצי' דוקא בלי תוס' ושינוי כלל, וכמו בדבור האדם שיגלה בו רצונו וחכמתו ומדותיו ואותיות מחשבתו כמו שהן ממש בלי שינוי, וידוע דכל האצי' כולו נחלק לג' קוין ימין ושמאל ואמצע, והיינו שנחלק הכתר לג'<sup data-n=\"4332\">226</sup> קוין חו\"ב ודעת קו האמצעי, והוא כמו באדם הרי הרצון מתלבש בחו\"ב<sup data-n=\"4333\">227</sup> להטות לימין בין שמאל<sup data-n=\"4334\">228</sup> בג\"ה והדעת נוטה ומכריע לימין ושמאל עד בחי' המל' שתחת יסוד שבקו האמצעי<sup data-n=\"4335\">229</sup> שמקבל[ת] מכל הג' קוין יחד דוקא כידוע, וא\"כ יש להבין למה צורת הפתח דבחי' המל' שהיא צורת אות הח' מ\"מ<sup data-n=\"4336\">230</sup> אינו רק בב' קוין לימין ושמאל, אחר שהמל' נק' פתח לשמש כניסה ויציאה הרי מגלה כל נהורין עילאין שבא בהתחלקות ה[ג' קוין] מאור הכתר שנחלק לג' קוין דוקא, וכמו הדבור באדם שמגלה כל ג' מיני המשכות הרצון [ב]שכל בחו\"ג<sup data-n=\"4337\">231</sup> ודעת נוטה הכוללם יחד כו' דכמו שרצון של חו\"ג ושכל [של חו\"ג] מתגלה בדבור כך גם בחי' ההכרעה [ד]דעת ות\"ת כו' מתגלה ג\"כ בדבור ואדרבה הוא העיקר שנק' בריח התיכון שכולל לב' הקוין שמשפיע למל' כו'.\n<b>אך</b> צ\"ל בענין צורת הפתח שהוא כמו [כ]משקוף ושתי מזוזות שזהו כמו בחי' הכתר עצמו שהוא כמו ענין המשקוף ע\"ג ב' מזוזות כך הוא העומד ע\"ג ב' קוין ימין ושמאל לבד ומחברם ומחזקם יחד ואין כאן קו אמצעי כלל רק ב' קוין דחח\"ן ובג\"ה לבד ובחי' הכתר עומד עליהם להיותו מעמיד ומקיים לקו ימין ולקו שמאל יחד והן נכללים בו כדמיון המשקוף שמחבר לב' המזוזות דימין ושמאל. ולכאורה זהו שלא כסדר ההשתל' דאור הכתר שנחלק לג' קוין ולא לב' קוין לבד והי' מהראוי שיהי' צורת הפתח בג' קוין דוקא אם [ה]טעם שהמל' נק' פתח לפי שמקבל מכל האורות דע\"ס כו'. אך שרש הענין הוא כידוע שיש ב' מדריגות בבחי' אור הכתר א' פנימי' הכתר שלמעלה עדיין מבחי' התחלקות לג' קוין באצי' וכמו באדם הוא עצם נקודת הרצון כמו שהוא טרם שבא לכלל טעם לרצון שלא יבא עדיין בבחי' חו\"ב ודעת מכריע כלל, והב' בחי' חיצוני' הכתר שהוא בחי' ח\"ס חכ' וטעם כמוס לרצון כנ\"ל שזהו הבא בבחי' התחלקו' לג' קוין באצי' חח\"ן [דת\"י] בג\"ה להיותו בא בהתלבשות בחו\"ב ודעת מכריע כו' כמ\"ש בפרד\"ס בשער הצנורות. ועפ\"ז יובן ג\"כ בענין צורת הפתח דבחי' המל' שהוא בציור ב' קוין <span data-k=\"pg\">260</span> ּ לבד [כ]משקוף ע\"ג ב' המזוזות הוא אור הכתר",[["4331","225","<b>רק כהע\"ס </b>[ח: הע\"ס]<b> כמו שהן</b>: ב: רק כמו שהע\"ס הן. ד: רק כמו, והניח מקום פנוי."],["4332","226","<b>לג'</b>: בד: לב'. אמנם בסמוך הוא כבפנים לג'."],["4333","227","<b>בחו\"ב</b>: ג: בחו\"ג ( ). וראה להלן הערה 231."],["4334","228","<b>בין שמאל</b>: בד: חח\"נ ולשמאל."],["4335","229","<b>המל' שתחת יסוד שבקו האמצעי</b>: ראה פרדס (שער סדר עמידתן) ש\"ו, פ\"א. פ\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670079\" data-slug=\"torat-chaim\" data-id=\"2300670079\">תו\"ח לך פ, ד</a> הערה 46."],["4336","230","<b>מ\"מ</b>: בד: ממש."],["4337","231","<b>בחו\"ג</b>: בד: בחו\"ב."]]],[2300540546,"שע\"ג ב' הקוין כו' שזהו דוקא בבחי' פנימי' הכתר שאז בחי' קו האמצעי עולה ונכלל בעצמו' הכתר ואינו נחשב בפ\"ע אבל הב' קוין הן שבעצמו' הכתר ממש (והוא כח\"ב בחי' ג\"ר שהוא כסגול העליון שהוא בציור ה\"א<sup data-n=\"4338\">232</sup> עם הפתח רק שהכתר אינו רק נקודה וב' הקוין והסגול<sup data-n=\"4339\">233</sup> אינו רק ג'<sup data-n=\"4340\">234</sup> נקודות כו', וזהו שכאשר הכתר נמנה עם י\"ס כח\"ב חג\"ת נהי\"מ אין הדעת נמנה שהוא קו האמצעי שנכלל בעצמו' הכתר וכאשר אין הכתר נמנה להיותו בבחי' פנימי' שבו [כנ\"ל] אז הדעת נמנה שזהו כשבא הכתר בהתחלקות דג' קוין והוא חב\"ד חג\"ת נהי\"מ כו'). וביאור הענין הוא<sup data-n=\"4341\">235</sup> היינו ענין התחלקות ב' קוין [ד]חו\"ג שבעצמות נקודת הרצון הפשוט הנ\"ל באהבת עצמו לחיים ולא למות או לאהבת נפש בנו או לשנוא לשונא בעצם כו' שאינו בא טעם כמוס ג\"כ כו' וכלולים כא', ובאים בהתחלקות בבחי' המל' דוקא שהוא צורת הפתח במשקוף וב' מזוזות דוקא שהוא ב' קוין דחו\"ג לבד ואין בו קו אמצעי דדעת כלל, לפי שזהו בבחי' עצמי' הנפש ברצון הפשוט ועצמי' ממש כנ\"ל שלמעלה מן הטעם ודעת לגמרי כנ\"ל, דמה שיתחלקו ממנו לדבר והיפוכו אינו רק ב' קוין דחו\"ג בעצמו'<sup data-n=\"4342\">236</sup> ואין בזה שינוי וחילוף מזל\"ז לעולם כמו כי לא אדם הוא להנחם<sup data-n=\"4343\">237</sup> בחו\"ג שבו ברצון ושכל כו' (וכנ\"ל<sup data-n=\"4344\">238</sup> בענין הגורלות דיוכ\"פ שלעולם יפול הגורל לחסד [ע]ל ישראל, לפי שגם בעצמו' ממש נבדלו ישראל בבחי' פנימי' ועצמי' שממילא יוכלל בזה הרצון שע\"פ הדעת ובחירה כו' וע\"כ נכלל בזה קו האמצעי דד\"ת<sup data-n=\"4345\">239</sup>, ואין כאן רק ב' קוין והן ב' מזוזות ומשקוף העליון שהוא עצמו' אור הכתר ע\"ג לחברם ולחזקם יחד וזהו עיקר ענין הפתח בציור ח' כשמל' מקבל מהכתר עצמו שהוא (ג\"ר כח\"ב כנ\"ל) דוקא ולא כשהמל' מקבל מהג' הקוין שהוא בציור הח'<sup data-n=\"4346\">240</sup> כו', וזהו ישראל לסגולת\"ו<sup data-n=\"4347\">241</sup> סגול התחתון שמקבל מסגול העליון כמשי\"ת בעז\"ה וד\"ל.\n[ו] <b>וזהו</b> ועבר הוי' לנגוף את מצרים וראה את הדם על המשקוף וב' המזוזות דוקא אז ופסח ה' על הפתח כו', דמשמע פשוטו שאם לא הי' רואה את הדם על המשקוף ושתי המזוזות לא הי' פוסח על הפתח דבתי בנ\"י ולא הי' ניצולים גם ישראל, וזהו פלא גדול דהלא עיקר העברה זאת הי' רק לנגוף למצרים במכת בכורות ואיך הי' הדין הזה נמשך גם לישראל ולמה [נ]גרע כח ואות ומופת זה האחרון משאר המכות שהפלה ה' בין ישראל למצרים כו'. אך הנה א' ואעבור עליך ואראך [כו'] ואומר לך בדמייך חיי בפו\"מ<sup data-n=\"4348\">242</sup>, להיות מבואר לעיל בעיקר ענין צורת הפתח במשקוף וב' מזוזות שמורה על בחי' עצמו' אור הכתר שכלול מב' קוין דחו\"ג העצמיי' [ד]אה\"ר [כו'] שלמעלה מעלה גם מן הרצון שמורכב בטעם כו' כאהבת עצמו<sup data-n=\"4349\">243</sup> דאב",[["4338","232","<b>ה\"א</b>: בד: א'."],["4339","233","<b>והסגול</b>: בד: ליתא."],["4340","234","<b>ג'</b>: בד: ב'."],["4341","235","<b>הוא</b>: בד: ליתא."],["4342","236","<b>בעצמו'</b>: בד: העצמיי'."],["4343","237","<b>כי לא אדם הוא להנחם</b>: שמואל-א טו, כט. ראה גם לעיל פ' שמות כט, א."],["4344","238","<b>(וכנ\"ל</b>: בד: כנ\"ל."],["4345","239","<b>דד\"ת</b>: ב: דדת\"י. ד: דדעת."],["4346","240","<b>הח'</b>: בד: הא'."],["4347","241","<b>ישראל לסגולת\"ו</b>: תהלים קלה, ד."],["4348","242","<b>בפו\"מ</b>: בד: ב\"פ ב' פעמים."],["4349","243","<b>כאהבת עצמו</b>: ב: כאהב' עצמיי'."]]],[2300540563,"לבנו יחידו שאהבת נפשו ממש אהבו כו'. וכך הוא כמים הפא\"פ<sup data-n=\"4350\">244</sup> כו' מכנ\"י לקוב\"ה שנק' בנים<sup data-n=\"4351\">245</sup>, שאה\"ר שלהם עצמי' ממש שלמעלה מן הטעם לרצון והוא בחי' הרצון הפשוט ועצמי' בלתי בחירה ברצון שאין בו שינוי וחילוף לעולם (שלמעלה מבחי' אדם להנחם וכמ\"ש כי אתה אבינו אתה ממש ואברהם לא ידענו<sup data-n=\"4352\">246</sup> כו' שלא מצד אור החכ' שברצון שנק' אב כו', וזהו שנק' דילוג שדולג על ההרים מדות דרצון וחכ' כנ\"ל), והוא ענין האמונה הפשוטה העצמי' ממש שלמעלה גם מן האמונה שירשו מאברהם (וכמ\"ש במ\"א בענין ורע\"ה אמונה<sup data-n=\"4353\">247</sup> שהוא האמונה באמיתי' אור עצמותו ית' ממש <span data-k=\"pg\">קל</span> ּ דאיהו אמת [איהו] ממש ואיהי אמונה<sup data-n=\"4354\">248</sup> שהן כלי קיבול לאמיתת העצמו' דא\"ס ממש כמ\"ש אמתך אלקי<sup data-n=\"4355\">249</sup> כו', שלמעלה מן האמונה בשם הוי' ואלקי' סובב וממלא<sup data-n=\"4356\">*250</sup> שזהו רק אמונה דאבות כמ\"ש בטחו בה'<sup data-n=\"4357\">250</sup> כו', וע\"כ כולם שוין בה מקטן ועד גדול<sup data-n=\"4358\">251</sup> וכמו לע\"ל דכתי' ולא ילמדו איש<sup data-n=\"4359\">252</sup> [כו'] כי כולם [בשוה] ידעו אותי ממש שהוא למעלה מבחי' [אד\"ם] ששוה שם ראש ורגל דציור קומת אדם כמ\"ש כי לא אדם הוא כו'. והוא ענין המצה שנק' מיכלא דמהימנותא<sup data-n=\"4360\">253</sup> שגם משה הי' חייב בה רק שהי' ראש לזון ולפרנס לכנ\"י באמונה זו העצמי' נק' רע\"מ<sup data-n=\"4361\">254</sup> כו'). והיינו ענין וארשתיך לי באמונה<sup data-n=\"4362\">255</sup> שהוא בחי' האמונה העצמי' באמיתת עצמות א\"ס שבפנימי' הכתר שנק' ג\"ר דכתר שהוא בעצמית הרצון [הפשוט] שכולל ב' קוין דחו\"ג העצמי', כאהבת נפש הבן שקשורה בנפש אביו ממש שנמשך כולו אחריו בלי בחירה ברצון וחכ'<sup data-n=\"4363\">256</sup> ודעת כלל<sup data-n=\"4364\">257</sup> וכמ\"ש זכרתי לך<sup data-n=\"4365\">258</sup> חסד נעוריך דוקא לכתך אחר\"י כו', ואין באמונה זאת העצמי' רק ב' קוין דחו\"ג ואין בו קו האמצעי דדעת<sup data-n=\"4366\">259</sup> כלל מטעם הנ\"ל, מפני שהוא כמו שיחפוץ [בחיים ולא יחפוץ] במות שהכל א' כך הוא ית' חיי' נש\"י בבחי' עצמי' ממש למעלה מן הבחירה ברצון כו', ובכלל זה נק'<sup data-n=\"4367\">260</sup> הבחירה שברצון וחכ' שנק' אד\"ם אל\"ף ד\"ם<sup data-n=\"4368\">261</sup> או<sup data-n=\"4369\">262</sup> אאלפך חכ'<sup data-n=\"4370\">263</sup>.\n<b>וזהו</b> שראה את הדם על המשקוף וב' [ה]מזוזות בצורת הפתח דכל<sup data-n=\"4371\">264</sup> עצמו בב' קוין דחו\"ג<sup data-n=\"4372\">265</sup> העצמי' שבכנ\"י כשמקבל המל' מפנימי' הכתר שנק' סגול העליון בחי' ג\"ר כח\"ב [כ]נ\"ל, והוא הי' שרש ומקור האמיתי' לקבל התורה פב\"פ בבחי' אדם א' דם כמ\"ש חכמת אדם העליון תאיר פניו<sup data-n=\"4373\">266</sup> כו' ביוה\"ד<sup data-n=\"4374\">267</sup> שהוא",[["4350","244","<b>כמים הפא\"פ</b>: ע\"פ משלי כז, יט."],["4351","245","<b>מכנ\"י. . שנק' בנים</b>: שמות ד, כב. ראה יד, א. אבות פ\"ג, מי\"ד."],["4352","246","<b>כי אתה אבינו. . ואברהם לא ידענו</b>: ישעי' סג, טז [ושם: כי אברהם]."],["4353","247","<b>ורע\"ה אמונה</b>: תהלים לז, ג. ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' קעו. [נדפס גם לקמן פ' תשא שפא, א ובשינויים קלים ב]דרמ\"צ ע' סה. מאמרי אדה\"א שמות ח\"ב ע' תריט-תרכד. לקמן קי, ד. קיח, ב. פ' בשלח קנה, ד."],["4354","248","<b>דאיהו אמת. . ואיהי אמונה</b>: נסמן לעיל פ' שמות י, ד."],["4355","249","<b>אמתך אלקי</b>: תהלים עא, כב."],["4356","*250","<b>הוי' ואלקי' סובב וממלא</b>: נסמן לעיל פ' וארא עג, ב."],["4357","250","<b>בטחו בה'</b>: ישעי' כו, ד. תהלים קטו, י. יא. בד: בטח בה' — תהלים לז, ג [התחלת הכתוב ורעה אמונה]. קטו, ט."],["4358","251","<b>מקטן ועד גדול</b>: בד: מגדול עד קטן."],["4359","252","<b>ולא ילמדו איש</b>: ירמי' לא, לג."],["4360","253","<b>המצה שנק' מיכלא דמהימנותא</b>: ראה זהר (רע\"מ) בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["4361","254","<b>משה. . נק' רע\"מ</b>: נסמן לעיל פ' וארא עז, ב."],["4362","255","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["4363","256","<b>ברצון וחכ'</b>: דה: ורצון."],["4364","257","<b>וחכ' ודעת כלל</b>: אז: וחכ' ומדות. ב: ות\"כ ותענוג כלל ( ). או שטעה המעתיק וצ\"ל: וחכ'."],["4365","258","<b>זכרתי לך</b>: ירמי' ב, ב."],["4366","259","<b>דדעת</b>: ד: ליתא."],["4367","260","<b>נק'</b>: בד: נכלל."],["4368","261","<b>אדם אל\"ף ד\"ם</b>: נסמן לעיל עב, ד."],["4369","262","<b>או</b>: בד: אלף."],["4370","263","<b>אאלפך חכ'</b>: נסמן לעיל פ' שמות טו, ב."],["4371","264","<b>דכל</b>: בד: דכתר."],["4372","265","<b>דחו\"ג</b>: ד: ליתא."],["4373","266","<b>חכמת אדם. . תאיר פניו</b>: קהלת ח, א."],["4374","267","<b>ביוה\"ד</b>: ב: בי' הדיברו'."]]],[2300540579,"בחי' פנימי' התענוג שבחכ' שהאיר בפנימי' החכ' דכנ\"י [עד<sup data-n=\"4375\">268</sup> ] שעל כל דבור פרחה נשמתן<sup data-n=\"4376\">269</sup> כו'. אבל האמונה הפשוטה העצמי' שהי' בהם במצרים הי' למעלה הרבה להיותה בבחי' עצמי' דיחידה שלהם שלמעלה מבחי' אדם (ע\"כ א' להם אהי' אשר אהי' אנא זמין לאתגלאה<sup data-n=\"4377\">270</sup> בעוה\"ב דוקא שנא' ונחי' לפניו<sup data-n=\"4378\">271</sup> ממש וכמ\"ש עם זו קני\"ת<sup data-n=\"4379\">272</sup> בבחי' עצמי' שלמעלה משם הוי' דיוה\"ד כו'). וז\"ש ואראך מתבוססת בדמיך דוקא כי הדם הוא הנפש<sup data-n=\"4380\">273</sup> והוא בחי' עצמי' וטבעי' הראשונה שבתולדת הולד בבטן והמוחין שנמשך בו אח\"כ הוא רק בחי' הרכבה על העצם כו', וע\"כ א' בדמיי\"ך חיי באמונה זו העצמי' דוקא חיי בחיי החיים<sup data-n=\"4381\">275</sup><sup data-n=\"4382\">274</sup> דעצמות א\"ס [ממש] שלמעלה מאור וחיות דא' דאד\"ם שהוא אור החכ' שברצון כו'. וא[מר] ב' פעמים ואומר לך בדמייך חיי נגד ב' הקוין דחו\"ג העצמי' לחיות ולא למות כו', שמזה בא ממילא ב' קוין דחו\"ג ברמ\"ח מ\"ע ושס\"ה ל\"ת ע\"י הדעת ובחירה שהוא קו האמצעי דת\"י שהי' בשעת קבלת התורה כשא' נעשה ונשמע<sup data-n=\"4383\">276</sup>, ו[הוא] ענין סו\"מ וע\"ט עכשיו באמונה [פשוטה] העצמי' שלמעלה מהבחירה ברצון ושכל לגמרי כו'. וזהו אנכי תרגלתי לאפרים שהשפיל א\"ע מראשו לרגלו להרים התינוק הקטן כשנולד ומתבוסס בדמי[ו] דם לידה כו' וכמ\"ש ואראך מתבוססת בדמיך כו' קחם על זרוע\"ו' להעלות[ם עד] למעלה מראשו שהוא [ב]בחי' עצמו' אוא\"ס שלמעלה מראש ומוחין דח\"ס דא\"א כנ\"ל וד\"ל.\n<b>וזהו</b> ועבר הוי' כו' דהעברה זו הוא מאור העצמו' דא\"ס ממש [ו]כמ\"ש ועברתי באמ\"צ אני ולא מלאך כו', ולהיות שבעצמו' א\"ס <span data-k=\"pg\">262</span> ּ ממש הובדלו ישראל בבחי' עצמי' ופנימי' ע\"כ א' וראה את הדם על המשקוף וב' המזוזות ד\"ם הוא בחי' העצמי'<sup data-n=\"4384\">277</sup> (שרמז על דם מילה<sup data-n=\"4385\">278</sup>, ודם פסח זה הי' כמו בחי' דם מילה שנק' אות ברית בעצמו' כמ\"ש בדמיי\"ך חי\"י כמ\"ש במ\"א). ומשקוף העליון הוא עצמות הרצון הפשוט שמחבר לב' הקוין דחו\"ג באוי\"ר עצמי' ואז ופסח ה' על הפתח הזה שדולג עליו לעשות בו ההבדלה הפנימי' הנ\"ל שבעצמו' דוקא שנבדלו בצורת הפתח [כ]זה, ודוקא בראי' הדם על המשקוף וב' מזוזות שיזכור על התקשרות עצמי' דאמונה פשוטה דכנ\"י בעצמות ממש, ואם לא הי' הדם על הפתח הגם שהפלה ה' בשאר מכות בין ישראל",[["4375","268","<b>עד</b>: ד: ע\"י."],["4376","269","<b>שעל כל דבור פרחה נשמתן</b>: נסמן לעיל פ' וארא סט, א."],["4377","270","<b>אהי'. . לאתגלאה</b>: נסמן לעיל א, ב."],["4378","271","<b>ונחי' לפניו</b>: הושע ו, ב."],["4379","272","<b>עם זו קני\"ת</b>: בשלח טו, טז."],["4380","273","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["4381","275","<b>החיים</b>: ב: ליתא."],["4382","274","<b>בחיי החיים</b>: יומא עא, א."],["4383","276","<b>נעשה ונשמע</b>: משפטים כד, ז."],["4384","277","<b>בחי' העצמי'</b>: דה: דבדמיך חיי בחיי הע'."],["4385","278","<b>הדם. . דם מילה</b>: ראה שמו\"ר פי\"ז, ג. פי\"ט ה."]]],[2300540595,"למצרים אבל בהעברה זו הי' מבחי' רוממות העצמו' ממש ששם אור וחשך שוין כמ\"ש ועברתי באמ\"צ כו', ע\"כ הוצרך לאות הדם על צורת הפתח במשקוף וב' מזוזות ש[י]בדיל בהבדלה העצמי' הנ\"ל. משא\"כ בשאר המכות שהי' הבדלה ע\"פ החכ' ורצון דשם הוי' לא הוצרך לזה וד\"ל (וז\"ש קדש לי כל בכור כו' דמשמע הפשוט שהי' בזה רבותא גדולה וחיבה יתירה נודעת<sup data-n=\"4386\">279</sup> לישראל שניצלו וזהו מטעם הנ\"ל, ואמנם בזה גדול יותר מעלת הדילוג הזה על בתי בנ\"י שפסח על הפתח דוקא שזהו הוראה על הבדלה הפנימי' והעצמי' שע\"י האמונה העצמי' שלמעלה ממ\"ת כנ\"ל וד\"ל). ונמצא מובן מכ\"ז שבחי' עצמו' אור הכתר בכללו' שהוא בחי' ג\"ר שבו שהוא כמו משקוף וב' מזוזות לחבר ב' קוין דחו\"ג העצמיי' הוא שבא והאיר בבחי' המל' דוקא שמזה הטעם בחי' המל' דוקא נק' פתח ולא שאר ספי' זולתה שבאים בב'<sup data-n=\"4387\">280</sup> קוין בדרך התחלקות מחיצוני' הכתר לבד כנ\"ל וד\"ל.\n[ז] <b>ומעתה</b> י\"ל עדיין מ\"ש ועבר הוי' כו' וראה את הדם כו' אז דוקא ופסח הוי' על הפתח, דמשמע מזה שכל ענין סיבת התחלת התעוררות הדילוג ממקום הגבוה מאד נעלה שהוא מבחי' העצמי' ממש שז\"ש ופסח ה' שנק' דילוג בשה\"ש<sup data-n=\"4388\">281</sup> (ולבד ענין ההבדלה הנ\"ל שפסח על בתי בנ\"י להצילם כפשוטו)<sup data-n=\"4389\">282</sup>, זה הי' רק כשראה את הפתח שהוא בחי' המל' למעלה על כל בתי בנ\"י<sup data-n=\"4390\">283</sup> א' ופסח ה' על הפתח דוקא כנ\"ל דבכאן מפרש להיכן הי' דילוג<sup data-n=\"4391\">284</sup> כו'. והנה תחלה י\"ל בשרש ענין הנ\"ל בפתח העליון שמשמש כניסה ויציאה מהעלאת מ\"נ והמשכת מ\"ד דמטעם זה צריך למשקוף וב' מזוזות להיות הוראה על מקום הפתח שבו דוקא יכנסו כולם ויצאו בו ולא במקום אחר זולתו כו'. אך הנה יש להקדים תחלה ענין א' והוא בענין הבירורים דרפ\"ח ניצוצים<sup data-n=\"4392\">285</sup> שהן באים בהתחדשות בכל יום והכל ע\"י בחי' המל' דוקא כנ\"ל, להיות שאנו רואים דכל<sup data-n=\"4393\">286</sup> דבר פלא והפלא במה שהנשמות בגעה\"ע והתחתון תמיד נהנין מזין השכינה<sup data-n=\"4394\">287</sup> שהוא בחי' דבור<sup data-n=\"4395\">288</sup> אור התענוג והמתיקות ועריבות בהשגת סודות התורה ברזין דאוריי' הנפלאי' בכל יום, בהתחדשות חידושים גדולים באור חדש בהשגות חדשות דוקא כמובן בזהר פ' שלח<sup data-n=\"4396\">289</sup> בחידושי אור תורה ברזין דאוריי' ומתיקות התורה דרב מתיבתא שדרש בכל יום, ומשמע שם דבכל לילה ולילה מחדשים שם חידושים נפלאים ברזין דאוריי', ויש בזה עליות באור חדש לחדש רזין ומתיקות התורה מדי יום ובכל שבת וחדש <span data-k=\"pg\">קלא</span> ּ שילכו מחיל אל",[["4386","279","<b>נודעת</b>: ד: ניתנה."],["4387","280","<b>בב'</b>: אבדהז: בג'."],["4388","281","<b>ופסח. . דילוג בשה\"ש</b>: ראה בריש המאמר."],["4389","282","<b>(ולבד. . כפשוטו)</b>: ב: לבד. ד: (לבד.. ב: כפשוטו."],["4390","283","<b>על כל בתי בנ\"י</b>: בד: ע\"כ."],["4391","284","<b>הי' דילוג</b>: ב: דילוגו. ד: דילוג."],["4392","285","<b>דרפ\"ח ניצוצים</b>: נסמן לעיל פ' שמות לו, ג."],["4393","286","<b>דכל</b>: בד: ליתא."],["4394","287","<b>שהנשמות. . נהנין מזיו השכינה</b>: ראה ברכות יז, א."],["4395","288","<b>בחי' דבור</b>: בד: בריבוי."],["4396","289","<b>בזהר פ' שלח</b>: ראה שם קסב, א ואילך. ראה גם לעיל פ' שמות כב, ג. וארא נ, ג. מאמרי אדה\"א בראשית ע' תמט."]]],[2300540610,"חיל<sup data-n=\"4397\">290</sup> כו' עד אין שיעור, כמו התנאים ואמוראים שלומדים בג\"ע סודות ופנימי' התושבע\"פ בחידושים גדולים תמיד, וכעובדא דרב\"נ<sup data-n=\"4398\">291</sup> בבהרת שקד[ם] לשער לבן קוב\"ה אומר טהור כו', וגם כל הנשמות הגבוהים ביותר כנשמת משה ואהרן ו[ה]אבות וכל הנשמות שמאדה\"ר עד הנשמות שבדורות האחרונים כולם הם מחדשים חידושי השגות עמוקות ביחו\"ע וברזין דאוריי' שמתחדשי' ממקור הח\"ע בעילוי אחר עילוי עד אין שיעור ממש, הרבה יותר ממה שהיו משיגים בעודם בעוה\"ז מאחר שזהו שכרם מזה שעסקו בתומ\"צ<sup data-n=\"4399\">292</sup> בעוה\"ז כו' כמו שמכריזין בג\"ע אשרי מי שבא לכאן<sup data-n=\"4400\">293</sup> ותלמודו בידו דוקא שעי\"ז דוקא משיג יותר בנסתרות שבתורה כו' וא' בזהר דבכל חצות לילה קוב\"ה אתי לאשתעשע<sup data-n=\"4401\">294</sup> עם צדיקייא בג\"ע בעסק סודות התורה [שלומדי' שם וכמ\"ש השמיעני את קולך<sup data-n=\"4402\">295</sup> כו'), וא\"כ יש להפליא מאד מאין נמצא למעלה עוצם ריבוי ההתחדשו' הזאת בסודו' התור'] זה כמה אלפים שנה מזמן אדה\"ר עד זמן ימוהמ\"ש ועוה\"ב כו' וד\"ל.\n<b>אך</b> הענין הוא כידוע דג\"ע הוא בחי' מקבל מבחי' עדן עילאה<sup data-n=\"4403\">296</sup> סתימאה<sup data-n=\"4404\">297</sup> שעליו א' עין לא ראתה<sup data-n=\"4405\">298</sup> כו' שיתגלה בעוה\"ב דוקא, ועכשיו גם הנשמות הגבוהות ביותר כמשה ואבות לא השיגוהו לתכלית[ו] ממש ואמנם גילוי אורו מאיר בגעה\"ע לנשמות הצדיקי' שמימות אדה\"ר עד העוה\"ב, ובזה האור הן עליי' העולמות<sup data-n=\"4406\">299</sup> התחדשות ההשגות בעומק סודות ופנימי' התורה בכל יום ויום (וכמאמר וקדושים בכ\"י<sup data-n=\"4407\">300</sup> יהללוך סלה בלי שיעור והפסק כלל כו') (והוא [בחי'] התענוג הפשוט הנעלם שבהעלם עצמות א\"ס ב\"ה שנק' שעשוע[י] המלך בעצמו'<sup data-n=\"4408\">301</sup> ממש, שיתגלה מהעלמו העצמי בעוה\"ב כמ\"ש יחיינו מיומים בג\"ע בגילוי רזין וסודות התורה וכן בימוהמ\"ש וביום הג'<sup data-n=\"4409\">302</sup> יקימנו ונחי' לפניו ממש, וכמ\"ש אשר אהי' אנא זמין לאתגלאה בעוה\"ב דכתי' וא' ביום ההוא<sup data-n=\"4410\">303</sup> הנה אלקינו זה כו' וז\"ש אלקים זולתך יעשה למחכה לו<sup data-n=\"4411\">304</sup> כו'). וזהו [ענין] ריבוי עוצם ההתחדשו' רזי<sup data-n=\"4412\">305</sup> דרזין וסודות התורה לנשמות בג\"ע בכל יום שנובע מעדן העליון [הזה] ע\"י הנהר שיוצא מעדן סתימאה וזהו<sup data-n=\"4413\">307</sup> להשקות את הגן<sup data-n=\"4414\">306</sup> ג\"ן סדרים דאוריי'<sup data-n=\"4415\">308</sup>. אך הנה סיבת ההמשכה הזאת בחידוש [ה]אור תמיד מהעלם העצמו' העדן הנ\"ל אינו בא רק ע\"י העלאות הבירורים דרפ\"ח ניצוצי' דבחי' התהו שקדם לבחי' התיקון<sup data-n=\"4416\">309</sup> דוקא [ש]ז\"ש ורוח אלקים מרחפת<sup data-n=\"4417\">310</sup>, להיות שידוע שיתרון האור הבא מן ההעלם דעצמו' א\"ס לגילוי אור להוסיף",[["4397","290","<b>שילכו מחיל אל חיל</b>: תהלים פד, ח."],["4398","291","<b>וכעובדא דרב\"נ</b>: ב\"מ פו, א. ראה (ד\"ה זה ב)מאמרי אדה\"א ויקרא ח\"ב ע' תמג וע' תנו."],["4399","292","<b>בתומ\"צ</b>: בד: בתור'."],["4400","293","<b>אשרי מי שבא לכאן</b>: ראה גם לעיל ה, א. וש\"נ."],["4401","294","<b>דבכל חצות. . לאשתעשע</b>: ראה זהר לך עז, א."],["4402","295","<b>השמיעיני את קולך</b>: שה\"ש ב, יד."],["4403","296","<b>דג\"ע. . מקבל. . מבחי' עדן עילאה</b>: ראה גם ביאוה\"ז (אד\"ז) קכז, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670264\" data-slug=\"torat-chaim\" data-id=\"2300670264\">תו\"ח נח סב, ג</a>."],["4404","297","<b>עדן עילאה סתימאה</b>: ראה גם הנסמן לעיל ה, ג הערה 250."],["4405","298","<b>עדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["4406","299","<b>עליי' העולמות</b>: ב: עולים בעליו'. ד: עולים בעילוי."],["4407","300","<b>וקדושים בכ\"י</b>: נוסח תפלת העמידה. עירובין נד, א."],["4408","301","<b>שעשוע[י] המלך בעצמו'</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. וש\"נ. קונטרסים ע' שמה. וש\"נ."],["4409","302","<b>יחיינו מיומים. . וביום הג'</b>: הושע ו, ב."],["4410","303","<b>וא' ביום ההוא</b>: ישעי' כה, ט."],["4411","304","<b>אלקים. . למחכה לו</b>: (המשך הכתוב עין לא ראתה) ישעי' סד, ג."],["4412","305","<b>רזי</b>: בד: ליתא."],["4413","307","<b>וזהו</b>: בד: זה."],["4414","306","<b>הנהר שיוצא מעדן. . להשקות את </b>[בד: ליתא]<b> הגן</b>: בראשית ב, י."],["4415","308","<b>ג\"ן סדרים דאוריי'</b>: נסמן לעיל ה, א."],["4416","309","<b>התהו שקדם לבחי' התיקון</b>: נסמן לעיל פ' שמות לט, ג."],["4417","310","<b>ורוח אלקים מרחפת</b>: בראשית א, ב."]]],[2300540624,"אור באור דח\"ע דתורה [ה]פנימי' הרי זה בא מחמת התהפכות חשוכא לנהורא<sup data-n=\"4418\">311</sup> ומריר[ו] למיתקא למטה דוקא, מפני שעי\"ז נהפוך<sup data-n=\"4419\">312</sup> בחי' חשך סתרו שהוא בחי' העלם דעצמו' שנק' סדכ\"ס לידי גילוי ביתרון גדול לאין שיעור למעלה מעלה כו' (וכידוע<sup data-n=\"4420\">313</sup> שזהו עיקר ענין כל התומ\"צ לברר [ל]רפ\"ח כו' שנפלו בעה\"ד טו\"ר כו' וע\"כ מכריזין בג\"ע אשרי מי שבא לכאן ותלמודו בידו שלמד בעוה\"ז דוקא כמ\"ש היום לעשותם<sup data-n=\"4421\">314</sup> ולמחר לקבל שכרם, שמזה דוקא יבא גילוי אור דעדן הנעלם דוקא כידוע. ולהיות שבחי' הבירורים דרפ\"ח מתחדשים בכל יום ויום ממש מניצוצי דקדושה שנפלו למטה בשינויי אופנים שונים ואין יום א' דומה לחבירו<sup data-n=\"4422\">315</sup> כלל, ע\"כ מזה יבא בחי' ריבוי חידושים והמשכות אור<sup data-n=\"4423\">316</sup> בגילוי אור התענוג דעדן הנעלם [העליון הנ\"ל] בג\"ע לנשמות בכל יום ויום [באור חדש בהשג' נסתרות ורזין דאוריי' שנובע מעד\"ן כו', מאחר שהעלאו' הברורים דרפ\"ח כו' מתחדש בכל יום ויום] שאין בירורי' דיום העבר דומה לבירורי' דיום שלאחריו בשינוי אופני <span data-k=\"pg\">264</span> ּ התכללות ז\"מ דתהו מחג\"ת כו' כמ\"ש במ\"א ע\"פ החלצו מאתכם אנשים<sup data-n=\"4424\">317</sup> כו' דבחי' ו\"ק דז\"א יורדים בכל יום אור [א'] לברר לק\"נ דבי\"ע, וע\"י העלאות הבירורים נמשך מוחין חדשים בכל יום ויום לזו\"נ שהוא בחי' מ\"ה וב\"ן<sup data-n=\"4425\">*318</sup> וכן בלילה שהמל' מבררת כו' וכמ\"ש ותקם בעוד לילה ותתן טרף שעולה רפ\"ח עם הכולל, כי בכל יום עולה בירור חדש מניצוצים חדשים דבחי' התהו שלא נתבררו עדיין מעולם (וגם במלאכים עליונים דבי\"ע מתחדשים בכל יום בהעלאות ובירורי' חדשים כמו מלאכים שנק' חציר כמ\"ש בזהר [ע\"פ מצמיח חצי\"ר לבהמה<sup data-n=\"4426\">318</sup> שהוא שם ב\"ן דשתת לון בגמיע' חדא כו' והיינו יוצר משרתי'<sup data-n=\"4427\">319</sup> כו', וכך גם] בהעלאות של מלאכים דמרכבה פני ארי' פני שור שמתבטלים מיש לאין בשיר שלהם באופן חדש בכל יום [ויום], וכן גם השרפים ואופנים שאומרים קדוש וברוך<sup data-n=\"4428\">320</sup> בכל יום באופן חדש, וכן עליות הנשמות כו'). ולכך יבא ג\"כ המשכת מ\"ד מלמעלה למטה בתוס' אור חדש בכל יום ויום והיינו סיבת ריבוי גילוי אור חדש דעונג העליון שבאה<sup data-n=\"4429\">321</sup> לנשמות בג\"ע בכל יום ולילה [כנ\"ל] וד\"ל.\n<b>ויובן</b> [כל] זה עד\"מ בנפש האדם למטה מן המאכלים שהאדם אוכל בכל יום שמזה מתח[ז]ק כחות חיות אברי גופו שהוא דמיון ומשל לבחי' הבירורים הנ\"ל, דהנה אנו רואים בחוש",[["4418","311","<b>התהפכות חשוכא לנהורא</b>: ראה זהר בהקדמה (ד, א)."],["4419","312","<b>למיתקא. . נהפוך</b>: בד: כו'. . יהופך."],["4420","313","<b>(וכידוע</b>: בד: ליתא."],["4421","314","<b>היום לעשותם</b>: נסמן לעיל ו, ד."],["4422","315","<b>ואין יום א' דומה לחבירו</b>: כ\"ה בכ\"מ. ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"ב. מאמרי אדה\"א דברים ח\"ג ע' א'קא. הנחות תקע\"ז ע' ק. וש\"נ. לקמן פ' בשלח ריב, ב."],["4423","316","<b>חידושים והמשכות אור</b>: ב: חידושי אור ההמשכו'. ד: חידושים אור והמשכות."],["4424","317","<b>החלצו מאתכם אנשים</b>: מטות לא, ג. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרצב-ד. תקס\"ד ע' כה. לקמן קכז, ד והערה 715. פ' ויקהל תלד, א."],["4425","*318","<b>לזו\"נ. . מ\"ה וב\"ן</b>: ראה גם לקמן פ' בשלח קס, ד."],["4426","318","<b>מצמיח חצי\"ר לבהמה</b>: תהלים קד, יד. ראה זהר בראשית יח, ב. סידור שחרית סב, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב. דברים ח\"א ע' רמג."],["4427","319","<b>יוצר משרתי'</b>: ברכת יוצר. ראה גם מאמרי אדה\"א בראשית ע' קכו. וש\"נ. הנחות תקע\"ז ע' לג."],["4428","320","<b>השרפים ואופנים שאומרים קדוש וברוך</b>: ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["4429","321","<b>שבאה</b>: בד: שבעדן."]]],[2300540638,"בכל המאכלים<sup data-n=\"4430\">322</sup> אשר יאכל האדם בכל יום יש בו חיות חדש<sup data-n=\"4431\">323</sup> אור וחיות הנפש בכלל ובפרט שלא הי' כמוהו מן המאכל שאכל ביום שעבר. ויובן [זה] מפרטי המאכלים שאוכל שיחזקו כחות הגוף בכלל ובפרט בכל יום, שהרי ידוע שעל הלחם יחי' האדם<sup data-n=\"4432\">324</sup> בכלל ובפרט דהיינו שיחזק הלחם ויוסיף אור חדש גם לאור השכל הרוחני' שבכלי המוח ובלא לחם יחלש אור השכל, וכן הלחם יסעד הלב בתוס' אור וחיות חדש עד שיחזק גם לאברים החיצוני' כמו כח ההילוך שברגל וכה\"ג. ובודאי יש שינוי אופנים רבים באופן אור חידוש החיות בשכל שבמוח ובמדות שבלב והדם שבאברים, לפי אופן עיכול מאכל הלחם שנעשה דם ועולה ללב ומוח לפי מה שהוא בהרכבת [ד\"י] שבלחם ומאכל זה, עד שמחמת זה ישתנה אופן חיות אור השכל והלב לטו\"ר ובכמה אופנים שונים שלפעמים ישכיל לטוב לחשוב טוב ולא רע ולהיפוך כו', וכן במדות שבלב [ל]טו\"ר ואם בגסות או שפלות רחמנות ואכזריות לפי שכל המזיגות<sup data-n=\"4433\">325</sup> מעורב מעה\"ד טו\"ר. וגם בחי' הטוב יש בו כמה מיני מדרגות ואופנים שונים משתנים לפי אופן העלאות ובירור [חיות] הרוחני' שבמאכל לחזק המוח והלב כו', להיות שנפל במאכלים מבחי' התהו שקדם לתיקון דנפש אדם ע\"כ יש בהם כח לחזק לשכל ומדות וכל האברים דאדם כידוע ומבואר במ\"א<sup data-n=\"4434\">326</sup> ע\"פ כי לא על הלחם<sup data-n=\"4435\">327</sup> כו' כי על כל מוצא פי ה' שבמאכל כו'. וראי' לזה משינוי אופנים בחיזוק כחות הגוף בין מאכל למאכל, דודאי אין דומה כח החיזוק מן מאכל הלחם למאכל בשר ודגים<sup data-n=\"4436\">328</sup> שהבשר מחזק המוח כמ\"ש ר\"נ עד דלא אכילנא בישרא<sup data-n=\"4437\">329</sup> כו', אבל הבשר מחזק הדם שבבשר ומוסיף כח וחיות בדם הוא הנפש (ש[ב]בחי' מוח בינה<sup data-n=\"4438\">330</sup> חם ויבש<sup data-n=\"4439\">331</sup> ) והלחם במוח החכ'<sup data-n=\"4440\">332</sup> כמ\"ש במ\"א. וכן יש שינוי אופני הוספות [ה]כח וחיות באדם בגופ[י] מאכלים פרטים שאוכל שיש מאכל שמזגו וטבעו להוסיף בחי' חיות<sup data-n=\"4441\">333</sup> חדש באור התענוג שבנפש כמו כל [מיני] חלב ודבש וכל שמנים שמרבים החלב ולא דם, וכך יש שינוי אופנים [חלוקים] בטעמים הפרטים<sup data-n=\"4442\">334</sup> הטובים כתפוח <span data-k=\"pg\">קלב</span> ּ ואתרוג וכה\"ג שטעם התפוח מכו[י]ן רעותא<sup data-n=\"4443\">335</sup> כו' וטעם האתרוג באופן אחר ו[טעם] השקדים מוסיף אור וחיות באופן אחר. ו[גם] עד\"ז יש שינוי אופנים חידוש האור וחיות במדות שבלב מכל חילוקי מדריגות [ד]מאכלים ופירות ותבואות הארץ לפי אופן הרכבתם וטבעם (ולזאת ימצא שינוי בטבעי בנ\"א וגם בבהמות וחיות בכל א[קלים] לפי אופן מאכלם ומזונם מן גידול",[["4430","322","<b>המאכלים</b>: בד: מאכל."],["4431","323","<b>חיות חדש</b>: בד: חידוש."],["4432","324","<b>שעל הלחם יחי' האדם</b>: נסמן בהערה 327."],["4433","325","<b>שכל המזיגות</b>: בד: המזונות."],["4434","326","<b>במ\"א</b>: ד: בזוהר."],["4435","327","<b>כי לא על הלחם</b>: עקב ח, ג. ראה גם לעיל פ' וארא נה, ב. וש\"נ."],["4436","328","<b>ודגים</b>: ב: [כתב תחילה דגים ומחקן ותיקן] דגם. ד: כי גם."],["4437","329","<b>עד דלא אכילנא בישרא</b>: ראה בב\"ק עב, רע\"א. ראה מאמרי אדה\"א במדבר ח\"ב ע' שיט. ע' תעו וע' תפא. ח\"ג ע' ריט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680321\" data-slug=\"torat-chaim\" data-id=\"2300680321\">תו\"ח וישלח קפה, סע\"ד</a>."],["4438","330","<b>בדם. . בינה</b>: ראה פרדס (שעה\"כ) שכ\"ג, מערכת דם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380071\" data-slug=\"likkutei-torah\" data-id=\"4001380071\">לקו\"ת פקודי ז, ד</a>."],["4439","331","<b>מוח בינה חם ויבש</b>: נסמן לעיל פ' שמות כז, ג."],["4440","332","<b>והלחם במוח החכ'</b>: בסידור שער בהמ\"ז קז, ד: כמ\"ש הע\"ח דלחם בגי' מזלא [נסמן לקמן קי, ד]. וראה לקמן צה, סע\"ב ואילך. קכ, ג."],["4441","333","<b>בחי' וחיות</b>: בד: כח וחיות."],["4442","334","<b>הפרטים</b>: בד: הפירות."],["4443","335","<b>התפוח מכו[י]ן רעותא</b>: זהר שמיני מ, א."]]],[2300540650,"הצומח שבו, יש אנשים במדות טו\"ר ואנשים חכמים בטו\"ר כידוע). ומזה יובן ג\"כ בסיבת שינוי האור וחיות הניתוסף מחדש מן המאכלים בכלל גם במין מאכל א' מלחם או בשר וכה\"ג מיום א' לחבירו, שבכל יום ויום יש חידוש החיות מחדש מן הנפש בגוף ממה שאכל היום דוקא מה שלא הי' עדיין כמוהו, כי מה שאכל לחם ובשר ופירות אתמול כבר נתעכל ונעשה דם וחיות אתמול וחלף והלך לו רק רשו[מו] נשאר בדם הוא הנפש, ועתה ביום הזה שאוכל מאכלים אחרים ומתעכלים ונעשים חיות חדש לחזק כחות הגוף הרי זה אור חדש ממש שלא הי' כמוהו בכל הימים זולת היום<sup data-n=\"4444\">336</sup> שהוא בודאי [ב]אופן חדש ממש, אעפ\"י שהמאכל הזה שאוכל [היום] הוא מאותו מין הלחם שאכל אתמול הרי ביום הזה הוא מוסיף אור וחיות חדש בשכל ולב באופן אחר ו[ב]יום הבא אחריו באופן אחר [אע\"פ שאוכל מאותו הלחם ומאכל יוסיף אור וחיו' חדש באופן אחר], וכן עד\"ז בכל הימים לפי שהלחם שאכל עכשיו אינו אותו הלחם [ממש] שאכל אתמול והעיכול שלו ע\"י כלי הגוף באופן חדש עד שהוא בעצמו בבחי'<sup data-n=\"4445\">337</sup> חדשה ממש [באופן חדש] שלא הי' כזה עדיין, כמו שרואה אדם בעצמו חידוש חיות[ו] בכל יום בשכל ומדות וכחות כל גופו באופן חדש [בכל יום אע\"פ שאוכל מין מאכל א' בכל יום כו', לפי שבהכרח ישתנה המשכו' חיו' חדש בנפש לגוף ויהי' שינוי' בנפשו וכוחות' מצד שינויי גופי המאכלי' שהן חדשים בכל יום] אע\"פ שהן [מ]מין א', שממילא ישתנה הכח וחיות הרוחני' הנמשך ע\"י מחיות הנפש בגוף מיום לחבירו אחר שהמאכל[י'] שאוכל[י'] מתחדשים בכל יום וכמו השינוי שבין מין מאכל לחבירו כנ\"ל וד\"ל. וא\"כ הרי [מ]ובן מזה ג\"כ ע\"פ כל הנ\"ל בשינוי אור וחיות חדש מן המאכלים בכל יום שממילא הרי גם בחי' הבירורים דרפ\"ח כו' שהוא בחי' הטוב דקדושה שבמאכלים שעשה חיזוק בנה\"ט במוח ולב [הוא] שבא ועולה הכח החדש<sup data-n=\"4446\">338</sup> ההוא שבדם ובשר להיות [ב]בחי' ביטול לאלקו' בכל כחות הטבע בלב בשר ומוח גשמי, כמו במס\"נ דק\"ש בכל לבבך בשני יצריך<sup data-n=\"4447\">339</sup>, ובודאי יש חיות<sup data-n=\"4448\">340</sup> אור וחיות חדש באור כלי השגתו באחדות ה' בק\"ש היום מכח המאכל שאכל אתמול, וכן התפעלות אוי\"ר בלב מחודשים ממש במדרגה בפרט אשר לא הי' כמוהו אתמול<sup data-n=\"4449\">341</sup> בק\"ש דאתמול, דגם שההתבוננו' ביחו\"ע ויחו\"ת<sup data-n=\"4450\">342</sup> בק\"ש אחת היא, מ\"מ יש בה שינוי אור אופן חדש בכל יום מפני חידוש הכח של השכל ומדות בכל יום [מן] המאכלים שמתחדשים בכל יום שאין א' דומה לחבירו כנ\"ל. ונמצא שיש בירור חדש בהעלאת הטוב דניצוצי' שנפלו בשבה\"כ בגוף ונפש האדם בכל יום מה שלא הי' כמוהו יום אתמול. וזהו ימי שנותינו",[["4444","336","<b>היום</b>: ב: כנראה מחק תיבה זו."],["4445","337","<b>בבחי'</b>: בד: כברי'."],["4446","338","<b>החדש</b>: בד: ליתא."],["4447","339","<b>בכל לבבך בשני יצריך</b>: נסמן לעיל פ' וארא סה, ג."],["4448","340","<b>חיות</b>: בד: חידוש."],["4449","341","<b>אתמול</b>: בד: ליתא."],["4450","342","<b>ביחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."]]],[2300540662,"בה\"ם<sup data-n=\"4451\">343</sup> ע' שנה במספר הצריך לברר מעה\"ד טו\"ר כו' וכתי' ימים יוצר\"ו<sup data-n=\"4452\">344</sup>, וכן בכל יום יש שינוי אור המשכות גילוי אלקו' בנפש האדם בתומ\"צ ותפלה בכל יום ויום מלמעלה למטה באור וכח חדש שלא הי' כמוהו ביום אתמול כמ\"ש חדשים לבקרי\"ם<sup data-n=\"4453\">345</sup> [דוקא] רבה אמונתיך, לבקרי\"ם בכל בקר ובקר דוקא מתחדש כח [ה]אור האלקי מלמעלה שהוא חיזוק האמונה בהוי' אלקי' ובמהו\"ע ממש שז\"ש רבה אמונתי\"ך ממש, והיינו לפי אופן שינוי ההעלאות בכל יום מן הבירורי' דמאכלים וכה\"ג כנ\"ל וד\"ל.\n[ח] <b>והנה</b> [ה]דוגמא מכ\"ז יובן ג\"כ למעלה בבחי' העלאת מ\"ן דמלאכים ונשמות דבי\"ע בכלל שבא מבחי' הבירורי' דרפ\"ח <span data-k=\"pg\">266</span> ּ ניצוצי' דבחי' התהו שנפל בק\"נ שבכל עולם ועולם בבי\"ע (שזהו כמו [דמיון] המאכלים שנהפך לחיות חדש בכל יום ויום כנ\"ל), וכמו מלאכים שנק' חציר שעולי' ונכללי' למעלה שנק' מאכל בהמה ויש שהן בבחי' מאכל אדם כו' וכולם מתחברים<sup data-n=\"4454\">346</sup> ע\"י שם ב\"ן דאצי' שיורד למטה בכל לילה לברר ולהעלות וכמ\"ש ותקם בעוד לילה ותתן טרף לביתה כו' [כנ\"ל]. וזהו ענין חידוש האור והכח וחיות האלקי' בתוס' אור חדש במוחין ומדות דאדה\"ע בכל יום ולילה למעלה ע\"י חידושי העלאות ובירורי' דרפ\"ח כו' בכל יום מה שלא הי' כמוהו ביום אתמול כלל, [ו]כנ\"ל בחיזוק השכל ומדות באופן חדש בכל יום, כמו השינויים בפרטי מיני מאכלים שאין א' דומה לחבירו כלל, כך אין בירורי' והעלאות העליונים דיום זה דומה ליום שעבר כו'. וז\"ש חדשים לבקרים דוקא רבה אמונתי\"ך בבחי' ריבוי ותוס' אור וחיות אלקי חדש שלא הי' כמוהו עדיין (וכן ברן יחד כוכבי בקר ויריעו<sup data-n=\"4455\">347</sup> כו' שהשיר של המלאכים [ג\"כ] מתחדשים בכל יום ויום). וראי' לכ\"ז בד\"כ יובן מן הקרבנות שבבהמ\"ק בכל יום בתמיד של שחר ובתמיד של בין הערבים דכתי' את קרבני לחמי<sup data-n=\"4456\">348</sup> לאשי ריח ניחוחי כו' שנק' [לחם] האלקי ממש וכמ\"ש האכל יאכל<sup data-n=\"4457\">349</sup> כו' אכילת מזבח ואכילת אדה\"ע כו'. ואע\"פ שאין לו גוף<sup data-n=\"4458\">350</sup> ולא כו' דברה תורה כלשון בנ\"א<sup data-n=\"4459\">351</sup>, וא' בזהר דג' שליטין הן לעילא<sup data-n=\"4460\">352</sup> מוחא ולבא וכבדא כו', וקרבן התמיד העולה לה' ע\"ג המזבח שיורד אש של מעלה<sup data-n=\"4461\">353</sup> לאכול אותו כו' נק' לחמי לאשי כו' ריח ניחוח לה' ממש להוסיף אור וחיות חדש ממקורא דכולא<sup data-n=\"4462\">354</sup> שהוא מבחי' העלם העצמו' להיות מוחין חדשים להיות<sup data-n=\"4463\">355</sup> שעי\"ז נמשך המשכת מ\"ד דחסדי' משם הוי' דאצי' לבי\"ע עד שגם חיצוני' העולמות מקבלים שפע האלקי' מן הקרבנות, והוא מתמיד של שחר ותמיד של בה\"ע שמתחדשים בכל יום ויום דוקא כמו עד\"מ הנ\"ל במאכלים שאדם אוכל בכל",[["4451","343","<b>ימי שנותינו בה\"ם</b>: תהלים צ, י. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקנו."],["4452","344","<b>ימים יוצר\"ו</b>: תהלים קלט, טז. ראה גם לקמן פ' משפטים ש, ד."],["4453","345","<b>חדשים לבקרי\"ם</b>: איכה ג, כג. ראה גם לעיל פ' וארא עג, א. לקמן פ' ויקהל שצה, א. תיא, ד. תלו, ג. מאמרי אדה\"א בראשית ע' קה. וש\"נ. הנחות תקע\"ז ע' יד. וש\"נ."],["4454","346","<b>מתחברי'</b>: בד: מתבררי'."],["4455","347","<b>ברן יחד. . ויריעו</b>: איוב לח, ז. ראה גם לעיל פ' וארא סא, א. וש\"נ. ש\"א כט, א. כה, א. וש\"נ."],["4456","348","<b>את קרבני לחמי</b>: פינחס כח, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380631\" data-slug=\"likkutei-torah\" data-id=\"4001380631\">לקו\"ת פינחס עז, ד</a>. מאמרי אדה\"א דברים ח\"ג ע' תתקכב. במדבר ח\"ג ע' תתקכב ואילך."],["4457","349","<b>האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קסג."],["4458","350","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל."],["4459","351","<b>דברה תורה בלשון בנ\"א</b>: ברכות לא, ב. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670114\" data-slug=\"torat-chaim\" data-id=\"2300670114\">תו\"ח וירא צח, ב</a>."],["4460","352","<b>דג' שליטין הן לעילא</b>: ראה זהר תרומה קנג, א. (מדהנ\"ע) תולדות קלח, א. ז\"ח רות פ, א."],["4461","353","<b>שיורד אש של מעלה</b>: ראה תו\"כ ויקרא א, ז. עירובין סג, א."],["4462","354","<b>ממקורא דכולא</b>: זהר בראשית לג, א."],["4463","355","<b>להיות</b>: ב: להוי'."]]],[2300540674,"יום כו', ובעלות התמיד בבוקר זהו בחי' בירור והעלאה חדשה כמו מאכל חדש וממילא עי\"ז נעשה כח וחיזוק למעלה בתוס' אור חדש מצד יתרון האור מן החשך דשרש הרפ\"ח כו' שנפל במאכל שהוא מבחי' התהו גבוה מבחי' אדם דתיקון ע\"כ נעשה לריח ניחוח להוי' דתיקון כמו באדם למטה כו', מאחר שנק' בחי'<sup data-n=\"4464\">356</sup> אכילת אדם זהו כמו מאכל אדם למטה דאע\"פ שאוכל מין מאכל א' בכל יום הרי אינו אותו הלחם ממש שאכל אתמול כנ\"ל ונעשה ממנו חיות ואור חדש באופן חדש בשכל ומדות כו'. וכך הוא בקרבן תמיד של שחר ושל בה\"ע שנק' לחמי לאשי כו' אע\"פ שהוא מאכל א' בכל יום ויום כבש א' בבוקר וכבש ב' בערב הרי מתחדש מהם [ה]העלאות והבירור בכל יום באופן חדש למעלה ונמשך עליהם<sup data-n=\"4465\">357</sup> המשכת גילוי אלקות מלמעלה למטה גם בהיכל ק\"ק ובכל העולמות מחדש באור חדש ממש שלא הי' כמוהו וכדוגמתו כלל בכל הימים, וכן בהמשכת מ\"ד בעולמות העליונים גם לנשמות בגעה\"ע נמשך אור חדש ממש כו' לפי שבכל יום ויום מתבררים ע\"י קרבנות התמיד ניצוצי' חדשים מרפ\"ח ניצוצי' דתהו כו' שלא נתברר עדיין מעולם כנ\"ל במאכלים דאדם בכל יום ויום. וכך הוא גם עכשיו בתפלת ישראל בכל יום שנגד תמידים<sup data-n=\"4466\">358</sup> תקנום כידוע שבכל יום מתחדשי' העלאות שלהם בוקר וערב [כ]תמידי' ממש מניצוצי' דתהו שבגופים שלהם במס\"נ בק\"ש וש\"ע ומתחדש בכל יום ויום עי\"ז בחי' המשכת גילוי אלקות מלמעלה למטה שנק' המשכת מ\"ד בתומ\"צ שלהם כמו בד\"א של הלכה שהוא במקום היכל ק\"ק<sup data-n=\"4467\">359</sup> וכה\"ג וד\"ל.\n<span data-k=\"pg\">קלג</span> ּ<b>ואחר</b> כ\"ז יובן ענין הנ\"ל בטעם עוצם ריבוי המשכות התחדשות ההשגות העמוקות בפנימי' ורזין דאוריי' לנשמות בג\"ע שנהנין מזיו השכינה בתוס' אור חדש מידי יום ויום מזמן אדה\"ר עד העוה\"ב שנובע ונמשך תמיד מבחי' עד\"ן העליון הנעלם לגילוי כו' כנ\"ל, לפי שבכל יום ויום ממש יש תמיד ריבוי התחדשות העלאות הבירורים דרפ\"ח ניצוצים דתהו שקדם לבחי' התיקון דאד\"ם כמו מקרבנות [המזבח] העליון שמקריבים שם פרים וכבשים שהן מבחי' הבירורים דמלאכים שנק' בהמות כפני שור<sup data-n=\"4468\">360</sup> וכה\"ג שנק' אכילת אדה\"ע כו', וע\"י ההעלאות הללו שמתחדשים בכל יום דוקא מטעם הנ\"ל ע\"כ בכל יום יש המשכות חדשות מעדן העליון לנשמות בהשגות חדשות באלקות ובהשגת סודות ורזין דאוריי' גם לנשמות הגבוהות ביותר עד העוה\"ב שנק' מנוחה לחיי העולמים<sup data-n=\"4469\">361</sup> כו' וד\"ל (ומטעם הנ\"ל שיתרון [ה]אור מן החשך דוקא שהן רפ\"ח ניצוצים",[["4464","356","<b>בחי'</b>: בד: ליתא."],["4465","357","<b>עליהם</b>: בד: על ידם."],["4466","358","<b>בתפלת ישראל. . שנגד תמידים</b>: ברכות כו, ב."],["4467","359","<b>בד\"א של הלכה. . היכל ק\"ק</b>: ראה ברכות ח, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310058\" data-slug=\"tanya\" data-id=\"3401310058\">תניא</a> פנ\"ג. סידור שער הת\"ת צח, ד. שע\"ת קיג, א. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תעד ואילך וע' תשלה. קונטרסים ע' שסה. הנחות תקע\"ז ע' ש. לקמן פ' תרומה שיז, ב."],["4468","360","<b>כפני שור</b>: יחזקאל א, י."],["4469","361","<b>מנוחה לחיי העולמים</b>: סוף תמיד."]]],[2300540686,"שנפלו מבחי' התהו שמתבררים בכל יום שעי\"ז נתגלה בכל יום מבחי' ההעלם דעצמות כנ\"ל).\n<b>והנה</b> אחר הקדמה הזאת יובן ג\"כ שרש ענין הפסח שהוא בחי' הדילוג שממקום גבוה מאד נעלה שהוא מבחי' העלם העצמו' דא\"ס ממש [ש]זהו ופ[ס]ח הוי' [ו]דוקא על הפתח כשראה את הדם על המשקוף כו'. דהנה הטעם שבחי' המל' נק' פתח בציור משקוף וב' מזוזות דוקא לפי שע\"י בחי' המל' דוקא עולים כל הבירורי' דרפ\"ח ניצוצי' דתהו כמו מעבודת הקרבנות למעלה ולמטה כו', ומביטול היש לאין דמלאכים ונשמות דבי\"ע בהעלאות מ\"נ שלהם וכן כל בחי' המשכת מ\"ד שאחר העלאו' מ\"נ מלמעלה למטה הנ\"ל<sup data-n=\"4470\">362</sup> נמשך ע\"י המל' שנק' פתח ושער להוי' דאצי' כנ\"ל שהוא כדוגמת פתח גשמי שמשמש כניסה ויציאה כנ\"ל. והנה מבואר לעיל שבכל יום ויום ממש מתבררים בירורים חדשים בהעלאות מ\"נ דמלאכים וקרבנות וכה\"ג ועי\"ז נמשך המשכות אורות חדשים בכל יום מאצי' לבי\"ע מטעם הנ\"ל, והכל ע\"י בחי' המל' שנק' פתח האהל (כמו במשכן דמשה שכל העלאות הקרבנות הביאו אל פתח אוה\"מ דוקא והי' הפתח מכוון נגד היכל ק\"ק<sup data-n=\"4471\">363</sup> דוקא), להיות שזה הפתח<sup data-n=\"4472\">364</sup> הוא מקום [ה]מיוחד דוקא שבו עולים [כל] העלאות ויורדים בו כל המשכות עליונים (כמו הסולם שמוצב ארצה כו' שמגיע בשער השמים כו' שהוא התפלה<sup data-n=\"4473\">365</sup> [ש]מגיע לפתח ושער השמים וכמ\"ש אם ישים אליו לבו<sup data-n=\"4474\">366</sup> כו', דרוח אייתי רוח ואמשיך רוח דלפי אופן העלאות דאדם ברוחו ונשמתו כו' כן יומשך לנפשו ורוחו מלמעלה לפי [אופן] ההעלאות דוקא, אם [מ]בחי' החסדי' או מבחי' הגבורות דהיינו או בחדוה ושמחה או במרירות ושפלות כידוע, אבל אם לא יעלה רוחו ונשמתו ולבו למעלה בהעלאה [ו]תשוקה לא ימש[י]ך כלום וכמ\"ש במ\"א). וכל תפלות החול עולים למעלה בפתח ושער השמים ולא במ\"א זולתו, וכל<sup data-n=\"4475\">367</sup> בחי' המשכות אלקות ברוחני' וגשמי' בח\"י ברכות דש\"ע אינו יורד מלמעלה מאצי' לבי\"ע רק ע\"י פתח ושער הזה [ו]רק כפי אופן ההעלאות דוקא שנק' אתעדל\"ת כך יהי' אופן ההמשכה מלמעלה שנק' אתעדל\"ע כידוע. וזהו כל ענין ההעלאו' והמשכות עכשיו עד ימוהמ\"ש ועוה\"ב שנק' עליות וירידות בכלל שלפ\"ע העליות כך יהי' ערך הירידה וההמשכה, ויש בזה חילוקי מדריגות שונות כמו [ההפרש] שבין תפלת החול לתפלת השבת ובין שבת ליו\"ט וביו\"ט עצמו יש ג' מדרגות דחג\"ת פסח בחי' החסד ושבועות בבחי' הגבו' <span data-k=\"pg\">268</span> ּ וסוכות בבחי' ת\"ת<sup data-n=\"4476\">369</sup>, ויוכ\"פ למעלה גם משבת שנק' שבת שבתון<sup data-n=\"4477\">370</sup> כו' (וגם בכל יום [יש] ג' תפלות ש\"ע<sup data-n=\"4478\">*372</sup>",[["4470","362","<b>הנ\"ל</b>: בד: הכל."],["4471","363","<b>פתח אוה\"מ. . מכוון נגד היכל ק\"ק</b>: ראה פרה פ\"ג, מ\"ט ובמפרשים שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרעו וע' תרפד."],["4472","364","<b>שזה הפתח</b>: ד: שם."],["4473","365","<b>הסולם שמוצב ארצה. . התפלה</b>: נסמן לעיל פ' וארא עח, א הערה 388."],["4474","366","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["4475","367","<b>וכל</b>: בז: וכן."],["4476","369","<b>פסח בחי' החסד. . הגבו'. . ת\"ת</b>: ראה זהר (רע\"מ) פינחס רנז, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670318\" data-slug=\"torat-chaim\" data-id=\"2300670318\">תו\"ח לך פד, ד</a> ובהערה 31. לקמן פ' משפטים רפו, ד. תרומה שטו, ג."],["4477","370","<b>ויוכ\"פ. . שבת שבתון</b>: אחרי טז, לא. אמור כג, לב. ראה גם אוה\"ת ר\"ה ע' ב'תפט. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191618\" data-slug=\"likkutei-sichot\" data-id=\"1300191618\">לקו\"ש ר\"ה (כרך יט) ע' 605</a> הערה שבת שבתון. ערב יו\"כ (כרך כט) ע' 329 הערה 18."],["4478","*372","<b>ש\"ע</b>: בד: ליתא."]]],[2300540698,"[תפלת שחרית מנחה ערבית] שהן ג' מדריגות דחג\"ת בפרטיות כמו ג' מדריגות דמועדים<sup data-n=\"4479\">371</sup> בכללות), ובכולן אין האור הנמשך מלמעלה רק כפי אופן ההעלאה מלמטה דוקא, ולכך נק' המל' בשם מראה דמות כבוד הוי'<sup data-n=\"4480\">372</sup> או מחז\"ה<sup data-n=\"4481\">373</sup> ובזהר א' שנק' [אבן] ספי\"ר<sup data-n=\"4482\">374</sup> [כהאי] אבן טבא<sup data-n=\"4483\">375</sup> כו' שבה נגלה בחי' מרא\"ה כבו\"ד הוי' שבאצי' לפי אופן ההעלאה דגוונין דבי\"ע כו'.\n<b>אך</b> הנה בליל א' דפסח יש בחי' מעלה ומדרגה גבוה ביותר שלא נמצא כמוהו בכל המועדים ושבתות וגם לא ביו\"כ שהוא מעין העוה\"ב<sup data-n=\"4484\">*376</sup> כנ\"ל, והוא במה שהי' אז בחי' המשכה מעצמו' אוא\"ס ב\"ה ממש בבחי' דילוג המדריגות כמ\"ש קול דודי כו' מדלג כו' [כמו] הקופץ מאיגרא רמה כו' שזהו שכתב ופסח [ה'] כו' שלא כסדר ההשתלשלו' דע\"ס בבחי' עו\"ע [כלל] כנ\"ל באריכות, וכמ\"ש ועבר הוי' כו' ועברתי בעצמי כו' וכך נגלה עליהם מלך<sup data-n=\"4485\">376</sup> כו'. וכ\"ז מצד שהי' בהם<sup data-n=\"4486\">377</sup> בחי' דילוג הזה מצד עצמו בלי סיבת העלאת מ\"נ באתעדל\"ת כלל אלא בבחי' אתעדל\"ע<sup data-n=\"4487\">368</sup> מצד עצמותו ומהותו האמיתי לבד שאין כל העולמות<sup data-n=\"4488\">378</sup> מגיע שם כלל ולא ישיגוהו לעולם דלית מח' תפיסא בי' כלל<sup data-n=\"4489\">379</sup> להיותו למעלה גם מן הרצון ותענוג ולמעלה מן החכ' כו' וד\"ל<sup data-n=\"4490\">380</sup>, שזהו בחי' פנימי' ועצמו' דאוא\"ס שבפנימי' הכתר כו' (שיתגלה לעוה\"ב ע\"י אתעדל\"ת [ד]מעשה המצות וביצ\"מ הי' זה שלא ע\"י אתעדל\"ת כלל). אך גם שהי' אתעדל\"ע מצד עצמו לבד אמנם גם בחי' התעוררות [זו] שמצד עצמו הוצרך להיות ע\"י התראות<sup data-n=\"4491\">381</sup> הדם על המשקוף וב' המזוזות ואם לאו לא הי' בחי' הדילוג הזה שמצד עצמו, [והיינו] מטעם הנ\"ל דהי' צריך להיות אות וזכרון לבחי' התקשרות העצמי' דכנ\"י בעצמו' הרצון [ו]בחי' חו\"ג העצמיי' שזהו ציור הפתח [ב]משקוף וב' מזוזות כנ\"ל, אך פתח זה הרי עושין לכניסה ויציאה בהעלאו' והמשכות ע\"י אתעדל\"ת דוקא, אך ע\"י שראה את הדם על המשקוף וב' מזוזות דוקא הוא שהי' לאות ברית וזכרון על התקשרות העצמי' דוקא ש[י]הי' מחמת זה אתעדל\"ע שמצד עצמו בבחי' אה\"ר העצמי' שלמעלה מן הרצון וטעם כו'. וז\"ש ועבר הוי' כו' וראה את הדם על כו' אז ופסח הוי' כו' שנתעורר לבחי' דילוג זה<sup data-n=\"4492\">382</sup> שאין כל העלאות מ\"נ דמועד ושבת מגיע לשם כלל לפי",[["4479","371","<b>ג' תפלות. . דמועדים</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'מד. וש\"נ. הנחות תקע\"ז ע' ריז. לקמן פ' משפטים רפו, ד. תרומה שטו, ג."],["4480","372","<b>המל'. . מראה דמות כבוד הוי'</b>: יחזקאל א, כח. ראה זהר ויקהל רטו, א ובהגהות מהרח\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שעד."],["4481","373","<b>המל'. . מחז\"ה</b>: ראה זהר לך פח, ב (ובאוה\"ח שם. ובמק\"מ שם פט, א). צא, א (ובאוה\"ח שם). פרדס (שעה\"כ) שכ\"ג, מערכת מחזה."],["4482","374","<b>המל'. . [אבן] ספיר</b>: יחזקאל א, כו. ראה זהר נח עא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670253\" data-slug=\"torat-chaim\" data-id=\"2300670253\">תו\"ח וירא ק, ג</a>. ובהערה 42 לקמן צז, ב."],["4483","375","<b>[כהאי] אבן טבא</b>: זהר ויגש ריא, א."],["4484","*376","<b>ביו\"כ שהוא מעין העוה\"ב</b>: נסמן לעיל פ' וארא עה, ד."],["4485","376","<b>נגלה עליהם מלך</b>: הגש\"פ פיסקא מצה זו."],["4486","377","<b>בהם</b>: בד: ליתא."],["4487","368","<b>אתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' שמות מא, א."],["4488","378","<b>העולמות</b>: בד: העלא' מ\"ן."],["4489","379","<b>דלית מח' תפיסא בי' כלל</b>: ראה ת\"ז בהקדמה (יז, א)."],["4490","380","<b>וד\"ל</b>: בד: כנ\"ל."],["4491","381","<b>התראות</b>: בד: שראה את."],["4492","382","<b>זה</b>: בד: הנ\"ל."]]],[2300540710,"שנעוץ תחב\"ס דוקא, וכמו שיהי' לע\"ל שיהי' אור פנימי' הכתר במל' דוקא כו', וזהו מ\"ש<sup data-n=\"4493\">383</sup> שמזכירין יצ\"מ גם לימוהמ\"ש ועוה\"ב<sup data-n=\"4494\">384</sup> כמשי\"ת בעז\"ה וד\"ל.\n[ט ] <b>ומעתה</b> י\"ל שרש ענין המצה וד' כוסות שאומרים ההגדה עליהם כו', דהנה מבואר לעיל שבליל א' דפסח יש יתרון מעלה על כל המועדים ושבתות מטעם בחי' הדילוג שמצד עצמו' א\"ס ב\"ה שלא ע\"י אתעדל\"ת כלל. אך [הנה] היא הנותנת דבחי' דילוג זה הוא שירד ונגלה למטה מטה מאד שכל הגבוה גבוה יותר ירידתו והתלבשותו למטה יותר לפי שלא יכילנו כל האורות העליונים כמ\"ש מדלג על ההרים אף על המדות דא\"א וע\"י כנ\"ל, והיינו שדילוגו הי' למטה בסוף כל המדריגות שהוא בחי' המל' שנק' פתח האוהל כנ\"ל וכמ\"ש ופסח ה' על הפתח דוקא מטעם שנעוץ תחב\"ס דוקא ומשום שראה את הדם על המשקוף כו' כנ\"ל. <span data-k=\"pg\">קלד</span> ּ אמנם הנה מ\"מ גם לבחי' דילוג הזה הי' צ\"ל שיהי' בחי' הכלים שיכילו וילב[י]שו לאור הגדול הזה למטה דוקא שהוא בכנ\"י שהן בבחי' המל' להיות שוכן בהם מבחי' גילוי אוא\"ס עצמו שדולג ממקומו העצמי, כי בלתי כלים לא ישכון האור הגדול דעצמו' ממש [למטה ממש] כמו שהוא למעלה בעצמותו ממש כו'. והן הן מצות מצה דאורייתא שציוה ה' להם לאכול מצה בליל א' דפסח<sup data-n=\"4495\">385</sup> ומצות ד' כוסות דיין שהן מדרבנן<sup data-n=\"4496\">386</sup> דוקא (ושזהו תושב\"כ ותושבע\"פ ששרשם באו\"א<sup data-n=\"4497\">387</sup> דאצי'). וזהו שאו' בהגדה פסח שהיו אבותינו<sup data-n=\"4498\">388</sup> אוכלי' כו' ומיד או' מצה זו שאנו אוכלים כו' ד[מצות ה]מצה הוא בחי' הכלי לאור דעצמו' א\"ס [בכנ\"י] וגם ד' כוסות דיין דאפי' עני שבישראל<sup data-n=\"4499\">389</sup> חייב בהן מדרבנן כידוע וד\"ל.\n<b>ולהבין</b> טעם הדבר הנה ידוע דחו\"ג דאו\"א דאבא מקור החסדים<sup data-n=\"4500\">390</sup> בקו ימין חח\"ן ואימא מקור הגבו'<sup data-n=\"4501\">391</sup> בקו השמאל בג\"ה<sup data-n=\"4502\">392</sup> זהו שיורד ונמשך למטה במל' בבחי' הקטנות שבה, כידוע בענין ויבן ה' אלקים את הצלע כו' שבנין הנוק' הוא מחו\"ג דאו\"א שנק' הוי' אלקינו כו' וד\"ל, וזהו ענין המצה שהוא בחי' החסד דאבא שבא בבחי' הקטנות דנה\"י דאבא<sup data-n=\"4503\">393</sup> כנ\"ל<sup data-n=\"4504\">394</sup> וכמ\"ש והוכן בחסד כסא<sup data-n=\"4505\">395</sup> וכן כי אמרתי עולם חסד",[["4493","383","<b>מ\"ש</b>: בד: ליתא."],["4494","384","<b>שמזכירין יצ\"מ גם לימוהמ\"ש ועוה\"ב</b>: נסמן לקמן קיא, ד הערה 616."],["4495","385","<b>מצה בליל א' דפסח</b>: ראה רמב\"ם הל' חמץ ומצה רפ\"ו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב. שה\"א לז, ב ובהערה 15."],["4496","386","<b>ד' כוסות. . מדרבנן</b>: ראה פסחים קיז, ב. שו\"ע אדה\"ז שם סתע\"ב, ס\"ב. סי\"ד. סט\"ו. וראה הגדה שלמה (קידוש ליל פסח) ארבע כוסות ע' 90 ואילך ובהערה 25."],["4497","387","<b>תושב\"כ ותושבע\"פ ששרשם באו\"א</b>: ראה לקמן צה, ד ובהערה 436. קכח, ג. פ' בשלח קפב, ד. רטז, ד. תצוה שסז, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, סע\"ג</a> ובהערה 37."],["4498","388","<b>שהיו אבותינו</b>: בד: זה שאנו (וראה גם לקמן צו, ג. קיז, ב הערה 89) — לשון הרמב\"ם הל' חו\"מ פ\"ח, ה\"ד."],["4499","389","<b>דאפי' עני שבישראל</b>: פסחים צט, ב (במשנה). שו\"ע אדה\"ז הל' פסח סתע\"ב, ס\"ל."],["4500","390","<b>דאבא מקור החסדים</b>: ראה זהר ואתחנן רסב, סע\"א. סידור שער התפילין ט, סע\"ד ואילך. (ובשם הע\"ח ב)שעה\"י קכד, ב ובהערה 29."],["4501","391","<b>ואימא מקור הגבו'</b>: נסמן בהערה שלפנ\"ז."],["4502","392","<b>בג\"ה</b>: בד: ליתא."],["4503","393","<b>המצה. . הקטנות. . דאבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. שה\"א ח, ב ובהערה 7. לקמן קטו, ד. פ' פקודי תמח, ב. תנח, ב [ושם: בפע\"ח]."],["4504","394","<b>כנ\"ל</b>: בד: במל'."],["4505","395","<b>והוכן בחסד כסא</b>: ישעי' טז, ה. ב: כסאו [— ראה שעה\"י קמב, א ובהערה 16]. ד: כסאך [— ראה לקמן צז, א. מאמרי אדה\"ז על פרשיות התורה ח\"א מהדורת תשמ\"ט בהוספות ע' 19 ובשוה\"ג שם. מאמרי אדה\"א בראשית ע' רפו ובהערה שם]."]]],[2300540722,"יבנה. וענין הד' כוסות דיין שהוא בבחי' ד' מוחין דאימא<sup data-n=\"4506\">396</sup> שבאין למטה במל' בבחי' הקטנות דוקא, והן בחי' הכלים שבמל' להכיל אור העצמו' שבא בבחי' דילוג הנ\"ל. ואע\"פ שמבואר לעיל דגם בבחי' חו\"ג דא\"א שנק' הרים עליונים לא יוכל האור דעצמו' להתלבש שם, וכ\"ש בחו\"ג דאו\"א שהוא בחי' אור הכתר בחו\"ג<sup data-n=\"4507\">397</sup> שנק' טעם גלוי לרצון כנ\"ל, אבל דוקא במצה וד' כוסות שהן בבחי' הקטנות דחו\"ג דאו\"א הוא שיכול האור דעצמו' א\"ס להתלבש לפי שבחי' חו\"ג דאו\"א כמו שהן במקומם בבחי' גדלות המוחין לא יכילו האור הגדול הזה להיותו למעלה מן הרצון וח\"ס<sup data-n=\"4508\">398</sup> כנ\"ל ואיך יתלבש במדות דחו\"ג דרצון שבחו\"ב כו', אבל בבחי' חו\"ג דאו\"א דאצי' כמו שהן באין למטה מטה דוקא שהוא בבחי' המל' כשהיא בבחי' הקטנות (ונק' נקודה תחת יסוד<sup data-n=\"4509\">399</sup> שז\"ש הא לחמא עניא<sup data-n=\"4510\">400</sup> ) שהוא האמונה הפשוטה שלמטה מן הדעת, והוא במצה שהוא בחי' חסד דאבא בבחי' הקטנות שנק' מיכלא דמהימנותא כו' וכן ד' כוסות דקטנות דאימא שם דוקא יוכל האור דעצמו' להתלבש שם ממש, מטעם כלל הידוע בכ\"מ שכל הגבוה גבוה יותר יותר ישפיל א\"ע לשכון ולהתלבש במדרגות התחתוני' ביותר, כי לעוצם רוממותו לא יכילנו המדריגה העליונה כו' כ\"א דוקא במדריגה התחתונה ונמוכה ביותר (כמ\"ש במ\"א בענין משלי שלמה<sup data-n=\"4511\">401</sup> דמצד עומק החכ' לא יכילם<sup data-n=\"4512\">402</sup> ההשגה כ\"א בדברי משלים וחידות, וכך נק' התורה מש\"ל הקדמוני<sup data-n=\"4513\">403</sup> ולכך נתלבשה התומ\"צ בדברים גשמיי' דוקא כו') וכה\"ג<sup data-n=\"4514\">404</sup>. וכך הוא בענין מצה וד' כוסות [לפי] שהן בבחי' הקטנות דחו\"ג דאו\"א שם דוקא נתלבש אור דילוג העצמי' דא\"ס ממש שאין כל אתעדל\"ת בהעלאת מ\"נ מגיע לשם כלל בכל המועדים ושבתות כנ\"ל וד\"ל.\n<b>אך</b> הנה עדיין י\"ל בזה ב' דברים הא' למה נתלבש האור דעצמו' בבחי' דילוג הנ\"ל בבחי' חו\"ג דאו\"א דוקא ולא בבחי' חו\"ג דא\"א שנק' יד החזקה והגדולה שלמעלה מן החכ' והטעם כנ\"ל, ואם על המדות דא\"א דילג כ\"ש על <span data-k=\"pg\">270</span> ּ מדות דאו\"א, ואם הטעם כנ\"ל<sup data-n=\"4515\">405</sup> שירד בבחי' הקטנות דחו\"ג דאו\"א זהו עצמו הטעם שיכול להתלבש בקטנות דחו\"ג דנה\"י דא\"א כמ\"ש אנכי תרגלתי כו'. ולכאורה זה סותר למ\"ש ויוציאנו ה' אלקינו ביד חזקה ובזרוע נטוי' שהן בחי' [ב'] זרועו' דא\"א דוקא כו'. והב' למה נתלבש בבחי' חו\"ג דמצה וכוסות דוקא שהן מחו\"ג דחו\"ב דהיינו תושב\"כ ותושבע\"פ דמצה דאורייתא וכוסות דרבנן כו', ומה ענין חו\"ג לכאן שהן בחי' המדות שמקבלים מחו\"ב לבד ועיקר ענין הדילוג מלמעלה גם מן הרצון וחכ' כנ\"ל. אך הנה",[["4506","396","<b>הד' כוסות. . ד' מוחין דאימא</b>: פע\"ח (שחה\"מ) שכ\"א, פ\"ז."],["4507","397","<b>בחו\"ג</b>: בד: בחו\"ב."],["4508","398","<b>וח\"ס</b>: בד: וחכ'."],["4509","399","<b>המל'. . נקודה תחת יסוד</b>: נסמן לעיל פ' וארא עא, ד הערה 30."],["4510","400","<b>הא לחמא עניא</b>: נוסח ההגדה. ראה שה\"א כד, ב ובהנסמן לשם."],["4511","401","<b>בענין משלי שלמה</b>: ראה לקמן פ' בשלח קצא, א. שעה\"י קמ, ב."],["4512","402","<b>יכילם</b>: בד: יכילנו."],["4513","403","<b>נק' התורה מש\"ל הקדמוני</b>: נסמן לעיל פ' שמות ח, ב."],["4514","404","<b>כו') וכה\"ג</b>: ב: כו' וכה\"ג)."],["4515","405","<b>ואם הטעם כנ\"ל</b>: בד: והטעם הנ\"ל."]]],[2300540734,"מבואר לעיל בענין צורת הפתח דבחי' המל' שב' המזוזות הן ב' קוין דחו\"ג העצמי' שבפנימי' אור הכתר דוקא ששרשם למעלה ממדות דרצון וחכ' שהי' במ\"ת, וז\"ש בדמייך חיי דוקא כנ\"ל<sup data-n=\"4516\">406</sup> שלמעלה מא' דאדם כו' והוא במה שהי' עיקר האות בדם שעל המשקוף כו'. וזהו כללות ענין טעם הדילוג הזה בבחי' חו\"ג דקטנות דאו\"א שבמל' שהוא המצה וד' כוסות ששרשם למעלה מבחי' הגדלות המוחין דח\"ס<sup data-n=\"4517\">407</sup> דמ\"ת כנ\"ל באורך וד\"ל.\n<b>וביאור</b> הענין בחי' קטנות דחו\"ג דאו\"א במצה וד' כוסות, הנה ידוע בענין המצה בכלל שהוא בבחי' קטנות דאור חסד דאבא וז\"ש זכרתי לך חסד נעורייך דוקא, וכמו התינוק שהולך ונמשך אחר אביו בלי טעם ודעת כלל רק מפני שכל דבר נמשך לשרשו<sup data-n=\"4518\">408</sup> למקום שמשם לוקח בתולדתו שזהו רק מצד עוצם<sup data-n=\"4519\">409</sup> טבע התולדה לבד, ע\"כ הוא נמשך אחר אביו ולא אחר זולתו כלל ואינו קורא אבא לאיש אחר רק לאביו לבד, וידוע מארז\"ל דאין התינוק יודע לקרות או\"א עד שיטעום טעם דגן<sup data-n=\"4520\">410</sup> דוקא כמו שאנו רואים בתינוק בן שנה<sup data-n=\"4521\">*411</sup> שמיד שיתחיל לטעום טעם לחם יודע לקרות אבא ואימא. והנה הידיעה הזאת שיודע לקרות אבא אינו [רק] מצד טבע התולדה שנמשך אחריו ממילא כנ\"ל ואין בידיעה זו טעם ודעת ושכל שיבין וישיג שהוא אביו איך<sup data-n=\"4522\">411</sup> שהולידו, אלא רק הכרה והרגשה עצמי' [וטבעי'] שהוא מכיר את אביו לבד<sup data-n=\"4523\">412</sup> ונמשך אחריו ולא לזולתו. וזהו שנק' בחי' קטנות שלמטה מן הדעת שאינו רק קריאה שקוראו אבא בלא טעם אלא שנראה [כאילו] הוא משיג ומבין שהוא אביו, אמנם שרשו למעלה מן הדעת ושכל שמשיג אח\"כ בגדלותו איך שהוא אביו שאינו אלא דבר נוסף על העצם, שעצם הדבר הוא בחי' [ה]הכרה מצד התולדה בטבע והוא העיקר [מה] שקוראו אבא בגדלותו בשנים כמו שקוראו אבא בקטנות[ו] ממש בשוה כו', וכל עצם אינו משתנה<sup data-n=\"4524\">413</sup> וכל הרכבות שכל וטעם משתנה וחולף כו' וד\"ל. וכך הוא בכנ\"י כשהן בבחי' הקטנות קוראים לאביהם שבשמים בשם אבא כמו אבינו אב הרחמן<sup data-n=\"4525\">414</sup> כו' וכמ\"ש כי אתה אבינו כו' שהוא בלא טעם ודעת והשגה שאין משיגים כלל איך שהוא אביהם רק כתינוק שמכיר לאביו ונמשך אחריו לקוראו אבא כנ\"ל. וזהו בחי' האמונה הפשוטה העצמי' שזהו מצד בחי' התולדה בעצם כמ\"ש [כי] בנים אתם<sup data-n=\"4526\">415</sup> לה' אלקיכם וכתי' בני בכורי ישראל כו'. וז\"ש זכרתי לך חסד נעוריך דוקא לכתך אחרי במדבר כו' כידוע, ואמנם מה שלכל<sup data-n=\"4527\">416</sup> סיבת השגות<sup data-n=\"4528\">417</sup> הכרת התינוק לקרות אבא עד שיטעם טעם דגן דוקא אם זה מצד טבע התולדה לבד כנ\"ל, הענין הוא כידוע <span data-k=\"pg\">קלה</span> ּ דשרש הלחם",[["4516","406","<b>כנ\"ל</b>: בד: כו'."],["4517","407","<b>דח\"ס</b>: בד: דחכ'."],["4518","408","<b>שכל דבר נמשך לשרשו</b>: ראה גם לקמן קי, ד. קטז, ב. פ' תצוה שמז, ד. ויקהל שצד, ב. שע\"ת יז, א. מאמרי אדה\"א נ\"ך ע' תצא. וש\"נ."],["4519","409","<b>עוצם</b>: בד: ליתא."],["4520","410","<b>דאין התינוק. . דגן</b>: ראה ברכות מ, סע\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' רמה־ שמות ח\"א ע' קמג. שה\"א טו, א ואילך. לקמן קטז, א. קכ, ג. קכט, א."],["4521","*411","<b>בתינוק בן שנה</b>: ראה לקמן קכט, א."],["4522","411","<b>איך</b>: בד: ליתא."],["4523","412","<b>לבד</b>: בד: ליתא."],["4524","413","<b>וכל עצם אינו משתנה</b>: נסמן לעיל פ' וארא עח, ב."],["4525","414","<b>אבינו אב הרחמן</b>: נוסח ברכת ק\"ש שחרית."],["4526","415","<b>[כי] בנים אתם</b>: נסמן לעיל פ' וארא פה, ג."],["4527","416","<b>שלכל</b>: ב: שתלוי. ד: שתלו."],["4528","417","<b>השגות</b>: בד: ליתא."]]],[2300540746,"הוא בחכ' דוקא כמ\"ש אילן שאכל אדה\"ר<sup data-n=\"4529\">418</sup> חטה כו'<sup data-n=\"4530\">419</sup> דחטה הוא כ\"ב אתוון דחכ'<sup data-n=\"4531\">420</sup> שע\"י טעם לחם נתחזק כח הדעת וההכרה שיוכל להכיר את אביו, אע\"פ שאין זה רק מצד התולדה ולא מצד ההשגה כלל כנ\"ל שאין [ב]קריאה זו השגת שכל וטעם כלל, עכ\"ז קודם שיטעום טעם דגן רק יונק חלב אין בו עדיין מבחי' החכ' ודעת לקרות אבא בדבור אע\"פ שיכירו ונמשך אחריו וכמ\"ש במ\"א וד\"ל. ומזה יובן ג\"כ בטעם ענין המצה שנק' מיכלא דמהימנותא שהוא בבחי' הקטנות דכנ\"י באמונה פשוטה לקרות אבא לבד כנ\"ל. אך לכאורה מאמר זה דאין התינוק יודע לקרות אלא בטעמו טעם דגן הוא להיפך מענין המצה שאין בה טעם כלל וזהו עיקר המצ[ו'] שלא יהי' בה שאור הנותן טעם כו'.\n<b>הענין</b> הוא דעיקר האמונה שבמצה הרי הוא באמיתית מהו\"ע ית' שלמעלה מבחי' החכ' דמוחין דאבא כנ\"ל שלמעלה מבחי' אדם המוליד במוחין דחו\"ב בדומה לו כו' כנ\"ל. ומ\"ש [כי] בנים אתם כו' כבן הנמשך אחר אביו מצד התולדה כנ\"ל זהו בשורש תולדות נש\"י מזיווג ויחוד פנימי' דאו\"א וזו\"נ דאצי' לבד שהוא גילוי אוא\"ס שבפנימי' [או\"א כו', ואמנם עיקר שרש הראשון דנש\"י הוא שעלת' במח'<sup data-n=\"4532\">421</sup> העצמי' דעצמות אא\"ס ממש שלמעלה מבחי' אד\"ם דחו\"ב ומדו' כמ\"ש כי לא אדם הוא כו'] וכמו שיאמרו לע\"ל כי אברהם לא ידענו כו' כי אתה אבינו אתה במהו\"ע ממש אבינו כו' כנ\"ל. ואמנם ע\"י ירידת אוא\"ס<sup data-n=\"4533\">422</sup> בבחי' חסד דקטנות דכנ\"י שנק' חסד נעוריך כמו שנמשך התינוק אחר אביו בתולדה אז יעלו ויגיעו לשרשם הראשון העצמי בעצמו' אוא\"ס ב\"ה ממש להיות אתה אבינו כו'. וזהו עיקר הטעם בענין הדילוג שהי' מבחי' העצמות במל' בהתלבשות במצה דוקא שהוא בחי' קטנות דחסד דאבא [ד]אצי' במל' שהן כנ\"י ולא באור חסד ומוחין דגדלות דאבא שהוא שרש הלחם שבחכ' וגם לא במוחין ומדות דא\"א שאין זה בחי' העצמו' [ממש] כנ\"ל. וזהו שמצות מצה היא בלא הרגשת טעם שהטעם הוא במוחין דאבא, וזהו<sup data-n=\"4534\">423</sup> אין התינוק יודע לקרות אבא עד שיטעום טעם לחם דוקא, משא\"כ במצה שנק' לחם עוני<sup data-n=\"4535\">424</sup> שלמטה מן הדעת ושרשו למעלה מבחי' הדעת דאדם מטעם הנ\"ל שהאמונה הזאת הי' במהו\"ע ממש כמ\"ש כי אתה אבינו. ובזה יתורץ כל הנ\"ל במה שהי' הדילוג דעצמו' בקטנות דחו\"ג דאו\"א דוקא מפני שהן המולידים לנשמות<sup data-n=\"4536\">425</sup> בבחי' הקטנות דוקא שם שורה מבחי' העצמו' דאת\"ה אבינ\"ו כו' וד\"ל.",[["4529","418","<b>אילן שאכל אדה\"ר</b>: ברכות מ, סע\"א. ראה גם שה\"א ח, ב ובהערה 12."],["4530","419","<b>כו'</b>: בד: הי'."],["4531","420","<b>דחטה הוא כ\"ב אתוון דחכ'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפא ובהנסמן במ\"מ לשם."],["4532","421","<b>דנש\"י הוא שעלת' במח'</b>: נסמן לעיל פ' שמות לב, ב."],["4533","422","<b>אוא\"ס</b>: בד: אור אבא."],["4534","423","<b>וזהו</b>: בד: ולזה."],["4535","424","<b>במצה שנק' לחם עוני</b>: פ' ראה טז, ג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רצג. וש\"נ."],["4536","425","<b>לנשמות</b>: בד: לנש\"י."]]],[2300540758,"[י] <b>אך</b> הנה עדיין י\"ל למה נתלבש האור דעצמו' בב' דברים הללו דמצה וד' כוסות דאוריי' ודרבנן דוקא. ועוד מ\"ש ויוציאנו ביד חזקה כו' משמע דעיקר יצ\"מ הי' בחו\"ג דא\"א כו'. אך הנה ידוע דג' קשרים הן<sup data-n=\"4537\">426</sup> ישראל מתקשראין באוריי' ואוריי' בקוב\"ה בבחי' סתים וגליא כו', וכמו שישראל עלו במח' בבחי' פנימי' ועצמיות כך אוריי' סתים כו' הוא ח\"ע הקדומה שבעצמות ממש וכמ\"ש זה ספר תולדות אדם<sup data-n=\"4538\">427</sup> וכתי'<sup data-n=\"4539\">428</sup> אז ראה ויספרה<sup data-n=\"4540\">429</sup> כו' (וכמ\"ש במ\"א בענין מיילדות העבריות<sup data-n=\"4541\">430</sup> ). וגם התומ\"צ נק' בבחי' האדם כמ\"ש וזאת תורת האדם<sup data-n=\"4542\">431</sup> ושרשה בעצמו' אוא\"ס שלמעלה מבחי' אדם כו'. וזהו הטעם שבחי' דילוג העצמו' הנ\"ל ירד ונתלבש בבחי' חו\"ג דאו\"א שהוא ספר וסופר<sup data-n=\"4543\">432</sup> כו' שהוא בא <span data-k=\"pg\">272</span> ּ למטה בהתלבשות דמצה וד' כוסות דאורייתא ודרבנן שהן תושב\"כ ותושבע\"פ שנק' ספר וסיפו\"ר<sup data-n=\"4544\">433</sup>, כמ\"ש בג' דברים ברא<sup data-n=\"4545\">434</sup> בספר וסופר וסיפור<sup data-n=\"4546\">435</sup> וידוע דתושב\"כ באור אבא ותושבע\"פ באור אימא כמ\"ש שמע בני מוסר אביך<sup data-n=\"4547\">436</sup> ואל תטוש תורת אמך, ולהיות שאותיות דתושב\"כ ושבע\"פ קדמו לעולם<sup data-n=\"4548\">437</sup> הנאצל<sup data-n=\"4549\">438</sup> והנברא שלמעלה עדיין מציו\"ר אד\"ם, ע\"כ ירד האור דעצמו' ונתלבש במצה דאוריי', שהוא מצוה הא' שקיבלו ישראל אחר מצות הפסח, שמורה על עצם נקודת יהדותם באמונה פשוטה<sup data-n=\"4550\">439</sup> העצמי' ממש שכוללת ב' קוין דחו\"ג העצמי' כמו לחיות ולא למות כו', שמזה הי' מקור קבלת התורה פב\"פ בגדלות דאור אבא כנ\"ל שהוא להיות סו\"מ וע\"ט ע\"י הרצון והבחירה בדעת. וע\"כ נתלבשו בחי' חו\"ג העצמי' הללו בחו\"ג דעצמי' התושב\"כ ושבע\"פ כמו שהי' בשרשם בעצמו' א\"ס והן המצה וד' כוסות שהן חו\"ג דקטנות דאו\"א דוקא, ובשבועות נעשו בבחי' גדלות המוחין שהן שתי הלחם שהן תושב\"כ ושבע\"פ<sup data-n=\"4551\">440</sup> שנא' בהן חמץ תאפינה<sup data-n=\"4552\">441</sup> דוקא כמ\"ש הטעם במ\"א. ושרש הגדלות הזאת לא באה רק מבחי' הקטנות דמוחין דאו\"א שבמצה וד' כוסות שהוא ספר וסיפור כמו שהן בשרשן למעלה מבחי' א' דאדם כנ\"ל בענין בדמייך חיי בכנ\"י כך הוא בתור\"ת האד\"ם דתורה וד\"ל. ובזה יתורץ ג\"כ מ\"ש ויוציאנו ה' אלקינו ביד חזקה כו' דאין הכוונה על בחי' חו\"ג דאו\"א<sup data-n=\"4553\">442</sup> אלא [על] בחי' חו\"ג שבעצמות אוא\"ס ממש שלמעלה מראש וגלגלתא דא\"א כנ\"ל בפי' קחם על זרועותי\"ו כו' דרישא דמלכא בחו\"ג אתתקן כידוע בענין נשיאת כפים כו', וזה הכח הי' ע\"י בחי' חו\"ג דאו\"א<sup data-n=\"4554\">443</sup> [שבבחי' קטנות דמוחין דאו\"א] שבמצה וד' כוסות<sup data-n=\"4555\">444</sup> (והעיקר בדם שעל המשקוף וב' מזוזות שהוא בחי' חו\"ג",[["4537","426","<b>דג' קשרים הן</b>: נסמן לעיל ב, ד."],["4538","427","<b>זה ספר תולדות אדם</b>: בראשית ה, א."],["4539","428","<b>וכתי'</b>: בד: וכמ\"ש."],["4540","429","<b>אז ראה ויספרה</b>: איוב כח, כז."],["4541","430","<b>בענין מיילדות העבריות</b>: לעיל פ' שמות לב, א."],["4542","431","<b>וזאת תורת האדם</b>: נסמן לעיל מו, ב."],["4543","432","<b>ספר וסופר </b>[בד: וסיפור]: נסמן בהערה 434."],["4544","433","<b>תושב\"כ ותושבע\"פ שנק' ספר וסיפו\"ר</b>: נסמן לעיל ט, ג."],["4545","434","<b>בג' דברים ברא</b>: ראה ס\"י פ\"א, מ\"א."],["4546","435","<b>בספר וסופר וסיפור</b>: ב: בסופר וספ\"ר וסיפו\"ר [ראה גם לעיל פ' שמות יב, ד]. ד: העולם בספר וסיפור וסופר."],["4547","436","<b>שמע בני מוסר אביך</b>: ראה לעיל ט, ב הערה 411. צד, ד הערה 387."],["4548","437","<b>קדמו לעולם</b>: פסחים נד, א."],["4549","438","<b>קדמו לעולם הנאצל</b>: נסמן לעיל פ' וארא עט, ד."],["4550","439","<b>פשוטה</b>: בד: ליתא."],["4551","440","<b>שתי הלחם שהן תושב\"כ ושבע\"פ</b>: ראה השמטות לזח\"א רס, א."],["4552","441","<b>חמץ תאפינה</b>: אמור כג, יז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380355\" data-slug=\"likkutei-torah\" data-id=\"4001380355\">לקו\"ת במדבר יא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380375\" data-slug=\"likkutei-torah\" data-id=\"4001380375\">טז, ד</a>. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקלה ואילך. ע' תקמא. ע' תקמט. ע' תקנא. ע' תקפא ואילך. תקס\"ח ח\"א ס\"ע רלג ואילך. ע' רנג ואילך. שה\"א כג, א ואילך."],["4553","442","<b>דאו\"א</b>: בד: דא\"א."],["4554","443","<b>דאו\"א</b>: ב: דא\"א."],["4555","444","<b>וד' כוסות</b>: ד: וד\"ל."]]],[2300540770,"העצמי' שבאמונה הפשוטה העצמי' כמו שחבקוק העמידן על א'<sup data-n=\"4556\">445</sup> שהוא האמונה שצדיק באמונתו יחי'<sup data-n=\"4557\">446</sup> והוא המשקוף שע\"ג ב' המזוזות שבציור פת\"ח כנ\"ל). וז\"ש ויוציאנו ה' אלקינו שהוא תושב\"כ ושבע\"פ ביד חזקה משום דנעוץ תחלתן בסופן דוקא כנ\"ל וד\"ל.\n<b>והנה</b> מעתה י\"ל מהו ענין הד' כוסות שנתחברו עם מצות מצה דאורייתא כו', להיות שבחי' חסד<sup data-n=\"4558\">447</sup> דאור אבא (שזהו הא' הכלול כללו'<sup data-n=\"4559\">448</sup> רמ\"ח מ\"ע<sup data-n=\"4560\">449</sup> דחכ' דתורה) מתלבש במצה שנק' מיכלא דמהימנותא שהאמונה כוללת כל המצות והוא בבחי' חסד שבחכ' דוקא רק שהוא בבחי' הקטנות מאד והוא בחי' חטה דלח\"ם עני דמצה שהלחם בחכ'. אך במצה שאין בה טעם מורגש [ו]נק' לחמא עניא הוא בבחי' הקטנות דאור אבא כמשל התינוק שיודע לקרות אבא בלא שכל וטעם כנ\"ל, וענין הד' כוסות הוא בבחי' הקטנות דד' מוחין דאימא (שהוא תושבע\"פ דוקא וד\"ל<sup data-n=\"4561\">450</sup> ). דהנה ידוע דשרש היין הוא בבינה<sup data-n=\"4562\">451</sup> שהוא מקור הגבורה<sup data-n=\"4563\">452</sup> דקו השמאל כמ\"ש אני בינה לי גבורה<sup data-n=\"4564\">453</sup> כו', ובחי' החסדים שבבינה הוא יין המשמח את הלב וייטיב לבו ביין להשפיע כל טוב כו' ונכנס יין יצא סוד<sup data-n=\"4565\">454</sup> שזהו גילוי העלם הטוב הגנוז. וכן בענין השגות אלקות בנסתרות שנק' יינ\"ה של תורה<sup data-n=\"4566\">455</sup>, והשמח\"ה שביין הוא מ\"ש א\"ם הבנים שמחה<sup data-n=\"4567\">456</sup> כי אם לבינה תקרא<sup data-n=\"4568\">457</sup> כידוע שהוא בחי' גדלות המוחין דאימא, שהוא [השמחה] הנפלא' מעומק ההשגה האלקי' דפנימי' בינה כמו שאומרים שירה על היין<sup data-n=\"4569\">458</sup> דוקא לפי שהיין מוציא מן ההעלם לגילוי והוא ע\"י בחי' השמחה שביין דוקא שטבע השמחה להוציא <span data-k=\"pg\">קלו</span> ּ מן ההעלם לגילוי וזהו יין המשמ\"ח אלקים<sup data-n=\"4570\">459</sup> כו', ומזה יש שרש לגילוי סודות התורה כמו אגבר\"א חמר\"א אדרדק\"י<sup data-n=\"4571\">460</sup> כו' וכיין ישן לזקנים<sup data-n=\"4572\">461</sup> כו' כמ\"ש במ\"א<sup data-n=\"4573\">462</sup>, והוא בחי' יינ\"ה של תורה שבבחי' מוחין דגדלות דאימא [ב]תושבע\"פ שנק' תורת אמ\"ך כו' כמו שבמ\"ת הי' בחי' גדלות דמוחין דאבא בחכ' דתורה דחכמת אד\"ם תאיר פניו כו' (כמ\"ש במ\"א ע\"פ ויין ישמח לבב אנוש<sup data-n=\"4574\">463</sup> להצהיל פנים כו') והוא מ\"ש ומלכי צדק<sup data-n=\"4575\">464</sup> כו' הוציא לח\"ם ויי\"ן תושב\"כ ותושבע\"פ כו'.\n<b>והנה</b> כמו שבמצה נתלבש [מ]בחי' קטנות דחסד דאבא כנ\"ל, כך בד' כוסות דיין דפסח נתלבש מבחי' קטנות דמוחין דאימא דוקא מטעם הנ\"ל דבבחי' הקטנות דוקא שם [שוכן] בחי'",[["4556","445","<b>שחבקוק העמידן על א'</b>: מכות כד, א. ראה שה\"א ד, א. יא, א."],["4557","446","<b>שצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["4558","447","<b>חסד</b>: ד: חכ'."],["4559","448","<b>הא' הכלול כללו'</b>: ב: ה\"ח כוללים. ד: כלל הכולל."],["4560","449","<b>ה\"ח. . רמ\"ח מ\"ע</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב. הנסמן במאמרי אדה\"א נ\"ך ע' רלה. לקמן קיג, ד. פ' בשלח קלה, ג. קעא, א. תצוה שנה, א. תשא שפג, א."],["4561","450","<b>וד\"ל</b>: בד: כנ\"ל."],["4562","451","<b>היין הוא בבינה</b>: נסמן לעיל פ' וארא נ, א."],["4563","452","<b>בבינה. . הגבורה</b>: ראה פרדס (שעה\"כ) שכ\"ג, מערכת גבורה."],["4564","453","<b>אני בינה לי גבורה</b>: משלי ח, יד."],["4565","454","<b>ונכנס יין יצא סוד</b>: עירובין סה, סע\"א. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["4566","455","<b>יינ\"ה של תורה</b>: ע\"ז לה, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תקצא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670217\" data-slug=\"torat-chaim\" data-id=\"2300670217\">תו\"ח בראשית לו, ד</a> ובהערה 44. לקמן פ' יתרו רס, ג."],["4567","456","<b>א\"ם הבנים שמחה</b>: תהלים קיג, ט."],["4568","457","<b>כי אם לבינה תקרא</b>: נסמן לעיל פ' וארא סט, ב."],["4569","458","<b>שאומרים שירה על היין</b>: ברכות לה, א. ראה סידור ברכת נשואין קלו, סע\"ד."],["4570","459","<b>יין המשמ\"ח אלקים</b>: ע\"פ ס' שופטים ט, יג."],["4571","460","<b>אגבר\"א חמר\"א אדרדק\"י</b>: ראה סנהדרין לח, א. מאמרי אדה\"א בראשית ע' רפח. דברים ח\"ב ע' תקצא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a>."],["4572","461","<b>וכיין ישן לזקנים</b>: ראה מגילה טז, ב. מאמרי אדה\"א בראשית ע' רפט. וש\"נ."],["4573","462","<b>במ\"א</b>: ב: במ\"א). ואולי התחלת הסוגר הוא ב(שו\"ה וזהו) תיבת ומזה."],["4574","463","<b>ויין ישמח לבב אנוש</b>: תהלים קד, טו. ראה מאמרי אדה\"א נ\"ך ע' רסו ואילך. וש\"נ."],["4575","464","<b>ומלכי צדק</b>: לך יד, יח."]]],[2300540781,"אור העצמו' בחו\"ג שבו העצמי' כו' שלמעלה מבחי' אדם דגדלות (והוא מ\"ש בדמיי\"ך חיי דם הוא הנפש דקטנות דוקא בבחי' גבורה דאימא דקטנות). דהנה ידוע בענין קידוש על היין בשבת זהו מבחי' מוחין דאימא בבחי' הגדלות כנ\"ל בבחי' גילוי ההעלם דיין המשמח אלקי' וכה\"ג, וכן יין לקידוש ביו\"ט דמועדים לשמחה ביין המשמ\"ח דבינ\"ה כידוע, אבל כללות ענין ד' כוסות דיין דפסח הוא בחי' הקטנות דיין דבינה שמשמח בהשגה דגדלות כו'. וזהו כמו שנותנין יין לתינוק קטן שתשמח נפשו ולבו ודעתו כו' כחמרא לדרדקי שהתפעלות שמחתו ביין הוא בבחי' הקטנות להוציא כל העלם העצמי' וטבעי' שלו כמו שהוא בתולדה מבטן בלבד, והוא התלהבות [ב]רשפי אש תשוקתו אל אביו ואמו והעיקר בהיפוכו שלא יעזוב אביו ואמו במס\"נ ממש שזה נגלה בו ע\"י היין המשמח כו', והוא בחי' גבורה דיין שבקטנות דוקא, וכידוע דבינה מינה דינין מתערין בסופה<sup data-n=\"4576\">465</sup> והוא על המנגד לרצונו כו', וזהו בחי' קו השמאל דבג\"ה. ובבחי' הקטנות היינו כמו בחי' גבורה דרשפי אש התקשרות של התינוק לאביו ואמו בשמחתו ביין בלתי יסור מהם בשום דבר המנגד כו'. וכן ענין היין למרי נפש<sup data-n=\"4577\">466</sup> ש[י]שמח מאד בעצם מהותו שהורם משפלותו וישכח עני ומרת נפשו כו' שזהו שמחת עצמי' הנפש יותר משמחת היין בבחי' גדלות המוחין הנ\"ל. וכמו\"כ ביצ\"מ שהיו מר\"י נפ\"ש בעצם כמ\"ש וימררו את חייה\"ם<sup data-n=\"4578\">467</sup> בעבודה קשה כו' חייה\"ם דכנ\"י, וע\"כ ניתן להם מצות ד' כוסות אפי' לעני שבישראל עני מן הדעת<sup data-n=\"4579\">468</sup> לשמח מרי נפש והיינו לשמח נפשם באלקי' חיים שיצאו מאפילה לאור גדול<sup data-n=\"4580\">469</sup>, כמו הבע\"ת או הגר שמפני שהי' מושקע ברע גמור [ע]\"כ כשיוצא מן הרע והתחיל להיות עובד ה' תגדל בו רשפי אש [השמחה] יותר משמחת הצדיקים גמורים באה\"ר בתענוגי'. וזהו שמחה שבבחי' הקטנות מבחי' גבור[ו'] דקטנות דבינה שהוא ביין, והוא ענין ד' כוסות דפסח שהן בחי' ד' מוחין דאימא כמו שהן בבחי' הקטנות דוקא ששם הוא עיקר בחי' העצמי' וטבעי' כמו שבאמונה העצמי' דמצה שם הוא עיקר עצמי' ההתקשרות רק שהוא בבחי' קטנות החסד דאבא וד' כוסות הוא בקטנות דגבורה דאימא, והן בחי' חו\"ג העצמי' כנ\"ל כמו לחיות ולא למות בכלל שזהו תושב\"כ ותושבע\"פ כמו שהן בשרשן למעלה מבחי' אד\"ם דגדלות, [ו]כידוע דעיקר תושבע\"פ הוא היראה<sup data-n=\"4581\">470</sup> כו' והיינו ענין סו\"מ וע\"ט בעצם שהן ב' המזוזות כנ\"ל וד\"ל.",[["4576","465","<b>דבינה מינה דינין מתערין בסופה</b>: נסמן לעיל פ' וארא פה, ג."],["4577","466","<b>היין למרי נפש</b>: משלי לא, ו."],["4578","467","<b>וימררו את חייהם</b>: שמות א, יד."],["4579","468","<b>עני מן הדעת</b>: ראה כתובות סח, א. נדרים מא, א."],["4580","469","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגש\"פ פיסקא לפיכך."],["4581","470","<b>תושבע\"פ הוא היראה</b>: ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' ל. מאמרי אדה\"א בראשית ע' ב וע' לב ואילך."]]],[2300540792,"ונמצא [מובן] דבחי' קטנות דחו\"ג דאו\"א דתושב\"כ ושבע\"פ חסד דאבא מתלבש במצה דאורייתא וגבורה דאימא דמינה דינין מתערין בד' כוסות נתלבש<sup data-n=\"4582\">471</sup> במל' כשהיא בבחי' הקטנות הא לחמא<sup data-n=\"4583\">472</sup> כו', וע\"י המצה <span data-k=\"pg\">274</span> ּ והכוסות הן בחי' הכלים שבמל' המלבישים ומכילים לעצמו' אוא\"ס הבא בבחי' דילוג הנ\"ל וד\"ל. וזהו [ש]אחר שאומר פסח זה<sup data-n=\"4584\">473</sup> כו' ע\"ש שפסח הוי' כו' אומר<sup data-n=\"4585\">474</sup> מצה זו שאנו אוכלים על שום שלא כו' עד שנגלה עליהם מלך כו' הקב\"ה בכבודו ובעצמו<sup data-n=\"4586\">*475</sup> כו', דהנה מבואר לעיל בענין הדם שראה על המשקוף כו' שזהו למעלה מבחי' א' דאד\"ם שהוא החכ' בבחי' הגדלות, ואמנם הד\"ם שהוא בבחי' הקטנות חסר בו הא' להיות[ו] בבחי' עצמי' הנפש דבחי' יחידה טרם שבא לבחי' רצון וחכ', וז\"ש בדמיי\"ך [חיי] דוקא כו'. וזהו שמזכירין יצ\"מ גם לעוה\"ב שנא' כל ימי חייך<sup data-n=\"4587\">475</sup> כו' לפי שבחי' הקטנות דאו\"א שבמצה [ו]פסח [ב]ד\"ם שע\"ג המשקוף כו' [י]תעלה לע\"ל יותר מבחי' הגדלות דמ\"ת וכמ\"ש יחיינ\"ו מיומי\"ם שזהו בחי' גדלות המוחין דאו\"א בתושב\"כ ושבע\"פ<sup data-n=\"4588\">476</sup> במ\"ת, יקימנו ונחי' לפניו בעוה\"ב שיהי' מעלי' דקטנות דפסח דוקא מטעם הנ\"ל וד\"ל. וז\"ש כימי צאתך<sup data-n=\"4589\">477</sup> מאמ\"צ דוקא אראנו נפלאות שהוא מ\"ש אהי' אשר אהי' בעוה\"ב, והן ב' עליות דימוהמ\"ש ועוה\"ב, דעלי' דמשיח הוא בבחי' ג\"ר דע\"י<sup data-n=\"4590\">478</sup> ובעוה\"ב במהו\"ע ית' ממש שנק' סדכ\"ס, וזהו אראנו נפלאות ב' מדרגות בהעלם העצמו' שנק' פל\"א למעלה מאל\"ף דאד\"ם כידוע וד\"ל. וזהו רק מבחי' קטנות דפסח דוקא כמ\"ש כימי כו', וזהו שאו' מצה זו כו' עד שנגלה עליהם [כו'] בכבוד\"ו ובעצמ\"ו, פי' בכבודו הוא בחי' כבודו העצמי' שירד בבחי' דילוג חסד דהוי' דז\"א שיהי'<sup data-n=\"4591\">479</sup> בבחי' קטנות דחסד דאבא [ש]בז\"א, ובעצמו הוא מלשון עצמות[\"ו] שז\"ש בבנין המל' זאת הפעם עצם מעצמי לזאת יקרא אשה כי מאיש לוקחה זאת והוא בחי' תושבע\"פ<sup data-n=\"4592\">480</sup> [מל'] קרינן לה<sup data-n=\"4593\">481</sup> שבנינה מגבורות וחסדים דאבא ואימא דקטנות כנ\"ל וכמ\"ש ויבן ה' אלקים",[["4582","471","<b>נתלבש</b>: בד: והכל."],["4583","472","<b>הא לחמא</b>: נוסח הגש\"פ."],["4584","473","<b>פסח זה</b>: ראה לעיל הערה 388."],["4585","474","<b>אומר</b>: בד: ליתא."],["4586","*475","<b>הקב\"ה בכבודו ובעצמו</b>: לשון הגש\"פ בפיסקא ויוציאנו. וראה גם לקמן קט, ג."],["4587","475","<b>שמזכירין. . כל ימי חייך</b>: נסמן לקמן קיא, ד הערה 617."],["4588","476","<b>יחיינ\"ו מיומי\"ם. . בתושב\"כ ושבע\"פ</b>: ראה גם לקמן פ' משפטים שא, ג. שע\"ת סח, סע\"ד ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670237\" data-slug=\"torat-chaim\" data-id=\"2300670237\">תו\"ח לך צו, ג</a> ובהערה 29."],["4589","477","<b>כימי צאתך. . נפלאות</b>: מיכה ז, טו. ראה גם לעיל פ' שמות כא, א. וש\"נ. מאמרי אדה\"א דברים ח\"א ע' טז."],["4590","478","<b>דמשיח. . ג\"ר דע\"י</b>: נסמן לעיל פ' שמות מח, ד."],["4591","479","<b>שיהי'</b>: בד: שזהו."],["4592","480","<b>זאת הפעם עצם מעצמי. . תושבע\"פ</b>: בראשית ב, כג [בדילוג]. ראה גם לקמן פ' ויקהל תטז, ג. מאמרי אדה\"א במדבר ח\"ג ע' תתקעה."],["4593","481","<b>תושבע\"פ [מל'] קרינן לה</b>: ת\"ז בהקדמה (יז, א)."]]],[2300540802,"את הצל\"ע כו' כנ\"ל, וז\"ש וה' הכה [כל בכור] הוא וב\"ד דוקא כו' וד\"ל."],[2300540062,"<b>ביאור בענין פסח ומצה מאדמו\"ר שי'</b>\n<span data-k=\"pg\">370</span> ּ<b>להבין</b> שרש ענין פסח ומצה<sup data-n=\"4594\">1</sup>, הנה תחלה יש להקדים בשרש ענין ההשתלשלו' בכלל בע\"ס דאצי' שהן מקור לג' עולמות בי\"ע כידוע במא' אפיקת י' תיקונין<sup data-n=\"4595\">2</sup> וקרית לון י\"ס כו' רק לאחזאה<sup data-n=\"4596\">3</sup> לאתנהגא בהון עלמין כו', דהגם שע\"ס דאצי' נק' מקור ממש לעולמות הנבראי' בע\"ג ותכלית, מ\"מ אין ערך כלל וכלל לבריאה עם בחי' אור האצי'<sup data-n=\"4597\">4</sup> עצמו אע\"פ שנתצמצם אור דאצי' בכלים מכלים שונים (פנימי אמצעי חיצון<sup data-n=\"4598\">5</sup> כו'), ורק מחיצוניות דחיצוניות הכלים דז\"א מאיר ונמשך במל', ומבחי' המל' בבי\"ע נמשך ג\"כ [ב]צמצום והעלם דמסך המפסיק בין האצי' לבריאה<sup data-n=\"4599\">6</sup> כו' שהרי א' דאיהו וחיוהי וגרמוהי חד<sup data-n=\"4600\">7</sup> שהן או\"כ דאצי' חד ממש ביחו\"ע דעצמות המאציל שהוא בבחי' הא\"ס ממש ולז\"א א\"א לומר<sup data-n=\"4601\">8</sup> בגילוי אור דאצי' בבי\"ע אפי' רק בבחי' הארה דהארה בריבוי הצמצומי' והעלמות שאין זה ממהות ועצמות דאורות האצי' ממש רק בבחי' התגלות מציאות[ן] לבד ולא מהות[ן] ממש (וביאור הפרש זה בין מציאות למהות ית' בסמוך כו'). ועוד יש להבין מ\"ש בזהר [ד]בחי' המל' דאצי' דלית לה מגרמה כלום<sup data-n=\"4602\">9</sup> כו' [כ]אור הלבנה כו' ונק' אספקלריא דלא נהרא<sup data-n=\"4603\">10</sup> כו' (והוא מ\"ש ה'<sup data-n=\"4604\">11</sup> במראה אליו<sup data-n=\"4605\">12</sup> כו' ונק' מראה דמות כבוד ה'<sup data-n=\"4606\">13</sup> כו'). והנה ביאור ענין בחי' מדת המל' למעלה ידוע",[["4594","1","<b>להבין שרש ענין פסח ומצה</b>: מיוסד על ד\"ה לה\"ע פסח ומצה תקס\"ג הנחת כ\"ק אדה\"א נדפסה במאמרי אדה\"ז תקס\"ג ח\"א ע' רפד (וקיצורים מהצ\"צ שם ע' תט). הנחת הר\"מ בן כ\"ק אדה\"ז נמצאת במאמרי אדה\"ז שם ע' רעז ופתיחתה: להבין מ\"ד מלכותך מלכות כל עולמי' (ובראשה נרשם תאריך אור ליום ד' פ' צו). ראה (ד\"ה ואמרתם זבח פסח) מאמרי אדה\"א ויקרא ח\"א ע' לה ואילך. הנחות תקע\"ז ע' כא ואילך. (ד\"ה עבדים היינו) שם ע' כז ואילך ובהנסמן בכל הנ\"ל. וראה עוד ע\"ד המאמר להלן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["4595","2","<b>אפיקת י' תיקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["4596","3","<b>לאחזאה</b>: ראה שם (יז, ב)."],["4597","4","<b>אין ערך. . לבריאה עם. . האצי'</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' רפד. וש\"נ. קונטרסים ע' תקלח. לקמן פ' בשלח קמא, ג והערה 14. רמ, ג. ויקהל תד, ד."],["4598","5","<b>בכלים. . פנימי אמצעי חיצון</b>: ראה ע\"ח (שער המוחין) ש\"כ, פ\"ה."],["4599","6","<b>דמסך. . בין האצי' לבריאה</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב, פ\"ד. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["4600","7","<b>דאיהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה (ג, ב). ראה גם מאמרי אדה\"ז על מארז\"ל ע' רצב (כמא' אליהו ז\"ל). מאמרי אדה\"א ויקרא ח\"ב ע' תנג בהערה."],["4601","8","<b>ולז\"א. . לומר</b>: אבגד: ולזאת. . ג: להיות. ד: מחק תיבת לומר וממעל כתב תיבת להיות."],["4602","9","<b>המל'. . דלית לה מגרמה כלום</b>: נסמן לעיל פ' וארא נה, ג."],["4603","10","<b>המל'. . אספקלריא דלא נהרא</b>: זהר בראשית לג, ב. פרדס (שער מיעוט הירח) שי\"ח, פ\"א (בס' מאירת עינים בהקדמה — כב, ב). (שעה\"כ) שכ\"ג מערכת אספקלריא."],["4604","11","<b>ה'</b>: אב: הן — ראה לקמן צז, ד. מאמרי אדה\"א נ\"ך ע' קמב. וש\"נ. שע\"ת קז, ג הערה 11."],["4605","12","<b>ה' במראה אליו</b>: בהעלותך יב, ו."],["4606","13","<b>מראה דמות כבוד ה'</b>: נסמן לעיל פח, ב."]]],[2300540100,"שזהו בא ממדת מל' דאצי' [ו]מאצי' לבי\"ע ע\"י צמצום ולבוש דוקא כמ\"ש ה' מלך גאות לבש<sup data-n=\"4607\">14</sup> שכדי שיהי' בבחי' גאות והתנשאות על העולמות להיות מלך על עם כו' זהו דוקא ע\"י ש[מ]תצמצם בעצמו ע\"י לבוש ומסך המעלים אור העצמות, כי מצד אור העצמות דאצי' הרי אין הבריאה בע\"ג ערוך לו כלל וכלל, וגם אין עוד מלבדו<sup data-n=\"4608\">15</sup> כו' שלא יתכן שם לומר בבחי' התנשאות על זולתו ונק' מלך [ה]מרומם לבדו<sup data-n=\"4609\">16</sup> כו', וכמ\"ש נכון כסאך מאז<sup data-n=\"4610\">17</sup> כו', ולזאת מה שנק' מלך על עם נפרד בחי' ב\"ג נק' אספקלריא דלא נהרא כו' ולית לה מגרמה כלום כו' וד\"ל.\n<b>וביאור</b> הענין הנה מה שא' דלית לה מגרמה כלום יש בזה ב' פי'<sup data-n=\"4611\">18</sup>, הא' דלית לה אור מצד עצמה רק מה שמקבלת מן המשפיע כמו הלבנה שאין לה אור עצמי<sup data-n=\"4612\">19</sup> כ\"א מה שמקבלת אור מן השמש כעני [ודל] דלית לי' מגרמי' כלום רק מה שנותני' לו [ה]עשירים וגומלי חסדים כו', ופי' הב' דלית לה מג\"כ כ\"א מה שמקבלת מלמטה למעלה ע\"י העלאת מ\"ן ממלאכים ונשמות דבי\"ע. והענין הוא, דב' הפי' אמת להיות שבאמת אין ערוך כלל לנברא עם הבורא<sup data-n=\"4613\">20</sup> ית' וכדי שירצה ברצון להיות מלך על עם צריך להיות ע\"י צמצום גדול כנ\"ל, ואמנם יש בזה ב' סיבות הא' מלמעלה למטה, והוא שיומשך מעצמות כח החסד שבחכ' ומדות עליונות דז\"א דאצי' כמ\"ש והוכן בחסד כסאך<sup data-n=\"4614\">21</sup> דבנין המל' מבחי' החסדי' דאו\"א וז\"א כו' שעי\"ז יעלה ברצונו לצמצם א\"ע להיות מלך גאות לבש כו' כנ\"ל, והיינו מה שמצמצם א\"ע מבחי' ההתנשאות בעצם דמדת מל' דאצי' למעלה בבחי' האצי' (כמו [שיש] מדה [זאת] דהתנשאות בעצם מצד בחי' אדם רק שאינו בבחי' התפשטות וגילוי כמו [ה]התנשאות על זולתו<sup data-n=\"4615\">22</sup> כידוע ומבואר במ\"א) להיות בבחי' התנשאות על העולמות, כמו שאו' אדון עולם<sup data-n=\"4616\">23</sup> אשר מלך בטרם כל יצור נברא שזהו מלך המרומם לבדו מאז בבחי' <span data-k=\"pg\">קפה</span> ּ התנשאות העצמי' כנ\"ל ולעת נעשה בחפצו ורצונו כל העולמות אזי נקרא שמו מלך על עם נפרד שזהו המתנשא מימו\"ע לבד שאין ערוך כלל ביניהם כנ\"ל, ועכ\"ז מתצמצם בעצמו ע\"י מדות דחכ' ורצון העליון שמשפיעי' למדה זו דבחי' המל' מלמעלה למטה דוקא כו' וד\"ל. ודוגמא לזה מה שאומרים י\"פ דמלכיות בר\"ה<sup data-n=\"4617\">24</sup> שמביאים ראי' מתנ\"ך שנא' שם בחי' המל' כמו ה' ימלוך לע\"ו<sup data-n=\"4618\">25</sup> וכה\"ג בכתובים ו[ב]נביאים כדי שעי\"ז יומשך מח\"ע דתורה ש\"מ למדות דז\"א להיות רצונו למלוכה זאת שנק' כתר מל' דאצי' שמכתירים אותו מלמעלה",[["4607","14","<b>ה' מלך גאות לבש</b>: נסמן לעיל פ' וארא עה, א."],["4608","15","<b>אין עוד מלבדו</b>: ואתחנן ד, לה."],["4609","16","<b>מלך [ה]מרומם לבדו</b>: ע\"פ ברכת יוצר."],["4610","17","<b>נכון כסאך מאז</b>: תהלים צג, ב."],["4611","18","<b>ב' פי'</b>: ראה בהדרושים שבהערה 1."],["4612","19","<b>הלבנה שאין לה אור עצמי</b>: ראה לקמן הערה 43."],["4613","20","<b>לנברא עם הבורא</b>: אב: בין הנברא לבורא."],["4614","21","<b>והוכן בחסד כסאך</b>: נסמן לעיל צד, ד."],["4615","22","<b>דהתנשאות. . כמו [ה]התנשאות על זולתו</b>: ראה גם שעה\"י קמב, ב. פיה\"מ פט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670567\" data-slug=\"torat-chaim\" data-id=\"2300670567\">תו\"ח נח עה, א</a>."],["4616","23","<b>כמו </b>[ט: וכמו]<b> שאו' אדון עולם</b>: בתפלת השחר."],["4617","24","<b>שאומרים י\"פ דמלכיות בר\"ה</b>: במוסף. ר\"ה לב, א (במשנה). ראה סידור תפלת ר\"ה רלח, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שס־ נ\"ך ע' תקב."],["4618","25","<b>ה' ימלוך לע\"ו</b>: בשלח טו, יח."]]]]});
